-- Asuncion production baseline for Supabase project veepwacsdbqnzkblxbiu.
-- Review against application commit 04553b8. This file contains no imported rows or credentials.
BEGIN;
SET LOCAL search_path = pg_catalog, public;
SET LOCAL check_function_bodies = off;

DO $baseline$
BEGIN
    IF EXISTS (
        SELECT FROM pg_class
        WHERE relnamespace = 'public'::regnamespace
          AND relkind IN ('r', 'p', 'S', 'v', 'm', 'f')
    ) THEN
        RAISE EXCEPTION 'Asuncion baseline requires an empty public relation namespace';
    END IF;
END
$baseline$;

CREATE ROLE psms_account_manager_owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
CREATE ROLE psms_aoq_approval_owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
CREATE ROLE psms_aoq_function_owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
CREATE ROLE psms_recovery_owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
CREATE ROLE psms_vercel_backend NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
-- Permit the migration operator to transfer ownership and verify the server role.
GRANT psms_account_manager_owner TO CURRENT_USER WITH SET TRUE;
GRANT psms_aoq_approval_owner TO CURRENT_USER WITH SET TRUE;
GRANT psms_aoq_function_owner TO CURRENT_USER WITH SET TRUE;
GRANT psms_recovery_owner TO CURRENT_USER WITH SET TRUE;
GRANT psms_vercel_backend TO CURRENT_USER WITH SET TRUE;

CREATE SCHEMA psms_accounts;
CREATE SCHEMA psms_aoq_api;
CREATE SCHEMA psms_documents;
CREATE SCHEMA psms_revised_release;
CREATE SCHEMA psms_signatories;
CREATE SCHEMA psms_sync;
CREATE SCHEMA psms_workbooks;

