-- public routines
CREATE OR REPLACE FUNCTION public.psms_auth_session_permissions_ready()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare registry record; policy record;
  allow_select boolean:=false; allow_insert boolean:=false; allow_update boolean:=false;
begin
  select c.oid,c.relowner,c.relrowsecurity,c.relforcerowsecurity into registry
    from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public' and c.relname='auth_sessions' and c.relkind='r';
  if not found or not registry.relrowsecurity then return false; end if;
  if not pg_catalog.has_table_privilege(current_user,registry.oid,'SELECT')
    or not pg_catalog.has_column_privilege(current_user,registry.oid,'token_hash','INSERT')
    or not pg_catalog.has_column_privilege(current_user,registry.oid,'user_id','INSERT')
    or not pg_catalog.has_column_privilege(current_user,registry.oid,'expires_at','INSERT')
    or not pg_catalog.has_column_privilege(current_user,registry.oid,'revoked_at','UPDATE') then return false; end if;
  if exists(select 1 from pg_catalog.pg_trigger where tgrelid=registry.oid
      and not tgisinternal and tgenabled in ('O','A')) then return false; end if;
  if not exists(
    select 1 from pg_catalog.pg_trigger t
    join pg_catalog.pg_class c on c.oid=t.tgrelid
    join pg_catalog.pg_namespace n on n.oid=c.relnamespace
    join pg_catalog.pg_proc p on p.oid=t.tgfoid
    join pg_catalog.pg_namespace pn on pn.oid=p.pronamespace
    where n.nspname='public' and c.relname='users' and t.tgname='psms_revoke_auth_sessions_on_account_change'
      and t.tgtype=17 and not t.tgisinternal and t.tgenabled in ('O','A')
      and pn.nspname='public' and p.proname='psms_revoke_auth_sessions' and not p.prosecdef
      and p.proconfig @> array['search_path=pg_catalog']
      and pg_catalog.md5(p.prosrc)='4c191348c92c7372785deded3c74e91c'
      and (select array_agg(a.attname::text order by a.attname) from pg_catalog.pg_attribute a
           where a.attrelid=c.oid and a.attnum=any(t.tgattr))=array['password','status']
  ) then return false; end if;
  -- Compatibility for the existing table-owner connection, without new bypass grants.
  if pg_catalog.pg_has_role(current_user,registry.relowner,'USAGE') and not registry.relforcerowsecurity then return true; end if;
  -- Narrow supported contract: full registry visibility/modification for the
  -- trusted server SQL role only, no applicable restrictive/filtering policies.
  for policy in
    select p.*,pg_catalog.pg_get_expr(p.polqual,p.polrelid) as using_expr,
      pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid) as check_expr
    from pg_catalog.pg_policy p where p.polrelid=registry.oid
      and (0=any(p.polroles) or exists(select 1 from unnest(p.polroles) r
            where case when r=0 then false else pg_catalog.pg_has_role(current_user,r,'USAGE') end))
  loop
    if not policy.polpermissive then return false; end if;
    -- PUBLIC policies never establish the trusted-role permission contract.
    if not exists(select 1 from unnest(policy.polroles) r
          where case when r=0 then false else pg_catalog.pg_has_role(current_user,r,'USAGE') end) then continue; end if;
    if policy.polcmd in ('r','*') and policy.using_expr='true' then allow_select:=true; end if;
    if policy.polcmd in ('a','*') and coalesce(policy.check_expr,policy.using_expr)='true' then allow_insert:=true; end if;
    if policy.polcmd in ('w','*') and policy.using_expr='true'
       and coalesce(policy.check_expr,policy.using_expr)='true' then allow_update:=true; end if;
  end loop;
  return allow_select and allow_insert and allow_update;
end;
$function$;

CREATE OR REPLACE FUNCTION public.psms_revoke_auth_sessions()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare expected_count bigint; revoked_count bigint;
begin
  -- phase5c-atomic-revocation-v1
  if new.password is distinct from old.password or new.status is distinct from old.status then
    if not public.psms_auth_session_permissions_ready() then
      raise exception 'Session revocation permissions are unavailable' using errcode='42501';
    end if;
    -- User row locking serializes login; lock existing sessions consistently.
    perform token_hash from public.auth_sessions where user_id=new.id and revoked_at is null
      order by token_hash for update;
    select count(*) into expected_count from public.auth_sessions where user_id=new.id and revoked_at is null;
    update public.auth_sessions set revoked_at=clock_timestamp() where user_id=new.id and revoked_at is null;
    get diagnostics revoked_count = row_count;
    if revoked_count <> expected_count or exists(
        select 1 from public.auth_sessions where user_id=new.id and revoked_at is null) then
      raise exception 'Session revocation could not be confirmed' using errcode='42501';
    end if;
  end if;
  return new;
end;
$function$;

-- psms_accounts routines
CREATE OR REPLACE FUNCTION psms_accounts.change_own_password_v1(expected_hash text, new_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor bigint; employee record;
BEGIN
 actor:=psms_accounts.recovery_actor_v1();
 SELECT id,username,password INTO employee FROM public.users WHERE id=actor FOR UPDATE;
 IF expected_hash IS NULL OR expected_hash IS DISTINCT FROM employee.password OR new_hash IS NULL OR length(new_hash)>1024
  OR new_hash !~ '^(scrypt:32768:8:1\$[A-Za-z0-9]{8,64}\$[0-9a-f]{128}|pbkdf2:sha256:(600000|1000000)\$[A-Za-z0-9]{8,64}\$[0-9a-f]{64})$' THEN
  RAISE EXCEPTION 'Verified current credential and supported new hash required' USING ERRCODE='42501'; END IF;
 IF public.psms_auth_session_permissions_ready() IS DISTINCT FROM true THEN RAISE EXCEPTION 'Session contract unavailable'; END IF;
 UPDATE public.users SET password=new_hash WHERE id=actor;
 IF EXISTS(SELECT 1 FROM public.auth_sessions WHERE user_id=actor AND revoked_at IS NULL) THEN
  RAISE EXCEPTION 'Session revocation failed'; END IF;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(clock_timestamp() AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),employee.username,
  'Password Changed','Account',actor::text,'Current-password confirmation; all sessions revoked');
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.create_user_v1(new_username text, new_hash text, new_role text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor record; new_id bigint;
BEGIN
 SELECT * INTO STRICT actor FROM psms_accounts.require_admin_v1();
 IF new_username IS NULL OR length(new_username) NOT BETWEEN 3 AND 80
    OR new_username<>btrim(new_username) OR new_username ~ '[[:cntrl:]]'
    OR new_role IS NULL OR new_role NOT IN ('Staff','Inspector') OR new_hash IS NULL
    OR length(new_hash)>1024
    OR new_hash !~ '^(scrypt:32768:8:1\$[A-Za-z0-9]{8,64}\$[0-9a-f]{128}|pbkdf2:sha256:(600000|1000000)\$[A-Za-z0-9]{8,64}\$[0-9a-f]{64})$' THEN
   RAISE EXCEPTION 'Validated username, role and supported password hash required' USING ERRCODE='22023';
 END IF;
 INSERT INTO public.users(username,password,role,status,created_at)
 VALUES(new_username,new_hash,new_role,'Active',to_char(clock_timestamp() AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'))
 RETURNING id INTO new_id;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(clock_timestamp() AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),
        actor.actor_name,'Created User','User Management',new_username,'Role: '||new_role);
 RETURN new_id;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.deactivate_user_v1(target_id bigint, reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor record; target record; changed bigint;
BEGIN
 SELECT * INTO STRICT actor FROM psms_accounts.require_admin_v1();
 IF target_id IS NULL OR target_id<=0 OR target_id=actor.actor_id OR reason IS NULL
    OR length(btrim(reason)) NOT BETWEEN 10 AND 500 THEN
   RAISE EXCEPTION 'Employee and documented reason required' USING ERRCODE='22023';
 END IF;
 SELECT id,username,role,status INTO target FROM public.users WHERE id=target_id FOR UPDATE;
 IF NOT FOUND OR target.role IS NULL OR target.role NOT IN ('Staff','Inspector')
    OR target.status IS DISTINCT FROM 'Active' THEN
   RAISE EXCEPTION 'Active employee required; administrator changes prohibited' USING ERRCODE='42501';
 END IF;
 UPDATE public.users SET status='Inactive' WHERE id=target_id AND status='Active';
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>1 OR EXISTS(SELECT 1 FROM public.auth_sessions WHERE user_id=target_id AND revoked_at IS NULL) THEN
   RAISE EXCEPTION 'Deactivation and session revocation unconfirmed' USING ERRCODE='42501';
 END IF;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(clock_timestamp() AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),
        actor.actor_name,'Deactivated User','User Management',target.username,btrim(reason));
 RETURN true;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.otp_budget_v1(key text, cap integer, seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE hits integer; stamp timestamptz:=clock_timestamp();
BEGIN
 INSERT INTO psms_accounts.otp_limits(bucket,started,attempts) VALUES(key,stamp,1)
 ON CONFLICT(bucket) DO UPDATE SET
  attempts=CASE WHEN otp_limits.started<=stamp-make_interval(secs=>seconds) THEN 1 ELSE least(otp_limits.attempts+1,cap+1) END,
  started=CASE WHEN otp_limits.started<=stamp-make_interval(secs=>seconds) THEN stamp ELSE otp_limits.started END
 RETURNING attempts INTO hits;
 RETURN hits<=cap;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.otp_consume_v1(challenge text, purpose text, proof text, new_hash text, peer text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE target bigint; actor bigint; employee record; address record; ticket record; stamp timestamptz; key text;
BEGIN
 IF challenge IS NULL OR challenge !~ '^[0-9a-f]{64}$' OR peer IS NULL OR peer !~ '^[0-9a-f]{64}$'
  OR proof IS NULL OR proof !~ '^[0-9a-f]{64}$' OR purpose IS NULL OR purpose NOT IN ('activate','verify','forgot','change') THEN RETURN NULL; END IF;
 IF NOT psms_accounts.otp_budget_v1('consume-peer:'||peer,30,900) THEN RETURN NULL; END IF;
 SELECT user_id INTO target FROM psms_accounts.otp_challenges WHERE challenge_id=challenge;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF purpose='change' THEN actor:=psms_accounts.recovery_actor_v1();IF actor<>target THEN RAISE EXCEPTION 'Own account only' USING ERRCODE='42501';END IF;END IF;
 SELECT id,username,password,role,status INTO employee FROM public.users WHERE id=target FOR UPDATE;
 SELECT * INTO address FROM psms_accounts.recovery_emails WHERE user_id=target FOR UPDATE;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO ticket FROM psms_accounts.otp_challenges WHERE challenge_id=challenge FOR UPDATE;
 IF NOT FOUND OR ticket.kind<>purpose OR ticket.consumed_at IS NOT NULL OR ticket.wrong_attempts>=2
  OR ticket.expires_at<=clock_timestamp() OR ticket.delivery_status<>'accepted'
  OR ticket.email IS DISTINCT FROM address.email OR ticket.email_revision IS DISTINCT FROM address.revision
  OR ticket.credential_tag IS DISTINCT FROM encode(sha256(convert_to(employee.password,'UTF8')),'hex') THEN RETURN NULL; END IF;
 IF purpose='activate' THEN
  IF employee.status<>'Inactive' OR NOT EXISTS(SELECT 1 FROM psms_accounts.otp_enrollments WHERE user_id=target AND pending) THEN RETURN NULL; END IF;
 ELSIF employee.status<>'Active' OR (purpose IN ('forgot','change') AND address.verified_at IS NULL) THEN RETURN NULL; END IF;
 IF purpose<>'verify' AND (new_hash IS NULL OR length(new_hash)>1024 OR new_hash !~ '^(scrypt:32768:8:1\$[A-Za-z0-9]{8,64}\$[0-9a-f]{128}|pbkdf2:sha256:(600000|1000000)\$[A-Za-z0-9]{8,64}\$[0-9a-f]{64})$') THEN RETURN NULL; END IF;
 stamp:=clock_timestamp();
 IF ticket.code_mac IS DISTINCT FROM proof THEN
  UPDATE psms_accounts.otp_challenges SET wrong_attempts=wrong_attempts+1,
   consumed_at=CASE WHEN wrong_attempts+1>=2 THEN stamp ELSE NULL END WHERE challenge_id=challenge;
  RETURN NULL; -- Persist this result: do NOT raise/roll back the attempt count.
 END IF;
 key:=address.mailbox_key;PERFORM pg_advisory_xact_lock(hashtextextended(key,0));
 IF EXISTS(SELECT 1 FROM psms_accounts.recovery_emails WHERE mailbox_key=key AND user_id<>target AND verified_at IS NOT NULL) THEN RETURN NULL; END IF;
 IF purpose IN ('activate','verify') THEN UPDATE psms_accounts.recovery_emails SET verified_at=stamp WHERE user_id=target;END IF;
 IF purpose<>'verify' THEN
  IF public.psms_auth_session_permissions_ready() IS DISTINCT FROM true THEN RAISE EXCEPTION 'Session readiness unavailable'; END IF;
  UPDATE public.users SET password=new_hash,status=CASE WHEN purpose='activate' THEN 'Active' ELSE status END WHERE id=target;
  IF EXISTS(SELECT 1 FROM public.auth_sessions WHERE user_id=target AND revoked_at IS NULL) THEN RAISE EXCEPTION 'Session revocation failed'; END IF;
  IF purpose='activate' THEN UPDATE psms_accounts.otp_enrollments SET pending=false WHERE user_id=target;END IF;
 END IF;
 UPDATE psms_accounts.otp_challenges SET consumed_at=stamp,success=(challenge_id=challenge) WHERE user_id=target AND consumed_at IS NULL;
 UPDATE psms_accounts.recovery_tokens SET consumed_at=stamp WHERE user_id=target AND consumed_at IS NULL;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(stamp::text,employee.username,CASE WHEN purpose='verify' THEN 'Gmail OTP Verified' ELSE 'OTP Password Changed' END,'Account',target::text,purpose||'; single-use code; no automatic login');
 RETURN jsonb_build_object('success',true,'email',address.email);
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.otp_create_employee_v1(name text, credential text, employee_role text, address text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE target bigint;
BEGIN
 -- Only this wrapper can call enrollment. It always creates a NEW employee.
 -- Inactive status and private enrollment commit atomically with account/audit.
 target:=psms_accounts.create_user_v1(name,credential,employee_role);
 UPDATE public.users SET status='Inactive' WHERE id=target;
 PERFORM psms_accounts.otp_enroll_v1(target,address);
 RETURN target;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.otp_delivery_v1(challenge text, outcome text, message text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 IF outcome IS NULL OR outcome NOT IN ('accepted','failed','unknown') OR length(coalesce(message,''))>512
  OR (outcome='accepted' AND coalesce(message,'')='') THEN RAISE EXCEPTION 'Invalid provider result'; END IF;
 UPDATE psms_accounts.otp_challenges SET delivery_status=outcome,provider_id=nullif(message,'') WHERE challenge_id=challenge AND delivery_status='pending';
 IF NOT FOUND THEN RAISE EXCEPTION 'Delivery already finalized'; END IF;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.otp_email_replace_v1(target bigint, address text, reason text, expected_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor bigint; key text;
BEGIN
 actor:=psms_accounts.recovery_actor_v1();
 IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=actor AND role='Admin' AND password=expected_hash)
  OR reason IS NULL OR length(btrim(reason)) NOT BETWEEN 10 AND 500
  OR address IS NULL OR address !~ '^[a-z0-9][a-z0-9.+_-]{0,63}@gmail[.]com$' THEN
  RAISE EXCEPTION 'Admin credential and documented reason required' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.users WHERE id=target AND role IN ('Admin','Staff','Inspector') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Account unavailable'; END IF;
 key:=replace(split_part(split_part(address,'@',1),'+',1),'.','')||'@gmail.com';
 PERFORM pg_advisory_xact_lock(hashtextextended(key,0));
 IF EXISTS(SELECT 1 FROM psms_accounts.recovery_emails WHERE mailbox_key=key AND user_id<>target) THEN RAISE EXCEPTION 'Mailbox already registered' USING ERRCODE='23505'; END IF;
 INSERT INTO psms_accounts.recovery_emails(user_id,email) VALUES(target,address)
 ON CONFLICT(user_id) DO UPDATE SET email=EXCLUDED.email,revision=recovery_emails.revision+1,verified_at=NULL,updated_at=clock_timestamp();
 UPDATE psms_accounts.otp_challenges SET consumed_at=clock_timestamp() WHERE user_id=target AND consumed_at IS NULL;
 UPDATE psms_accounts.recovery_tokens SET consumed_at=clock_timestamp() WHERE user_id=target AND consumed_at IS NULL;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 SELECT clock_timestamp()::text,username,'Registered Gmail Replaced','Account',target::text,btrim(reason) FROM public.users WHERE id=actor;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.otp_enroll_v1(target bigint, address text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor bigint; key text;
BEGIN
 actor:=psms_accounts.recovery_actor_v1();
 IF (SELECT role FROM public.users WHERE id=actor) IS DISTINCT FROM 'Admin'
  OR NOT EXISTS(SELECT 1 FROM public.users WHERE id=target AND role IN ('Staff','Inspector') AND status='Inactive')
  OR address IS NULL OR address !~ '^[a-z0-9][a-z0-9.+_-]{0,63}@gmail[.]com$' THEN RAISE EXCEPTION 'Invalid enrollment' USING ERRCODE='42501'; END IF;
 key:=replace(split_part(split_part(address,'@',1),'+',1),'.','')||'@gmail.com';
 PERFORM pg_advisory_xact_lock(hashtextextended(key,0));
 IF EXISTS(SELECT 1 FROM psms_accounts.recovery_emails WHERE mailbox_key=key) THEN RAISE EXCEPTION 'Mailbox already registered' USING ERRCODE='23505'; END IF;
 INSERT INTO psms_accounts.otp_enrollments(user_id) VALUES(target);
 INSERT INTO psms_accounts.recovery_emails(user_id,email) VALUES(target,address);
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.otp_issue_v1(username_input text, email_input text, purpose text, challenge text, proof text, peer text, identity_key text, expected_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor bigint; employee record; address record; stamp timestamptz;
BEGIN
 IF challenge IS NULL OR challenge !~ '^[0-9a-f]{64}$' OR proof IS NULL OR proof !~ '^[0-9a-f]{64}$'
  OR peer IS NULL OR peer !~ '^[0-9a-f]{64}$' OR identity_key IS NULL OR identity_key !~ '^[0-9a-f]{64}$'
  OR purpose IS NULL OR purpose NOT IN ('activate','verify','forgot','change') THEN RETURN NULL; END IF;
 -- Budgets precede every actor/user lock in BOTH public and authenticated paths.
 IF NOT psms_accounts.otp_budget_v1('request-peer:'||peer,10,900) THEN RETURN NULL; END IF;
 IF NOT psms_accounts.otp_budget_v1('request-identity:'||identity_key,3,900) THEN RETURN NULL; END IF;
 IF purpose='change' THEN
  actor:=psms_accounts.recovery_actor_v1();
  SELECT id,username,password,role,status INTO employee FROM public.users WHERE id=actor FOR UPDATE;
  IF expected_hash IS NULL OR employee.password IS DISTINCT FROM expected_hash THEN RAISE EXCEPTION 'Current credential required' USING ERRCODE='42501'; END IF;
 ELSE
  SELECT id,username,password,role,status INTO employee FROM public.users WHERE username=username_input AND role IN ('Admin','Staff','Inspector') FOR UPDATE;
 END IF;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO address FROM psms_accounts.recovery_emails WHERE user_id=employee.id FOR UPDATE;
 IF NOT FOUND OR (purpose<>'change' AND address.email IS DISTINCT FROM email_input) THEN RETURN NULL; END IF;
 IF purpose='activate' THEN
  IF employee.status<>'Inactive' OR NOT EXISTS(SELECT 1 FROM psms_accounts.otp_enrollments WHERE user_id=employee.id AND pending) THEN RETURN NULL; END IF;
 ELSE
  IF employee.status<>'Active' OR (purpose IN ('forgot','change') AND address.verified_at IS NULL) THEN RETURN NULL; END IF;
 END IF;
 stamp:=clock_timestamp();
 IF EXISTS(SELECT 1 FROM psms_accounts.otp_challenges WHERE user_id=employee.id AND issued_at>stamp-interval '60 seconds') THEN RETURN NULL; END IF;
 -- Unknown identities cannot exhaust the shared sending quota. Every issuer
 -- takes this global budget only after its actor/user/email locks, consistently.
 IF NOT psms_accounts.otp_budget_v1('request-global',250,86400) THEN RETURN NULL; END IF;
 stamp:=clock_timestamp(); -- Start the exact 180-second lifetime after lock/budget waits.
 UPDATE psms_accounts.otp_challenges SET consumed_at=stamp WHERE user_id=employee.id AND consumed_at IS NULL;
 INSERT INTO psms_accounts.otp_challenges(challenge_id,user_id,kind,code_mac,credential_tag,email,email_revision,issued_by,issued_at,expires_at)
 VALUES(challenge,employee.id,purpose,proof,encode(sha256(convert_to(employee.password,'UTF8')),'hex'),address.email,address.revision,actor,stamp,stamp+interval '180 seconds');
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(stamp::text,'OTP service','OTP Issued','Account',employee.id::text,purpose||'; 180-second lifetime; two incorrect attempts maximum');
 RETURN jsonb_build_object('email',address.email);
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.otp_notice_v1(challenge text, outcome text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE target bigint;
BEGIN
 IF outcome IS NULL OR outcome NOT IN ('accepted','failed','unknown') THEN RAISE EXCEPTION 'Invalid notification state'; END IF;
 UPDATE psms_accounts.otp_challenges SET notification_status=outcome WHERE challenge_id=challenge AND success
  AND kind<>'verify' AND notification_status IS NULL RETURNING user_id INTO target;
 IF NOT FOUND THEN RAISE EXCEPTION 'Notification already recorded'; END IF;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 SELECT clock_timestamp()::text,username,'Password Change Notification','Account',id::text,outcome||'; acceptance is not delivery' FROM public.users WHERE id=target;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.otp_state_v1(ids bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor bigint; result jsonb;
BEGIN
 actor:=psms_accounts.recovery_actor_v1(false);
 IF (SELECT role FROM public.users WHERE id=actor)<>'Admin' AND (ids IS NULL OR ids<>ARRAY[actor]) THEN
  RAISE EXCEPTION 'Own account only' USING ERRCODE='42501'; END IF;
 SELECT coalesce(jsonb_object_agg(e.user_id::text,jsonb_build_object('email',e.email,'verified',e.verified_at IS NOT NULL,
  'pending_activation',coalesce(n.pending,false),'last_status',c.delivery_status)),'{}'::jsonb) INTO result
 FROM psms_accounts.recovery_emails e LEFT JOIN psms_accounts.otp_enrollments n ON n.user_id=e.user_id
 LEFT JOIN LATERAL(SELECT delivery_status FROM psms_accounts.otp_challenges WHERE user_id=e.user_id ORDER BY issued_at DESC LIMIT 1)c ON true
 WHERE e.user_id=ANY(ids);
 RETURN result;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.preserve_administrator()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
   IF OLD.role='Admin' THEN RAISE EXCEPTION 'The designated administrator cannot be removed'; END IF;
   RETURN OLD;
 END IF;
 IF TG_OP='INSERT' AND NEW.role='Admin' THEN RAISE EXCEPTION 'Additional administrators are prohibited'; END IF;
 IF TG_OP='UPDATE' AND NEW.role IS DISTINCT FROM OLD.role
    AND (OLD.role='Admin' OR NEW.role='Admin') THEN
   RAISE EXCEPTION 'The designated administrator cannot be changed or replaced';
 END IF;
 IF TG_OP='UPDATE' AND OLD.role='Admin' AND NEW.status IS DISTINCT FROM 'Active' THEN
   RAISE EXCEPTION 'The designated administrator cannot be disabled by account updates';
 END IF;
 RETURN NEW;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.recovery_actor_v1(lock_actor boolean DEFAULT true)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE uid bigint; sid text; who record;
BEGIN
 uid:=(nullif(current_setting('psms.workbook_actor',true),'')::jsonb->>'uid')::bigint;
 sid:=nullif(current_setting('psms.workbook_actor',true),'')::jsonb->>'sid';
 IF uid IS NULL OR sid IS NULL OR sid !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Session required' USING ERRCODE='42501'; END IF;
 IF lock_actor THEN
  SELECT id,role,status INTO who FROM public.users WHERE id=uid FOR UPDATE;
 ELSE
  SELECT id,role,status INTO who FROM public.users WHERE id=uid;
 END IF;
 IF NOT FOUND OR who.status IS DISTINCT FROM 'Active' OR who.role IS NULL OR who.role NOT IN ('Admin','Staff','Inspector') THEN
  RAISE EXCEPTION 'Active actor required' USING ERRCODE='42501'; END IF;
 IF lock_actor THEN
  PERFORM token_hash FROM public.auth_sessions WHERE user_id=uid AND token_hash=sid
   AND revoked_at IS NULL AND expires_at>clock_timestamp() FOR SHARE;
 ELSE
  PERFORM token_hash FROM public.auth_sessions WHERE user_id=uid AND token_hash=sid
   AND revoked_at IS NULL AND expires_at>clock_timestamp();
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'Live session required' USING ERRCODE='42501'; END IF;
 RETURN uid;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.recovery_consume_v1(digest text, kind text, new_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE ticket record; employee record; address record; target bigint;
BEGIN
 IF digest IS NULL OR digest !~ '^[0-9a-f]{64}$' OR kind IS NULL OR kind NOT IN ('verify','reset') THEN RETURN false; END IF;
 SELECT user_id INTO target FROM psms_accounts.recovery_tokens WHERE token_hash=digest;
 IF NOT FOUND THEN RETURN false; END IF;
 -- Same user -> email -> token order in all mutating recovery paths.
 SELECT id,username,password,role,status INTO employee FROM public.users WHERE id=target FOR UPDATE;
 IF NOT FOUND OR employee.status IS DISTINCT FROM 'Active' OR employee.role IS NULL OR employee.role NOT IN ('Admin','Staff','Inspector') THEN RETURN false; END IF;
 SELECT * INTO address FROM psms_accounts.recovery_emails WHERE user_id=target FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT * INTO ticket FROM psms_accounts.recovery_tokens WHERE token_hash=digest FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 IF ticket.purpose<>kind OR ticket.consumed_at IS NOT NULL OR ticket.expires_at<=clock_timestamp()
  OR ticket.delivery_status<>'accepted' OR ticket.email<>address.email OR ticket.email_revision<>address.revision
  OR ticket.credential_tag IS DISTINCT FROM encode(sha256(convert_to(employee.password,'UTF8')),'hex') THEN RETURN false; END IF;
 IF kind='verify' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended(address.mailbox_key,0));
  IF EXISTS(SELECT 1 FROM psms_accounts.recovery_emails WHERE mailbox_key=address.mailbox_key
    AND user_id<>target AND verified_at IS NOT NULL) THEN RETURN false; END IF;
  UPDATE psms_accounts.recovery_emails SET verified_at=clock_timestamp() WHERE user_id=target;
 ELSE
  IF address.verified_at IS NULL OR employee.role NOT IN ('Staff','Inspector') OR new_hash IS NULL OR length(new_hash)>1024
   OR new_hash !~ '^(scrypt:32768:8:1\$[A-Za-z0-9]{8,64}\$[0-9a-f]{128}|pbkdf2:sha256:(600000|1000000)\$[A-Za-z0-9]{8,64}\$[0-9a-f]{64})$' THEN RETURN false; END IF;
  IF public.psms_auth_session_permissions_ready() IS DISTINCT FROM true THEN RAISE EXCEPTION 'Session contract unavailable'; END IF;
  UPDATE public.users SET password=new_hash WHERE id=target;
  IF EXISTS(SELECT 1 FROM public.auth_sessions WHERE user_id=target AND revoked_at IS NULL) THEN
   RAISE EXCEPTION 'Session revocation failed'; END IF;
 END IF;
 UPDATE psms_accounts.recovery_tokens SET consumed_at=clock_timestamp() WHERE user_id=target
  AND consumed_at IS NULL AND (purpose=kind OR kind='reset');
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(clock_timestamp() AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),employee.username,
  CASE WHEN kind='verify' THEN 'Recovery Email Verified' ELSE 'Email Password Reset' END,
  'Account',target::text,'Single-use verified-mailbox link; no automatic login');
 RETURN true;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.recovery_delivery_v1(digest text, outcome text, message_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor bigint; target bigint;
BEGIN
 actor:=psms_accounts.recovery_actor_v1();
 IF outcome IS NULL OR outcome NOT IN ('accepted','failed','unknown') OR message_id IS NULL OR length(message_id)>512
   OR (outcome='accepted' AND length(message_id)=0) THEN RAISE EXCEPTION 'Invalid delivery state'; END IF;
 UPDATE psms_accounts.recovery_tokens SET delivery_status=outcome,provider_id=nullif(message_id,'')
 WHERE token_hash=digest AND issued_by=actor AND delivery_status='pending' AND consumed_at IS NULL RETURNING user_id INTO target;
 IF NOT FOUND THEN RAISE EXCEPTION 'Pending delivery changed'; END IF;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 SELECT to_char(clock_timestamp() AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),username,
  'Recovery Provider Status','Account',target::text,outcome||'; delivery not confirmed' FROM public.users WHERE id=actor;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.recovery_email_set_v1(target bigint, address text, expected_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor bigint; actor_role text; employee record;
BEGIN
 actor:=psms_accounts.recovery_actor_v1();SELECT role INTO actor_role FROM public.users WHERE id=actor;
 IF actor<>target AND actor_role<>'Admin' THEN RAISE EXCEPTION 'Admin or self required' USING ERRCODE='42501'; END IF;
 SELECT id,password,role,status INTO employee FROM public.users WHERE id=target FOR UPDATE;
 IF NOT FOUND OR employee.status IS DISTINCT FROM 'Active' OR employee.role IS NULL OR employee.role NOT IN ('Admin','Staff','Inspector')
  OR (actor<>target AND employee.role='Admin')
  OR (actor=target AND (expected_hash IS NULL OR expected_hash IS DISTINCT FROM employee.password)) THEN
  RAISE EXCEPTION 'Account authorization changed' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM psms_accounts.recovery_emails WHERE user_id=target AND email=address) THEN RETURN; END IF;
 INSERT INTO psms_accounts.recovery_emails(user_id,email) VALUES(target,address)
 ON CONFLICT(user_id) DO UPDATE SET email=EXCLUDED.email,revision=psms_accounts.recovery_emails.revision+1,
  verified_at=NULL,updated_at=clock_timestamp();
 UPDATE psms_accounts.recovery_tokens SET consumed_at=clock_timestamp() WHERE user_id=target AND consumed_at IS NULL;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 SELECT to_char(clock_timestamp() AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),username,
  'Recovery Email Updated','Account',target::text,'Unverified; old recovery links invalidated' FROM public.users WHERE id=actor;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.recovery_issue_v1(target bigint, kind text, digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor bigint; actor_role text; employee record; address record; now_at timestamptz:=clock_timestamp();
BEGIN
 actor:=psms_accounts.recovery_actor_v1();SELECT role INTO actor_role FROM public.users WHERE id=actor;
 IF kind IS NULL OR kind NOT IN ('verify','reset') OR digest !~ '^[0-9a-f]{64}$' OR digest IS NULL
  OR (kind='reset' AND (actor_role<>'Admin' OR actor=target))
  OR (kind='verify' AND actor<>target AND actor_role<>'Admin') THEN
  RAISE EXCEPTION 'Recovery request denied' USING ERRCODE='42501'; END IF;
 SELECT id,password,role,status INTO employee FROM public.users WHERE id=target FOR UPDATE;
 IF NOT FOUND OR employee.status IS DISTINCT FROM 'Active' OR employee.role IS NULL OR employee.role NOT IN ('Admin','Staff','Inspector')
  OR (kind='reset' AND employee.role NOT IN ('Staff','Inspector')) THEN
  RAISE EXCEPTION 'Active employee required' USING ERRCODE='42501'; END IF;
 SELECT * INTO address FROM psms_accounts.recovery_emails WHERE user_id=target FOR UPDATE;
 IF NOT FOUND OR (kind='reset' AND address.verified_at IS NULL) THEN
  RAISE EXCEPTION 'Verified recovery address required' USING ERRCODE='22023'; END IF;
 -- Per-actor/user serialization plus a shared issuance lock enforce limits
 -- across all Vercel instances, including failed/unknown provider requests.
 PERFORM pg_advisory_xact_lock(21474,11914);
 IF (SELECT count(*) FROM psms_accounts.recovery_tokens WHERE user_id=target AND issued_at>now_at-interval '1 hour')>=3
  OR EXISTS(SELECT 1 FROM psms_accounts.recovery_tokens WHERE user_id=target AND issued_at>now_at-interval '1 minute')
  OR (SELECT count(*) FROM psms_accounts.recovery_tokens WHERE issued_by=actor AND issued_at>now_at-interval '1 hour')>=20
  OR (SELECT count(*) FROM psms_accounts.recovery_tokens WHERE issued_at>now_at-interval '24 hours')>=250 THEN
  RAISE EXCEPTION 'Recovery rate limit reached' USING ERRCODE='P0001'; END IF;
 UPDATE psms_accounts.recovery_tokens SET consumed_at=now_at WHERE user_id=target AND purpose=kind AND consumed_at IS NULL;
 INSERT INTO psms_accounts.recovery_tokens(token_hash,user_id,issued_by,purpose,email,email_revision,credential_tag,issued_at,expires_at)
 VALUES(digest,target,actor,kind,address.email,address.revision,encode(sha256(convert_to(employee.password,'UTF8')),'hex'),
  now_at,now_at+CASE WHEN kind='reset' THEN interval '15 minutes' ELSE interval '30 minutes' END);
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 SELECT to_char(now_at AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),username,
  'Recovery Link Requested','Account',target::text,kind||'; provider submission pending' FROM public.users WHERE id=actor;
 RETURN jsonb_build_object('email',address.email);
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.recovery_state_v1(ids bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor bigint; is_admin boolean; result jsonb;
BEGIN
 actor:=psms_accounts.recovery_actor_v1(false);
 SELECT role='Admin' INTO is_admin FROM public.users WHERE id=actor;
 IF NOT FOUND OR is_admin IS NULL THEN RAISE EXCEPTION 'Actor changed' USING ERRCODE='42501'; END IF;
 IF cardinality(ids)>100 OR (NOT is_admin AND EXISTS(SELECT 1 FROM unnest(ids) id WHERE id<>actor)) THEN
  RAISE EXCEPTION 'Record access denied' USING ERRCODE='42501'; END IF;
 SELECT coalesce(jsonb_object_agg(e.user_id::text,jsonb_build_object('email',e.email,
   'verified',e.verified_at IS NOT NULL,'last_status',coalesce(t.delivery_status,'not_requested'))),'{}')
 INTO result FROM psms_accounts.recovery_emails e LEFT JOIN LATERAL (
  SELECT delivery_status FROM psms_accounts.recovery_tokens WHERE user_id=e.user_id ORDER BY issued_at DESC LIMIT 1
 ) t ON true WHERE e.user_id=ANY(ids);
 RETURN result;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.recovery_throttle_v1(peer text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE hits integer;
BEGIN
 IF peer IS NULL OR peer !~ '^[0-9a-f]{64}$' THEN RETURN false; END IF;
 INSERT INTO psms_accounts.recovery_limits(peer_hash,window_start,attempts) VALUES(peer,clock_timestamp(),1)
 ON CONFLICT(peer_hash) DO UPDATE SET
  attempts=CASE WHEN psms_accounts.recovery_limits.window_start<clock_timestamp()-interval '15 minutes' THEN 1
   ELSE least(psms_accounts.recovery_limits.attempts+1,31) END,
  window_start=CASE WHEN psms_accounts.recovery_limits.window_start<clock_timestamp()-interval '15 minutes'
   THEN clock_timestamp() ELSE psms_accounts.recovery_limits.window_start END
 RETURNING attempts INTO hits;
 RETURN hits<=30;
END;$function$;

CREATE OR REPLACE FUNCTION psms_accounts.require_admin_v1()
 RETURNS TABLE(actor_id bigint, actor_name text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE context jsonb; uid bigint; sid text; actor record;
BEGIN
 context:=nullif(current_setting('psms.workbook_actor',true),'')::jsonb;
 IF jsonb_typeof(context)<>'object' OR coalesce(context->>'uid','') !~ '^[1-9][0-9]{0,17}$'
    OR coalesce(context->>'sid','') !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'Active administrator session required' USING ERRCODE='42501';
 END IF;
 uid:=(context->>'uid')::bigint; sid:=context->>'sid';
 IF NOT public.psms_auth_session_permissions_ready() THEN
   RAISE EXCEPTION 'Existing revocation contract unavailable' USING ERRCODE='42501';
 END IF;
 SELECT id,username,role,status INTO actor FROM public.users WHERE id=uid FOR UPDATE;
 IF NOT FOUND OR actor.role IS DISTINCT FROM 'Admin' OR actor.status IS DISTINCT FROM 'Active' THEN
   RAISE EXCEPTION 'Active administrator required' USING ERRCODE='42501';
 END IF;
 PERFORM token_hash FROM public.auth_sessions WHERE token_hash=sid AND user_id=uid
   AND revoked_at IS NULL AND expires_at>clock_timestamp() FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Current session required' USING ERRCODE='42501'; END IF;
 RETURN QUERY SELECT actor.id,actor.username;
END;$function$;

-- psms_aoq_api routines
CREATE OR REPLACE FUNCTION psms_aoq_api.approval_actor_v1()
 RETURNS TABLE(actor_id bigint, actor_username text)
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
AS $function$
DECLARE v_claim jsonb; v_uid bigint; v_name text;
BEGIN
 BEGIN
  v_claim:=nullif(current_setting('psms.workbook_actor',true),'')::jsonb;
  IF jsonb_typeof(v_claim) IS DISTINCT FROM 'object'
   OR coalesce(v_claim->>'uid','') !~ '^[1-9][0-9]{0,18}$'
   OR coalesce(v_claim->>'sid','') !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';END IF;
  v_uid:=(v_claim->>'uid')::bigint;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';
 END;
 SELECT usr.username INTO v_name FROM public.users usr WHERE usr.id=v_uid
  AND usr.status='Active' AND usr.role IN ('Admin','Staff','Inspector') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';END IF;
 PERFORM 1 FROM public.auth_sessions sess WHERE sess.user_id=v_uid
  AND sess.token_hash=v_claim->>'sid' AND sess.revoked_at IS NULL AND sess.expires_at>clock_timestamp() FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';END IF;
 RETURN QUERY SELECT v_uid,v_name;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.approve_po_after_verification_v1(p_po_id bigint, p_review_confirm boolean, p_final_confirm boolean)
 RETURNS TABLE(po_id bigint, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_preview record;v_aoq record;v_pr record;v_po record;v_review record;v_nlp record;v_hash text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 SELECT aoq_id,pr_id INTO v_preview FROM public.po WHERE id=p_po_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PO unavailable' USING ERRCODE='PA004';END IF;
 SELECT id,pr_id,status INTO v_aoq FROM public.aoq WHERE id=v_preview.aoq_id FOR SHARE;
 SELECT id,no,status,items,app_id,ppmp_id,office INTO v_pr FROM public.pr WHERE id=v_preview.pr_id FOR SHARE;
 SELECT id,no,aoq_id,pr_id,status,items INTO v_po FROM public.po WHERE id=p_po_id FOR UPDATE;
 SELECT proof.* INTO v_review FROM psms_documents.pr_po_reviews AS proof WHERE proof.po_id=p_po_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Authorized PR-PO relationship required before final PO approval' USING ERRCODE='PA002';END IF;
 SELECT verification.id,verification.no,verification.po_id,verification.pr_id,verification.workflow_version,verification.status,
  verification.result,verification.confidence,verification.details,verification.technical_status,verification.model_version,
  verification.pr_items_hash,verification.po_items_hash INTO v_nlp FROM public.nlp AS verification WHERE verification.id=v_review.nlp_id FOR SHARE;
 IF p_review_confirm IS DISTINCT FROM true OR p_final_confirm IS DISTINCT FROM true
  OR v_po.status IS DISTINCT FROM 'For Review' OR v_pr.status IS DISTINCT FROM 'Approved'
  OR v_aoq.status IS DISTINCT FROM 'Approved' OR v_po.aoq_id IS DISTINCT FROM v_preview.aoq_id
  OR v_po.pr_id IS DISTINCT FROM v_review.pr_id OR v_pr.id IS DISTINCT FROM v_review.pr_id
  OR (v_aoq.pr_id IS NOT NULL AND v_aoq.pr_id IS DISTINCT FROM v_review.pr_id)
  OR v_nlp.status IS DISTINCT FROM 'Approved' OR v_nlp.result IS NULL OR v_nlp.result NOT IN ('Acceptable','Needs Review')
  OR v_nlp.technical_status IS DISTINCT FROM 'MATCH' OR v_nlp.po_id IS DISTINCT FROM v_po.id
  OR v_nlp.pr_id IS DISTINCT FROM v_pr.id THEN
  RAISE EXCEPTION 'Confirmed reviewed procurement relationship required' USING ERRCODE='PA002';END IF;
 IF v_nlp.details::jsonb->'reviewed_procurement_context' IS DISTINCT FROM
   jsonb_build_object('pr_app_id',v_pr.app_id,'pr_ppmp_id',v_pr.ppmp_id,'pr_office',v_pr.office) THEN
  RAISE EXCEPTION 'Reviewed procurement scope changed' USING ERRCODE='PA002';END IF;
 IF v_aoq.pr_id IS NULL THEN
  PERFORM 1 FROM public.app_plan a JOIN public.ppmp m ON m.id=a.ppmp_id
   WHERE a.id=v_pr.app_id AND a.status='Approved' AND m.status='Approved'
    AND (v_pr.ppmp_id IS NULL OR v_pr.ppmp_id=m.id) FOR SHARE OF a,m;
  IF NOT FOUND THEN RAISE EXCEPTION 'Approved planning evidence changed' USING ERRCODE='PA006';END IF;
 END IF;
 IF v_review.pr_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_pr.items,''),'UTF8')),'hex')
  OR v_review.po_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_po.items,''),'UTF8')),'hex') THEN
  RAISE EXCEPTION 'Reviewed documents changed' USING ERRCODE='PA002';END IF;
 v_hash:=encode(sha256(convert_to(jsonb_build_array(v_nlp.pr_id,v_nlp.po_id,v_nlp.result,v_nlp.confidence,v_nlp.details,
  v_nlp.technical_status,v_nlp.model_version,v_nlp.pr_items_hash,v_nlp.po_items_hash)::text,'UTF8')),'hex');
 IF v_hash IS DISTINCT FROM v_review.nlp_hash THEN RAISE EXCEPTION 'Reviewed verification changed' USING ERRCODE='PA002';END IF;
 PERFORM psms_aoq_api.require_saved_technical_match_v2(v_nlp.technical_status,
  v_nlp.details::jsonb->'technical_comparison',v_review.item_mapping,
  v_nlp.details::jsonb->'reviewed_technical_checks');
 -- The existing Python signatory adapter binds context only for direct UPDATE
 -- statements. This secure SELECT/RPC path must bind the same validated actor
 -- before the existing approval trigger runs; never bypass that trigger.
 PERFORM set_config('psms.signatory_actor',jsonb_build_object('user_id',v_actor.actor_id,
  'sid',(nullif(current_setting('psms.workbook_actor',true),'')::jsonb)->>'sid')::text,true);
 UPDATE public.po SET status='Approved' WHERE id=p_po_id;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(clock_timestamp() AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),v_actor.actor_username,
  'Approved PO','PO',v_po.no,'Final approval after authorized PR-PO relationship and human NLP review');
 RETURN QUERY SELECT p_po_id,'Approved'::text;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.approve_po_before_verification_v2(p_po_id bigint, p_review_confirm boolean, p_final_confirm boolean)
 RETURNS TABLE(po_id bigint, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
 SET statement_timeout TO '10s'
AS $function$
DECLARE v_actor record;v_preview record;v_aoq record;v_po record;v_pr record;v_items jsonb;v_item jsonb;
 v_qty double precision;v_price double precision;v_amount double precision;v_link bigint;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();

 PERFORM 1 FROM psms_documents.procurement_policy p WHERE p.singleton AND p.policy->'enabled'='true'::jsonb
  AND p.policy->>'po_clock'='ASIA_MANILA';
 IF NOT FOUND THEN RAISE EXCEPTION 'Procurement workflow disabled' USING ERRCODE='PA007';END IF;

 IF p_review_confirm IS DISTINCT FROM true OR p_final_confirm IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'Explicit PO review and approval required' USING ERRCODE='PA001';END IF;
 SELECT target.aoq_id,target.pr_id INTO v_preview FROM public.po target WHERE target.id=p_po_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PO unavailable' USING ERRCODE='PA004';END IF;
 -- Same source-before-child lock order as the installed contract.
 SELECT a.id,a.pr_id,a.status,a.winner,a.winning_offer,a.winning_amount INTO v_aoq
  FROM public.aoq a WHERE a.id=v_preview.aoq_id FOR SHARE;
 IF NOT FOUND OR v_aoq.status IS DISTINCT FROM 'Approved' THEN
  RAISE EXCEPTION 'Approved AOQ required' USING ERRCODE='PA002';END IF;
 v_link:=coalesce(v_preview.pr_id,v_aoq.pr_id);
 IF v_link IS NOT NULL THEN
  SELECT p.id,p.status INTO v_pr FROM public.pr p WHERE p.id=v_link FOR SHARE;
  IF NOT FOUND OR v_pr.status IS DISTINCT FROM 'Approved' THEN
   RAISE EXCEPTION 'Existing PR link is not approved' USING ERRCODE='PA002';END IF;
 END IF;
 SELECT p.id,p.no,p.aoq_id,p.pr_id,p.status,p.supplier,p.items,p.total INTO v_po
  FROM public.po p WHERE p.id=p_po_id FOR UPDATE;
 IF NOT FOUND OR v_po.aoq_id IS DISTINCT FROM v_preview.aoq_id OR v_po.pr_id IS DISTINCT FROM v_preview.pr_id
  OR v_po.status NOT IN ('For Review','Approved') OR v_po.status IS NULL
  OR (v_po.pr_id IS NOT NULL AND v_aoq.pr_id IS NOT NULL AND v_po.pr_id IS DISTINCT FROM v_aoq.pr_id)
  OR nullif(btrim(v_aoq.winner),'') IS NULL OR v_po.supplier IS DISTINCT FROM v_aoq.winner
  OR v_po.total IS NULL OR v_po.total::text IN ('NaN','Infinity','-Infinity') OR v_po.total<=0
  OR v_po.total IS DISTINCT FROM v_aoq.winning_amount THEN
  RAISE EXCEPTION 'Reviewed PO conflicts with its approved source' USING ERRCODE='PA002';END IF;
 IF EXISTS(SELECT 1 FROM public.po other_po WHERE other_po.aoq_id=v_po.aoq_id AND other_po.id<>v_po.id
  AND other_po.status IN ('For Review','Approved')) THEN
  RAISE EXCEPTION 'AOQ has conflicting active purchase orders' USING ERRCODE='PA002';END IF;
 BEGIN
  v_items:=v_po.items::jsonb;
  IF v_items IS DISTINCT FROM v_aoq.winning_offer::jsonb OR jsonb_typeof(v_items) IS DISTINCT FROM 'array'
   OR jsonb_array_length(v_items) NOT BETWEEN 1 AND 200 THEN
   RAISE EXCEPTION 'Unchanged approved quotation items required' USING ERRCODE='PA001';END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
   IF jsonb_typeof(v_item) IS DISTINCT FROM 'object' OR nullif(btrim(v_item->>'item'),'') IS NULL
    OR nullif(btrim(v_item->>'description'),'') IS NULL OR nullif(btrim(v_item->>'unit'),'') IS NULL THEN
    RAISE EXCEPTION 'Complete reviewed source items required' USING ERRCODE='PA001';END IF;
   v_qty:=(v_item->>'qty')::double precision;v_price:=(v_item->>'unit_cost')::double precision;v_amount:=(v_item->>'amount')::double precision;
   IF v_qty IS NULL OR v_price IS NULL OR v_amount IS NULL OR v_qty<=0 OR v_price<0 OR v_amount<0
    OR v_qty::text IN ('NaN','Infinity','-Infinity') OR v_price::text IN ('NaN','Infinity','-Infinity')
    OR v_amount::text IN ('NaN','Infinity','-Infinity') THEN
    RAISE EXCEPTION 'Valid approved source numbers required' USING ERRCODE='PA001';END IF;
  END LOOP;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RAISE EXCEPTION 'Valid approved source values required' USING ERRCODE='PA001';
 END;
 -- Idempotent repeat does not execute the snapshot trigger or duplicate audits.
 IF v_po.status='Approved' THEN RETURN QUERY SELECT p_po_id,'Approved'::text;RETURN;END IF;
 -- Existing trigger validates the REAL active registry and captures snapshots.
 PERFORM set_config('psms.signatory_actor',jsonb_build_object('user_id',v_actor.actor_id,
  'sid',(nullif(current_setting('psms.workbook_actor',true),'')::jsonb)->>'sid')::text,true);
 UPDATE public.po SET status='Approved' WHERE id=p_po_id;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(clock_timestamp() AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),v_actor.actor_username,
  'Approved PO','PO',v_po.no,'Explicit source-backed PO approval; PR-PO verification and receiving remain separate');
 RETURN QUERY SELECT p_po_id,'Approved'::text;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.approve_po_before_verification_v3(p_po_id bigint, p_review_confirm boolean, p_final_confirm boolean)
 RETURNS TABLE(po_id bigint, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
 SET statement_timeout TO '10s'
AS $function$
DECLARE v_actor record;v_preview record;v_aoq record;v_po record;v_pr record;v_items jsonb;v_item jsonb;
 v_qty double precision;v_price double precision;v_amount double precision;v_link bigint;
 v_source_items jsonb;v_source_item jsonb;v_position bigint;v_seen_source_ids text[]:=ARRAY[]::text[];
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();

 PERFORM 1 FROM psms_documents.procurement_policy p WHERE p.singleton AND p.policy->'enabled'='true'::jsonb
  AND p.policy->>'po_clock'='ASIA_MANILA';
 IF NOT FOUND THEN RAISE EXCEPTION 'Procurement workflow disabled' USING ERRCODE='PA007';END IF;

 IF p_review_confirm IS DISTINCT FROM true OR p_final_confirm IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'Explicit PO review and approval required' USING ERRCODE='PA001';END IF;
 SELECT target.aoq_id,target.pr_id INTO v_preview FROM public.po target WHERE target.id=p_po_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PO unavailable' USING ERRCODE='PA004';END IF;
 -- Same source-before-child lock order as the installed contract.
 SELECT a.id,a.pr_id,a.status,a.winner,a.winning_offer,a.winning_amount INTO v_aoq
  FROM public.aoq a WHERE a.id=v_preview.aoq_id FOR SHARE;
 IF NOT FOUND OR v_aoq.status IS DISTINCT FROM 'Approved' THEN
  RAISE EXCEPTION 'Approved AOQ required' USING ERRCODE='PA002';END IF;
 v_link:=coalesce(v_preview.pr_id,v_aoq.pr_id);
 IF v_link IS NOT NULL THEN
  SELECT p.id,p.status INTO v_pr FROM public.pr p WHERE p.id=v_link FOR SHARE;
  IF NOT FOUND OR v_pr.status IS DISTINCT FROM 'Approved' THEN
   RAISE EXCEPTION 'Existing PR link is not approved' USING ERRCODE='PA002';END IF;
 END IF;
 SELECT p.id,p.no,p.aoq_id,p.pr_id,p.status,p.supplier,p.items,p.total INTO v_po
  FROM public.po p WHERE p.id=p_po_id FOR UPDATE;
 IF NOT FOUND OR v_po.aoq_id IS DISTINCT FROM v_preview.aoq_id OR v_po.pr_id IS DISTINCT FROM v_preview.pr_id
  OR v_po.status NOT IN ('For Review','Approved') OR v_po.status IS NULL
  OR (v_po.pr_id IS NOT NULL AND v_aoq.pr_id IS NOT NULL AND v_po.pr_id IS DISTINCT FROM v_aoq.pr_id)
  OR nullif(btrim(v_aoq.winner),'') IS NULL OR v_po.supplier IS DISTINCT FROM v_aoq.winner
  OR v_po.total IS NULL OR v_po.total::text IN ('NaN','Infinity','-Infinity') OR v_po.total<=0
  OR v_po.total IS DISTINCT FROM v_aoq.winning_amount THEN
  RAISE EXCEPTION 'Reviewed PO conflicts with its approved source' USING ERRCODE='PA002';END IF;
 IF EXISTS(SELECT 1 FROM public.po other_po WHERE other_po.aoq_id=v_po.aoq_id AND other_po.id<>v_po.id
  AND other_po.status IN ('For Review','Approved')) THEN
  RAISE EXCEPTION 'AOQ has conflicting active purchase orders' USING ERRCODE='PA002';END IF;
 BEGIN
  v_items:=v_po.items::jsonb;
  v_source_items:=v_aoq.winning_offer::jsonb;
  IF jsonb_typeof(v_items) IS DISTINCT FROM 'array' OR jsonb_typeof(v_source_items) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'Unchanged approved quotation items required' USING ERRCODE='PA001';END IF;
  IF jsonb_array_length(v_items) NOT BETWEEN 1 AND 200
   OR jsonb_array_length(v_items)<>jsonb_array_length(v_source_items) THEN
   RAISE EXCEPTION 'Unchanged approved quotation items required' USING ERRCODE='PA001';END IF;
  FOR v_item,v_position IN SELECT value,ordinality FROM jsonb_array_elements(v_items) WITH ORDINALITY LOOP
   v_source_item:=v_source_items->(v_position::integer-1);
   -- Only the two documented PO-generated keys may differ from the AOQ row.
   -- Missing, duplicate, reordered or foreign source mappings fail closed.
   IF jsonb_typeof(v_item) IS DISTINCT FROM 'object' OR jsonb_typeof(v_source_item) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Valid PO source item mapping required' USING ERRCODE='PA001';END IF;
   IF v_source_item ? '_PO Item ID' OR v_source_item ? '_Source Item ID'
    OR jsonb_typeof(v_source_item->'_AOQ Item ID') IS DISTINCT FROM 'string'
    OR nullif(btrim(v_source_item->>'_AOQ Item ID'),'') IS NULL
    OR (v_source_item->>'_AOQ Item ID')=ANY(v_seen_source_ids)
    OR jsonb_typeof(v_item->'_PO Item ID') IS DISTINCT FROM 'string'
    OR jsonb_typeof(v_item->'_Source Item ID') IS DISTINCT FROM 'string'
    OR (v_item->>'_Source Item ID') IS DISTINCT FROM (v_source_item->>'_AOQ Item ID')
    OR nullif(btrim(v_po.no),'') IS NULL
    OR (v_item->>'_PO Item ID') IS DISTINCT FROM
      (v_po.no||'-ITEM-'||CASE WHEN v_position<10 THEN '0'||v_position::text ELSE v_position::text END)
    OR (v_item - ARRAY['_PO Item ID','_Source Item ID']::text[]) IS DISTINCT FROM v_source_item THEN
    RAISE EXCEPTION 'PO tracking or approved quotation fields changed' USING ERRCODE='PA001';END IF;
   v_seen_source_ids:=array_append(v_seen_source_ids,v_source_item->>'_AOQ Item ID');
   IF jsonb_typeof(v_item) IS DISTINCT FROM 'object' OR nullif(btrim(v_item->>'item'),'') IS NULL
    OR nullif(btrim(v_item->>'description'),'') IS NULL OR nullif(btrim(v_item->>'unit'),'') IS NULL THEN
    RAISE EXCEPTION 'Complete reviewed source items required' USING ERRCODE='PA001';END IF;
   v_qty:=(v_item->>'qty')::double precision;v_price:=(v_item->>'unit_cost')::double precision;v_amount:=(v_item->>'amount')::double precision;
   IF v_qty IS NULL OR v_price IS NULL OR v_amount IS NULL OR v_qty<=0 OR v_price<0 OR v_amount<0
    OR v_qty::text IN ('NaN','Infinity','-Infinity') OR v_price::text IN ('NaN','Infinity','-Infinity')
    OR v_amount::text IN ('NaN','Infinity','-Infinity') THEN
    RAISE EXCEPTION 'Valid approved source numbers required' USING ERRCODE='PA001';END IF;
  END LOOP;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RAISE EXCEPTION 'Valid approved source values required' USING ERRCODE='PA001';
 END;
 -- Idempotent repeat does not execute the snapshot trigger or duplicate audits.
 IF v_po.status='Approved' THEN RETURN QUERY SELECT p_po_id,'Approved'::text;RETURN;END IF;
 -- Existing trigger validates the REAL active registry and captures snapshots.
 PERFORM set_config('psms.signatory_actor',jsonb_build_object('user_id',v_actor.actor_id,
  'sid',(nullif(current_setting('psms.workbook_actor',true),'')::jsonb)->>'sid')::text,true);
 UPDATE public.po SET status='Approved' WHERE id=p_po_id;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(clock_timestamp() AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),v_actor.actor_username,
  'Approved PO','PO',v_po.no,'Explicit source-backed PO approval; PR-PO verification and receiving remain separate');
 RETURN QUERY SELECT p_po_id,'Approved'::text;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.approve_pr_v1(p_pr_id bigint, p_review_confirm boolean)
 RETURNS TABLE(pr_id bigint, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_pr record;v_actor_context jsonb;v_stamp timestamp;
BEGIN
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 IF p_review_confirm IS DISTINCT FROM true THEN RAISE EXCEPTION 'Explicit review required' USING ERRCODE='PA001';END IF;
 SELECT id,no,status,items INTO v_pr FROM public.pr WHERE id=p_pr_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PR unavailable' USING ERRCODE='PA004';END IF;
 IF v_pr.status='Approved' THEN RETURN QUERY SELECT v_pr.id,v_pr.status;RETURN;END IF;
 IF v_pr.status IS DISTINCT FROM 'For Review' OR jsonb_typeof(v_pr.items::jsonb) IS DISTINCT FROM 'array'
  OR jsonb_array_length(v_pr.items::jsonb)=0 THEN RAISE EXCEPTION 'Reviewable complete PR required' USING ERRCODE='PA002';END IF;
 v_actor_context:=current_setting('psms.workbook_actor',true)::jsonb;
 PERFORM set_config('psms.signatory_actor',jsonb_build_object('user_id',v_actor.actor_id,'sid',v_actor_context->>'sid')::text,true);
 UPDATE public.pr SET status='Approved' WHERE id=v_pr.id;
 v_stamp:=clock_timestamp() AT TIME ZONE 'Asia/Manila';
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details) VALUES(to_char(v_stamp,'Mon DD, YYYY HH12:MI AM'),
  v_actor.actor_username,'Approved PR','PR',v_pr.no,'Purchase Request approved');
 RETURN QUERY SELECT v_pr.id,'Approved'::text;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.approve_reviewed_aoq_v1(p_aoq_id bigint, p_review_confirm boolean, p_final_confirm boolean)
 RETURNS TABLE(aoq_id bigint, aoq_no text, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET extra_float_digits TO '1'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET standard_conforming_strings TO 'on'
 SET lock_timeout TO '5s'
AS $function$
DECLARE actor record; source record; checked record; changed bigint;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'Unsupported workflow transaction' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT actor FROM psms_aoq_api.approval_actor_v1();
 IF p_aoq_id IS NULL OR p_aoq_id<=0 THEN RAISE EXCEPTION 'AOQ unavailable' USING ERRCODE='PA004';END IF;
 IF p_review_confirm IS DISTINCT FROM true OR p_final_confirm IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'Explicit approval confirmation required' USING ERRCODE='PA001';END IF;
 SELECT a.id,a.no,a.status,a.winner,a.winning_amount,a.winning_offer INTO source
  FROM public.aoq a WHERE a.id=p_aoq_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'AOQ unavailable' USING ERRCODE='PA004';END IF;
 IF source.status IS DISTINCT FROM 'For Review' THEN RAISE EXCEPTION 'AOQ no longer awaiting approval' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT checked FROM psms_aoq_api.workflow_offer_v1(source.winning_offer,source.winner,source.winning_amount);
 UPDATE public.aoq SET status='Approved' WHERE id=p_aoq_id AND status='For Review';
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>1 THEN RAISE EXCEPTION 'AOQ changed' USING ERRCODE='PA002';END IF;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(clock_timestamp() AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),actor.actor_username,
  'Approved AOQ','AOQ',source.no,'OCR-created AOQ approved after explicit final confirmation');
 RETURN QUERY SELECT source.id::bigint,source.no::text,'Approved'::text;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.approve_reviewed_pr_po_v3(p_nlp_id bigint, p_confirm boolean)
 RETURNS TABLE(nlp_id bigint, po_id bigint, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_preview record;v_saved public.nlp%ROWTYPE;v_review jsonb;v_hash text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 IF p_confirm IS DISTINCT FROM true THEN RAISE EXCEPTION 'Final approval confirmation required' USING ERRCODE='PA001';END IF;
 SELECT n.pr_id,n.po_id,p.aoq_id INTO v_preview FROM public.nlp n JOIN public.po p ON p.id=n.po_id WHERE n.id=p_nlp_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Verification unavailable' USING ERRCODE='PA004';END IF;
 -- Same source-first lock order as the existing final approval function.
 PERFORM 1 FROM public.aoq WHERE id=v_preview.aoq_id FOR SHARE;
 PERFORM 1 FROM public.pr WHERE id=v_preview.pr_id FOR UPDATE;
 PERFORM 1 FROM public.po WHERE id=v_preview.po_id FOR UPDATE;
 SELECT * INTO v_saved FROM public.nlp n WHERE n.id=p_nlp_id FOR UPDATE;
 IF NOT FOUND OR v_saved.workflow_version IS DISTINCT FROM 2 OR v_saved.status IS DISTINCT FROM 'Reviewed' THEN
  RAISE EXCEPTION 'Saved Reviewed verification required' USING ERRCODE='PA002';END IF;
 v_review:=v_saved.details::jsonb->'workflow_review_v3';
 SELECT encode(sha256(convert_to(jsonb_build_array(n.pr_id,n.po_id,n.result,n.confidence,
  n.details::jsonb-'workflow_review_v3',n.technical_status,n.model_version,n.pr_items_hash,n.po_items_hash)::text,'UTF8')),'hex') INTO v_hash FROM public.nlp n WHERE n.id=p_nlp_id;
 IF jsonb_typeof(v_review) IS DISTINCT FROM 'object' OR v_review->>'version' IS DISTINCT FROM '1'
  OR v_review->>'actor_id' IS DISTINCT FROM v_saved.reviewed_by::text
  OR v_review->>'reviewed_at' IS DISTINCT FROM (to_jsonb(v_saved.reviewed_at)#>>'{}')
  OR v_review->>'verification_sha256' IS DISTINCT FROM v_hash
  OR v_review->'mapping' IS DISTINCT FROM v_saved.review_mapping
  OR v_review->'checks' IS DISTINCT FROM v_saved.details::jsonb->'technical_comparison'
  OR v_review->>'reason' IS DISTINCT FROM v_saved.relationship_reason
  OR v_review->>'evidence_reference' IS DISTINCT FROM v_saved.evidence_reference THEN
  RAISE EXCEPTION 'Saved review evidence changed' USING ERRCODE='PA002';END IF;
 -- This temporary state exists only inside the locked approval transaction.
 -- Any old-contract, audit or trigger failure rolls it back to Reviewed.
 UPDATE public.nlp SET status='For Review' WHERE id=p_nlp_id AND status='Reviewed';
 RETURN QUERY SELECT approved.nlp_id,approved.po_id,'Approved'::text
  FROM psms_aoq_api.review_approved_pr_po_verification_v2(p_nlp_id,v_review->'mapping',v_review->'checks',
    v_review->>'reason',v_review->>'evidence_reference',true) AS approved;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.approve_reviewed_pr_po_v4(p_nlp_id bigint, p_confirm boolean)
 RETURNS TABLE(nlp_id bigint, po_id bigint, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_preview record;v_saved public.nlp%ROWTYPE;v_review jsonb;v_hash text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 IF p_confirm IS DISTINCT FROM true THEN RAISE EXCEPTION 'Final approval confirmation required' USING ERRCODE='PA001';END IF;
 SELECT n.pr_id,n.po_id,p.aoq_id INTO v_preview FROM public.nlp n JOIN public.po p ON p.id=n.po_id WHERE n.id=p_nlp_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Verification unavailable' USING ERRCODE='PA004';END IF;
 -- Same source-first lock order as the existing final approval function.
 PERFORM 1 FROM public.aoq WHERE id=v_preview.aoq_id FOR SHARE;
 PERFORM 1 FROM public.pr WHERE id=v_preview.pr_id FOR UPDATE;
 PERFORM 1 FROM public.po WHERE id=v_preview.po_id FOR UPDATE;
 SELECT * INTO v_saved FROM public.nlp n WHERE n.id=p_nlp_id FOR UPDATE;
 IF NOT FOUND OR v_saved.workflow_version IS DISTINCT FROM 2 OR v_saved.status IS DISTINCT FROM 'Reviewed' THEN
  RAISE EXCEPTION 'Saved Reviewed verification required' USING ERRCODE='PA002';END IF;
 v_review:=v_saved.details::jsonb->'workflow_review_v3';
 SELECT encode(sha256(convert_to(jsonb_build_array(n.pr_id,n.po_id,n.result,n.confidence,
  n.details::jsonb-'workflow_review_v3',n.technical_status,n.model_version,n.pr_items_hash,n.po_items_hash)::text,'UTF8')),'hex') INTO v_hash FROM public.nlp n WHERE n.id=p_nlp_id;
 IF jsonb_typeof(v_review) IS DISTINCT FROM 'object' OR v_review->>'version' IS DISTINCT FROM '1'
  OR v_review->>'actor_id' IS DISTINCT FROM v_saved.reviewed_by::text
  OR v_review->>'reviewed_at' IS DISTINCT FROM (to_jsonb(v_saved.reviewed_at)#>>'{}')
  OR v_review->>'verification_sha256' IS DISTINCT FROM v_hash
  OR v_review->'mapping' IS DISTINCT FROM v_saved.review_mapping
  OR v_review->'checks' IS DISTINCT FROM v_saved.details::jsonb->'technical_comparison'
  OR v_review->>'reason' IS DISTINCT FROM v_saved.relationship_reason
  OR v_review->>'evidence_reference' IS DISTINCT FROM v_saved.evidence_reference THEN
  RAISE EXCEPTION 'Saved review evidence changed' USING ERRCODE='PA002';END IF;
 -- This temporary state exists only inside the locked approval transaction.
 -- Any old-contract, audit or trigger failure rolls it back to Reviewed.
 UPDATE public.nlp SET status='For Review' WHERE id=p_nlp_id AND status='Reviewed';
 RETURN QUERY SELECT approved.nlp_id,approved.po_id,'Approved'::text
  FROM psms_aoq_api.approve_tolerated_pr_po_v4(p_nlp_id,v_review->'mapping',v_review->'checks',
    v_review->>'reason',v_review->>'evidence_reference',true) AS approved;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.approve_tolerated_pr_po_v4(p_nlp_id bigint, p_mapping jsonb, p_checks jsonb, p_reason text, p_evidence_reference text, p_confirm boolean)
 RETURNS TABLE(nlp_id bigint, po_id bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_role text;v_preview record;v_aoq record;v_pr record;v_po record;v_nlp record;
 v_policy text;v_nlp_hash text;v_stamp timestamptz:=clock_timestamp();v_pr_count integer;v_po_count integer;v_percentage numeric;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 SELECT role INTO v_role FROM public.users WHERE id=v_actor.actor_id;
 SELECT n.po_id,n.pr_id,p.aoq_id INTO v_preview FROM public.nlp n JOIN public.po p ON p.id=n.po_id WHERE n.id=p_nlp_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Verification unavailable' USING ERRCODE='PA004';END IF;
 SELECT id,pr_id,status INTO v_aoq FROM public.aoq WHERE id=v_preview.aoq_id FOR SHARE;
 SELECT id,no,status,items,app_id,ppmp_id,office INTO v_pr FROM public.pr WHERE id=v_preview.pr_id FOR UPDATE;
 SELECT id,no,aoq_id,pr_id,status,items INTO v_po FROM public.po WHERE id=v_preview.po_id FOR UPDATE;
 SELECT verification.id,verification.no,verification.po_id,verification.pr_id,verification.workflow_version,verification.status,
  verification.result,verification.confidence,verification.details,verification.technical_status,verification.model_version,
  verification.pr_items_hash,verification.po_items_hash INTO v_nlp FROM public.nlp AS verification WHERE verification.id=p_nlp_id FOR UPDATE;
 IF v_nlp.workflow_version IS DISTINCT FROM 2 OR v_nlp.status IS DISTINCT FROM 'For Review'
  OR v_nlp.po_id IS DISTINCT FROM v_po.id OR v_nlp.pr_id IS DISTINCT FROM v_pr.id
  OR v_po.aoq_id IS DISTINCT FROM v_aoq.id OR v_po.status IS DISTINCT FROM 'Approved'
  OR v_pr.status IS DISTINCT FROM 'Approved' OR v_aoq.status IS DISTINCT FROM 'Approved'
  OR (v_aoq.pr_id IS NOT NULL AND v_aoq.pr_id IS DISTINCT FROM v_pr.id)
  OR (v_po.pr_id IS NOT NULL AND v_po.pr_id IS DISTINCT FROM v_pr.id) THEN
  RAISE EXCEPTION 'Sources or verification changed' USING ERRCODE='PA002';END IF;
 IF v_nlp.pr_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_pr.items,''),'UTF8')),'hex')
  OR v_nlp.po_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_po.items,''),'UTF8')),'hex') THEN
  RAISE EXCEPTION 'Sources or verification changed' USING ERRCODE='PA002';END IF;

 -- A replacement may be reviewed only while its immutable lineage still matches.
 IF v_nlp.details::jsonb ? 'verification_lineage' OR EXISTS(
  SELECT 1 FROM psms_documents.nlp_legacy_replacements l WHERE l.replacement_nlp_id=v_nlp.id) THEN
  PERFORM 1 FROM psms_documents.nlp_legacy_replacements l JOIN public.nlp old ON old.id=l.legacy_nlp_id
   WHERE l.replacement_nlp_id=v_nlp.id AND l.po_id=v_po.id AND l.pr_id=v_pr.id
    AND v_nlp.details::jsonb->'verification_lineage'->>'legacy_nlp_id'=l.legacy_nlp_id::text
    AND v_nlp.details::jsonb->'verification_lineage'->>'legacy_record_sha256'=l.legacy_record_sha256
    AND encode(sha256(convert_to(to_jsonb(old)::text,'UTF8')),'hex')=l.legacy_record_sha256
   FOR SHARE OF old;
  IF NOT FOUND THEN RAISE EXCEPTION 'Saved legacy lineage changed' USING ERRCODE='PA002';END IF;
 END IF;

 IF v_aoq.pr_id IS NULL THEN
  SELECT policy->>'link_authority' INTO v_policy FROM psms_documents.procurement_policy WHERE singleton;
  IF v_policy IS NULL OR v_policy='PENDING' THEN RAISE EXCEPTION 'Independent PR-PO authorization policy pending' USING ERRCODE='PA005';END IF;
  IF NOT ((v_policy='ADMIN_DOCUMENTED' AND v_role='Admin') OR
          (v_policy='EXISTING_REVIEWERS_DOCUMENTED' AND v_role IN ('Admin','Staff','Inspector'))) THEN
   RAISE EXCEPTION 'Authorized procurement relationship reviewer required' USING ERRCODE='PA003';END IF;
  PERFORM 1 FROM public.app_plan a JOIN public.ppmp m ON m.id=a.ppmp_id
      WHERE a.id=v_pr.app_id AND a.status='Approved' AND m.status='Approved'
       AND (v_pr.ppmp_id IS NULL OR v_pr.ppmp_id=m.id) FOR SHARE OF a,m;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Approved planning evidence required for independent relationship' USING ERRCODE='PA006';END IF;
 END IF;
 IF p_confirm IS DISTINCT FROM true OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 10 AND 2000
  OR p_evidence_reference IS NULL OR length(btrim(p_evidence_reference)) NOT BETWEEN 3 AND 500 THEN
  RAISE EXCEPTION 'Documented relationship confirmation required' USING ERRCODE='PA001';END IF;
 IF v_nlp.result IS NULL OR v_nlp.result NOT IN ('Acceptable','Needs Review','Needs Recanvass','Reject') THEN
  RAISE EXCEPTION 'Saved original model output required' USING ERRCODE='PA001';END IF;
 v_percentage:=psms_aoq_api.require_ten_percent_review_v4(v_nlp.technical_status,
  v_nlp.details::jsonb->'technical_comparison',p_mapping,p_checks);
 IF EXISTS(SELECT 1 FROM psms_documents.pr_po_reviews AS proof WHERE proof.po_id=v_po.id) THEN
  RAISE EXCEPTION 'Official relationship already reviewed' USING ERRCODE='PA002';END IF;
 IF EXISTS(SELECT 1 FROM psms_documents.pr_po_reviews WHERE pr_id=v_pr.id)
  OR EXISTS(SELECT 1 FROM public.po other_po JOIN public.aoq other_aoq ON other_aoq.id=other_po.aoq_id
     WHERE other_po.id<>v_po.id AND coalesce(other_po.pr_id,other_aoq.pr_id)=v_pr.id
       AND other_po.status IN ('For Review','Approved')) THEN
  RAISE EXCEPTION 'PR already has an active purchase order' USING ERRCODE='PA002';END IF;
 UPDATE public.nlp SET status='Approved',staff_decision=result,reviewed_by=v_actor.actor_id,reviewed_at=v_stamp,
  review_mapping=p_mapping,relationship_reason=btrim(p_reason),evidence_reference=btrim(p_evidence_reference),
  details=(details::jsonb||jsonb_build_object('threshold_approval_v4',jsonb_build_object(
    'version',1,'percentage',v_percentage,'technical_comparison',v_nlp.details::jsonb->'technical_comparison',
    'pr_items_hash',v_nlp.pr_items_hash,'po_items_hash',v_nlp.po_items_hash),
    'reviewed_technical_checks',p_checks,'reviewed_procurement_context',
    jsonb_build_object('pr_app_id',v_pr.app_id,'pr_ppmp_id',v_pr.ppmp_id,'pr_office',v_pr.office)))::text WHERE id=p_nlp_id;
 UPDATE public.po SET pr_id=v_pr.id WHERE id=v_po.id;
 SELECT encode(sha256(convert_to(jsonb_build_array(n.pr_id,n.po_id,n.result,n.confidence,n.details,n.technical_status,n.model_version,n.pr_items_hash,n.po_items_hash)::text,'UTF8')),'hex')
  INTO v_nlp_hash FROM public.nlp n WHERE n.id=p_nlp_id;
 INSERT INTO psms_documents.pr_po_reviews(po_id,pr_id,nlp_id,pr_items_hash,po_items_hash,nlp_hash,
  reviewer_id,reviewed_at,item_mapping,justification,evidence_reference)
 VALUES(v_po.id,v_pr.id,p_nlp_id,v_nlp.pr_items_hash,v_nlp.po_items_hash,v_nlp_hash,v_actor.actor_id,v_stamp,
  p_mapping,btrim(p_reason),btrim(p_evidence_reference));
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(v_stamp AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),v_actor.actor_username,
  'Authorized PR-PO Relationship','NLP',v_nlp.no,'PR '||v_pr.no||'; PO '||v_po.no||'; final affected-item discrepancy '||v_percentage::text||'%; manual <=10% policy; evidence: '||btrim(p_evidence_reference));
 RETURN QUERY SELECT p_nlp_id,v_po.id;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.create_po_for_review_v2(p_aoq_id bigint)
 RETURNS TABLE(po_id bigint, po_no text, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_aoq record;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 SELECT id,pr_id,status INTO v_aoq FROM public.aoq WHERE id=p_aoq_id FOR UPDATE;
 IF NOT FOUND OR v_aoq.status IS DISTINCT FROM 'Approved' THEN RAISE EXCEPTION 'Approved AOQ required' USING ERRCODE='PA002';END IF;
 IF v_aoq.pr_id IS NOT NULL THEN
  PERFORM 1 FROM public.pr WHERE id=v_aoq.pr_id AND status='Approved' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Approved source PR required' USING ERRCODE='PA002';END IF;
  IF EXISTS(SELECT 1 FROM public.po other_po JOIN public.aoq other_aoq ON other_aoq.id=other_po.aoq_id
     WHERE coalesce(other_po.pr_id,other_aoq.pr_id)=v_aoq.pr_id AND other_po.aoq_id<>p_aoq_id
      AND other_po.status IN ('For Review','Approved')) THEN
   RAISE EXCEPTION 'PR already has an active purchase order' USING ERRCODE='PA002';END IF;
 END IF;
 -- Preserve the exact tested quotation, totals, numbering and retry routine as
 -- a private operation; the backend cannot bypass this relationship wrapper.
 RETURN QUERY SELECT result.po_id,result.po_no,result.created
  FROM psms_aoq_api.create_po_from_approved_aoq_v1(p_aoq_id) AS result;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.create_po_from_approved_aoq_v1(p_aoq_id bigint)
 RETURNS TABLE(po_id bigint, po_no text, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET extra_float_digits TO '1'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET standard_conforming_strings TO 'on'
 SET lock_timeout TO '5s'
AS $function$
DECLARE
 actor record; source record; checked record; existing record; existing_count bigint;
 instant timestamptz; stamp timestamp; display_date text; counter_key text; next_number bigint; document_no text; new_id bigint;
 item json; pair record; source_id json; field_name text; fields text; output_text text:=''; item_number integer:=0; replace_source boolean;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'Unsupported workflow transaction' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT actor FROM psms_aoq_api.approval_actor_v1();
 IF p_aoq_id IS NULL OR p_aoq_id<=0 THEN RAISE EXCEPTION 'AOQ unavailable' USING ERRCODE='PA004';END IF;
 SELECT a.id,a.no,a.status,a.winner,a.winning_amount,a.winning_offer INTO source
  FROM public.aoq a WHERE a.id=p_aoq_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'AOQ unavailable' USING ERRCODE='PA004';END IF;
 IF source.status IS DISTINCT FROM 'Approved' THEN RAISE EXCEPTION 'Approved AOQ required' USING ERRCODE='PA002';END IF;
 -- Separate statement after the parent lock: READ COMMITTED sees a preceding committed child.
 SELECT count(*) INTO existing_count FROM public.po p WHERE p.aoq_id=p_aoq_id;
 IF existing_count>1 THEN RAISE EXCEPTION 'Multiple existing POs require review' USING ERRCODE='PA002';END IF;
 IF existing_count=1 THEN
  SELECT p.id,p.no INTO STRICT existing FROM public.po p WHERE p.aoq_id=p_aoq_id;
  RETURN QUERY SELECT existing.id::bigint,existing.no::text,false;RETURN;
 END IF;
 SELECT * INTO STRICT checked FROM psms_aoq_api.workflow_offer_v1(source.winning_offer,source.winner,source.winning_amount);
 -- DRAFT PO CLOCK POLICY: Asia/Manila requires owner confirmation before installer assembly.
 instant:=clock_timestamp();stamp:=instant AT TIME ZONE 'Asia/Manila';
 display_date:=to_char(stamp,'Mon DD, YYYY HH12:MI AM');
 counter_key:='PO:'||extract(year FROM stamp)::integer::text;
 INSERT INTO public.identifier_sequence AS counter(sequence_key,last_number) VALUES(counter_key,1)
  ON CONFLICT(sequence_key) DO UPDATE SET last_number=counter.last_number+1 RETURNING last_number INTO next_number;
 LOOP
  document_no:='PO-'||extract(year FROM stamp)::integer::text||'-'||lpad(next_number::text,greatest(4,length(next_number::text)),'0');
  EXIT WHEN NOT EXISTS(SELECT 1 FROM public.po p WHERE p.no=document_no);
  UPDATE public.identifier_sequence SET last_number=last_number+1 WHERE sequence_key=counter_key RETURNING last_number INTO next_number;
 END LOOP;
 FOR item IN SELECT value FROM json_array_elements(checked.items_text::json) LOOP
  item_number:=item_number+1;source_id:=NULL;
  FOREACH field_name IN ARRAY ARRAY['_IAR Item ID','_PO Item ID','_AOQ Item ID','_PR Item ID','_APP Item ID','_PPMP Item ID'] LOOP
   IF item->field_name IS NOT NULL AND (item->field_name)::jsonb NOT IN ('null'::jsonb,'false'::jsonb,'0'::jsonb,'""'::jsonb,'[]'::jsonb,'{}'::jsonb) THEN
    source_id:=item->field_name;EXIT;
   END IF;
  END LOOP;
  replace_source:=source_id IS NOT NULL AND NOT (item::jsonb ? '_PO Item ID');
  fields:='';
  FOR pair IN SELECT key,value FROM json_each(item) LOOP
   IF pair.key='_PO Item ID' OR (pair.key='_Source Item ID' AND replace_source) THEN CONTINUE;END IF;
   IF fields<>'' THEN fields:=fields||',';END IF;
   fields:=fields||to_json(pair.key)::text||':'||pair.value::text;
  END LOOP;
  IF fields<>'' THEN fields:=fields||',';END IF;
  fields:=fields||'"_PO Item ID":'||to_json(document_no||'-ITEM-'||lpad(item_number::text,greatest(2,length(item_number::text)),'0'))::text;
  IF replace_source THEN fields:=fields||',"_Source Item ID":'||source_id::text;END IF;
  IF item_number>1 THEN output_text:=output_text||',';END IF;
  output_text:=output_text||'{'||fields||'}';
 END LOOP;
 INSERT INTO public.po(no,aoq_id,supplier,status,created_at,items,total)
 VALUES(document_no,p_aoq_id,source.winner,'For Review',display_date,'['||output_text||']',psms_aoq_api.round2_v1(checked.total))
 RETURNING id INTO new_id;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(display_date,actor.actor_username,'Generated PO','PO',document_no,
  'from approved OCR AOQ '||source.no||'; '||item_number::text||' winning offer item(s)');
 -- Caller must commit; a returned receipt does not prove deferred-trigger/COMMIT success.
 RETURN QUERY SELECT new_id,document_no,true;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.create_pr_from_approved_app_v1(p_app_id bigint, p_purpose text, p_source_hash text, p_validated_total double precision)
 RETURNS TABLE(pr_id bigint, pr_no text, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_app record;v_source record;v_existing record;v_items json;v_item json;
 v_pair record;v_source_id json;v_field text;v_fields text;v_output text:='';v_index integer:=0;
 v_number bigint;v_no text;v_id bigint;v_year integer;v_key text;v_stamp timestamp;v_purpose text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 SELECT id,no,ppmp_id,year,office,status,items,total INTO v_app FROM public.app_plan WHERE id=p_app_id FOR UPDATE;
 IF NOT FOUND OR v_app.status IS DISTINCT FROM 'Approved' THEN RAISE EXCEPTION 'Approved APP required' USING ERRCODE='PA002';END IF;
 SELECT id,no,status,items INTO v_source FROM public.ppmp WHERE id=v_app.ppmp_id FOR SHARE;
 IF NOT FOUND OR v_source.status IS DISTINCT FROM 'Approved' THEN RAISE EXCEPTION 'Approved PPMP required' USING ERRCODE='PA002';END IF;
 IF (SELECT count(*) FROM public.pr WHERE app_id=p_app_id)>1 THEN RAISE EXCEPTION 'Existing PR ambiguity' USING ERRCODE='PA002';END IF;
 SELECT id,no INTO v_existing FROM public.pr WHERE app_id=p_app_id;
 IF FOUND THEN RETURN QUERY SELECT v_existing.id,v_existing.no,false;RETURN;END IF;
 IF p_source_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(nullif(v_app.items,''),v_source.items),'UTF8')),'hex')
  OR p_validated_total IS NULL OR p_validated_total::text IN ('NaN','Infinity','-Infinity') OR p_validated_total<=0
  OR v_app.total IS NULL OR v_app.total::text IN ('NaN','Infinity','-Infinity') OR v_app.total<=0
  OR abs(p_validated_total-v_app.total)>0.001 THEN
  RAISE EXCEPTION 'Approved source changed or total requires review' USING ERRCODE='PA002';END IF;
 IF p_purpose IS NULL OR length(p_purpose)>2000 OR p_purpose ~ ('['||chr(1)||'-'||chr(8)||chr(11)||chr(12)||chr(14)||'-'||chr(31)||']') THEN
  RAISE EXCEPTION 'Valid purpose required' USING ERRCODE='PA001';END IF;
 v_items:=coalesce(nullif(v_app.items,''),v_source.items)::json;
 IF json_typeof(v_items) IS DISTINCT FROM 'array' OR json_array_length(v_items) NOT BETWEEN 1 AND 200 THEN
  RAISE EXCEPTION 'Complete approved source items required' USING ERRCODE='PA001';END IF;
 v_year:=v_app.year;
 IF v_year IS NULL OR v_year NOT BETWEEN 1900 AND 9999 THEN RAISE EXCEPTION 'Approved APP procurement year required' USING ERRCODE='PA001';END IF;
 v_stamp:=clock_timestamp() AT TIME ZONE 'Asia/Manila';v_key:='PR:'||v_year;
 INSERT INTO public.identifier_sequence AS counter(sequence_key,last_number) VALUES(v_key,1)
  ON CONFLICT(sequence_key) DO UPDATE SET last_number=counter.last_number+1 RETURNING last_number INTO v_number;
 LOOP
  v_no:='PR-'||v_year||'-'||lpad(v_number::text,greatest(4,length(v_number::text)),'0');
  EXIT WHEN NOT EXISTS(SELECT 1 FROM public.pr WHERE no=v_no);
  UPDATE public.identifier_sequence SET last_number=last_number+1 WHERE sequence_key=v_key RETURNING last_number INTO v_number;
 END LOOP;
 FOR v_item IN SELECT value FROM json_array_elements(v_items) LOOP
  IF json_typeof(v_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid approved item' USING ERRCODE='PA001';END IF;
  v_index:=v_index+1;v_source_id:=NULL;v_fields:='';
  FOREACH v_field IN ARRAY ARRAY['_IAR Item ID','_PO Item ID','_AOQ Item ID','_PR Item ID','_APP Item ID','_PPMP Item ID'] LOOP
   IF coalesce(v_item->>v_field,'')<>'' THEN v_source_id:=v_item->v_field;EXIT;END IF;
  END LOOP;
  FOR v_pair IN SELECT source_field.key,source_field.value FROM json_each(v_item) AS source_field LOOP
   IF v_pair.key='_PR Item ID' OR (v_pair.key='_Source Item ID' AND v_source_id IS NOT NULL AND NOT(v_item::jsonb ? '_PR Item ID')) THEN CONTINUE;END IF;
   v_fields:=v_fields||CASE WHEN v_fields='' THEN '' ELSE ',' END||to_json(v_pair.key)::text||':'||v_pair.value::text;
  END LOOP;
  IF v_source_id IS NOT NULL AND NOT(v_item::jsonb ? '_PR Item ID') THEN
   v_fields:=v_fields||CASE WHEN v_fields='' THEN '' ELSE ',' END||'"_Source Item ID":'||v_source_id::text;END IF;
  v_fields:=v_fields||CASE WHEN v_fields='' THEN '' ELSE ',' END||'"_PR Item ID":'||to_json(v_no||'-ITEM-'||lpad(v_index::text,greatest(2,length(v_index::text)),'0'))::text;
  v_output:=v_output||CASE WHEN v_output='' THEN '' ELSE ',' END||'{'||v_fields||'}';
 END LOOP;
 v_purpose:=btrim(p_purpose);
 IF v_purpose='' THEN
  SELECT string_agg(objective,E'\n' ORDER BY first_position) INTO v_purpose FROM (
   SELECT btrim(item.value->>'General Description and Objective of the Project to be Procured') objective,min(item.position) first_position
   FROM json_array_elements(v_items) WITH ORDINALITY AS item(value,position)
   WHERE coalesce(btrim(item.value->>'General Description and Objective of the Project to be Procured'),'')<>''
   GROUP BY btrim(item.value->>'General Description and Objective of the Project to be Procured')) AS objectives;
 END IF;
 INSERT INTO public.pr(no,app_id,ppmp_id,office,purpose,status,created_at,items,total)
 VALUES(v_no,v_app.id,v_app.ppmp_id,v_app.office,coalesce(v_purpose,'Purpose not recorded in approved source.'),'For Review',
  to_char(v_stamp,'Mon DD, YYYY HH12:MI AM'),'['||v_output||']',p_validated_total) RETURNING id INTO v_id;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details) VALUES(to_char(v_stamp,'Mon DD, YYYY HH12:MI AM'),
  v_actor.actor_username,'Created PR','PR',v_no,'Created from approved APP '||v_app.no||'; source PPMP '||v_source.no||'; '||v_index||' item(s)');
 RETURN QUERY SELECT v_id,v_no,true;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.lock_po_for_workflow_v2(p_po_id bigint, p_purpose text)
 RETURNS TABLE(id bigint, no text, aoq_id bigint, supplier text, status text, created_at text, items text, total double precision, pr_id bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_po record;
BEGIN
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 IF p_purpose IS DISTINCT FROM 'iar' THEN RAISE EXCEPTION 'Unsupported receiving boundary' USING ERRCODE='PA001';END IF;
 SELECT target.id,target.no,target.aoq_id,target.supplier,target.status,target.created_at,target.items,target.total,target.pr_id
  INTO v_po FROM public.po AS target WHERE target.id=p_po_id FOR UPDATE;
 IF NOT FOUND OR v_po.status IS DISTINCT FROM 'Approved' THEN RAISE EXCEPTION 'Approved PO required' USING ERRCODE='PA002';END IF;
 PERFORM 1 FROM public.nlp verification WHERE verification.po_id=p_po_id AND verification.status='Approved'
  AND verification.result IN ('Acceptable','Needs Review')
  AND (verification.workflow_version IS NULL OR EXISTS(SELECT 1 FROM psms_documents.pr_po_reviews proof
      WHERE proof.po_id=p_po_id AND proof.nlp_id=verification.id AND proof.pr_id=v_po.pr_id))
  FOR SHARE OF verification;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Approved procurement verification required' USING ERRCODE='PA002';END IF;
 RETURN QUERY SELECT v_po.id,v_po.no,v_po.aoq_id,v_po.supplier,v_po.status,v_po.created_at,v_po.items,v_po.total,v_po.pr_id;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.lock_po_for_workflow_v4(p_po_id bigint, p_purpose text)
 RETURNS TABLE(id bigint, no text, aoq_id bigint, supplier text, status text, created_at text, items text, total double precision, pr_id bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_preview record;v_po record;v_pr record;v_nlp record;v_proof record;
 v_marker jsonb;v_percentage numeric;v_hash text;eligible boolean:=false;
BEGIN
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 IF p_purpose IS DISTINCT FROM 'iar' THEN RAISE EXCEPTION 'Unsupported receiving boundary' USING ERRCODE='PA001';END IF;
 SELECT p.aoq_id,p.pr_id INTO v_preview FROM public.po p WHERE p.id=p_po_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Approved PO required' USING ERRCODE='PA002';END IF;
 -- Source-first order is shared with review/approval. No new lock inversion.
 PERFORM 1 FROM public.aoq a WHERE a.id=v_preview.aoq_id FOR SHARE;
 SELECT r.id,r.status,r.items INTO v_pr FROM public.pr r WHERE r.id=v_preview.pr_id FOR SHARE;
 SELECT p.id,p.no,p.aoq_id,p.supplier,p.status,p.created_at,p.items,p.total,p.pr_id
  INTO v_po FROM public.po p WHERE p.id=p_po_id FOR UPDATE;
 IF NOT FOUND OR v_po.status IS DISTINCT FROM 'Approved'
  OR v_po.aoq_id IS DISTINCT FROM v_preview.aoq_id OR v_po.pr_id IS DISTINCT FROM v_preview.pr_id THEN
  RAISE EXCEPTION 'Approved source PO changed' USING ERRCODE='PA002';END IF;
 FOR v_nlp IN SELECT n.* FROM public.nlp n WHERE n.po_id=p_po_id AND n.status='Approved' ORDER BY n.id FOR SHARE LOOP
  IF v_nlp.workflow_version IS NULL AND v_nlp.result IN ('Acceptable','Needs Review') THEN eligible:=true;EXIT;END IF;
  v_marker:=v_nlp.details::jsonb->'threshold_approval_v4';
  IF v_marker IS NULL THEN
   IF v_nlp.result IN ('Acceptable','Needs Review') AND (v_nlp.workflow_version IS NULL OR EXISTS(
    SELECT 1 FROM psms_documents.pr_po_reviews proof WHERE proof.po_id=p_po_id
     AND proof.nlp_id=v_nlp.id AND proof.pr_id=v_po.pr_id)) THEN eligible:=true;EXIT;END IF;
   CONTINUE;
  END IF;
  IF jsonb_typeof(v_marker) IS DISTINCT FROM 'object' OR v_marker->'version' IS DISTINCT FROM '1'::jsonb
   OR v_nlp.workflow_version IS DISTINCT FROM 2 OR v_nlp.pr_id IS DISTINCT FROM v_po.pr_id
   OR v_pr.id IS NULL OR v_pr.status IS DISTINCT FROM 'Approved'
   OR v_nlp.pr_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_pr.items,''),'UTF8')),'hex')
   OR v_nlp.po_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_po.items,''),'UTF8')),'hex')
   OR v_marker->>'pr_items_hash' IS DISTINCT FROM v_nlp.pr_items_hash
   OR v_marker->>'po_items_hash' IS DISTINCT FROM v_nlp.po_items_hash
   OR v_marker->'technical_comparison' IS DISTINCT FROM v_nlp.details::jsonb->'technical_comparison'
   OR v_nlp.details::jsonb->'reviewed_technical_checks' IS DISTINCT FROM v_nlp.details::jsonb->'technical_comparison' THEN
   CONTINUE;END IF;
  SELECT proof.* INTO v_proof FROM psms_documents.pr_po_reviews proof
   WHERE proof.po_id=p_po_id AND proof.nlp_id=v_nlp.id AND proof.pr_id=v_po.pr_id;
  IF NOT FOUND OR v_proof.pr_items_hash IS DISTINCT FROM v_nlp.pr_items_hash
   OR v_proof.po_items_hash IS DISTINCT FROM v_nlp.po_items_hash THEN CONTINUE;END IF;
  v_hash:=encode(sha256(convert_to(jsonb_build_array(v_nlp.pr_id,v_nlp.po_id,v_nlp.result,v_nlp.confidence,
    v_nlp.details,v_nlp.technical_status,v_nlp.model_version,v_nlp.pr_items_hash,v_nlp.po_items_hash)::text,'UTF8')),'hex');
  IF v_proof.nlp_hash IS DISTINCT FROM v_hash THEN CONTINUE;END IF;
  BEGIN
   v_percentage:=psms_aoq_api.require_ten_percent_review_v4(v_nlp.technical_status,
     v_nlp.details::jsonb->'technical_comparison',v_proof.item_mapping,v_nlp.details::jsonb->'reviewed_technical_checks');
  EXCEPTION WHEN SQLSTATE 'PA001' THEN CONTINUE;END;
  IF v_marker->'percentage' IS DISTINCT FROM to_jsonb(v_percentage) THEN CONTINUE;END IF;
  eligible:=true;EXIT;
 END LOOP;
 IF NOT eligible THEN RAISE EXCEPTION 'Approved reviewed verification required' USING ERRCODE='PA002';END IF;
 RETURN QUERY SELECT v_po.id,v_po.no,v_po.aoq_id,v_po.supplier,v_po.status,v_po.created_at,v_po.items,v_po.total,v_po.pr_id;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.mark_pr_po_reviewed_v3(p_nlp_id bigint, p_mapping jsonb, p_checks jsonb, p_reason text, p_evidence_reference text, p_confirm boolean)
 RETURNS TABLE(nlp_id bigint, po_id bigint, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_role text;v_preview record;v_aoq record;v_pr record;v_po record;v_nlp record;
 v_policy text;v_nlp_hash text;v_stamp timestamptz:=clock_timestamp();v_pr_count integer;v_po_count integer;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 SELECT role INTO v_role FROM public.users WHERE id=v_actor.actor_id;
 SELECT n.po_id,n.pr_id,p.aoq_id INTO v_preview FROM public.nlp n JOIN public.po p ON p.id=n.po_id WHERE n.id=p_nlp_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Verification unavailable' USING ERRCODE='PA004';END IF;
 SELECT id,pr_id,status INTO v_aoq FROM public.aoq WHERE id=v_preview.aoq_id FOR SHARE;
 SELECT id,no,status,items,app_id,ppmp_id,office INTO v_pr FROM public.pr WHERE id=v_preview.pr_id FOR UPDATE;
 SELECT id,no,aoq_id,pr_id,status,items INTO v_po FROM public.po WHERE id=v_preview.po_id FOR UPDATE;
 SELECT verification.id,verification.no,verification.po_id,verification.pr_id,verification.workflow_version,verification.status,
  verification.result,verification.confidence,verification.details,verification.technical_status,verification.model_version,
  verification.pr_items_hash,verification.po_items_hash INTO v_nlp FROM public.nlp AS verification WHERE verification.id=p_nlp_id FOR UPDATE;
 IF v_nlp.workflow_version IS DISTINCT FROM 2 OR v_nlp.status IS DISTINCT FROM 'For Review'
  OR v_nlp.po_id IS DISTINCT FROM v_po.id OR v_nlp.pr_id IS DISTINCT FROM v_pr.id
  OR v_po.aoq_id IS DISTINCT FROM v_aoq.id OR v_po.status IS DISTINCT FROM 'Approved'
  OR v_pr.status IS DISTINCT FROM 'Approved' OR v_aoq.status IS DISTINCT FROM 'Approved'
  OR (v_aoq.pr_id IS NOT NULL AND v_aoq.pr_id IS DISTINCT FROM v_pr.id)
  OR (v_po.pr_id IS NOT NULL AND v_po.pr_id IS DISTINCT FROM v_pr.id) THEN
  RAISE EXCEPTION 'Sources or verification changed' USING ERRCODE='PA002';END IF;
 IF v_nlp.pr_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_pr.items,''),'UTF8')),'hex')
  OR v_nlp.po_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_po.items,''),'UTF8')),'hex') THEN
  RAISE EXCEPTION 'Sources or verification changed' USING ERRCODE='PA002';END IF;

 -- A replacement may be reviewed only while its immutable lineage still matches.
 IF v_nlp.details::jsonb ? 'verification_lineage' OR EXISTS(
  SELECT 1 FROM psms_documents.nlp_legacy_replacements l WHERE l.replacement_nlp_id=v_nlp.id) THEN
  PERFORM 1 FROM psms_documents.nlp_legacy_replacements l JOIN public.nlp old ON old.id=l.legacy_nlp_id
   WHERE l.replacement_nlp_id=v_nlp.id AND l.po_id=v_po.id AND l.pr_id=v_pr.id
    AND v_nlp.details::jsonb->'verification_lineage'->>'legacy_nlp_id'=l.legacy_nlp_id::text
    AND v_nlp.details::jsonb->'verification_lineage'->>'legacy_record_sha256'=l.legacy_record_sha256
    AND encode(sha256(convert_to(to_jsonb(old)::text,'UTF8')),'hex')=l.legacy_record_sha256
   FOR SHARE OF old;
  IF NOT FOUND THEN RAISE EXCEPTION 'Saved legacy lineage changed' USING ERRCODE='PA002';END IF;
 END IF;

 IF v_aoq.pr_id IS NULL THEN
  SELECT policy->>'link_authority' INTO v_policy FROM psms_documents.procurement_policy WHERE singleton;
  IF v_policy IS NULL OR v_policy='PENDING' THEN RAISE EXCEPTION 'Independent PR-PO authorization policy pending' USING ERRCODE='PA005';END IF;
  IF NOT ((v_policy='ADMIN_DOCUMENTED' AND v_role='Admin') OR
          (v_policy='EXISTING_REVIEWERS_DOCUMENTED' AND v_role IN ('Admin','Staff','Inspector'))) THEN
   RAISE EXCEPTION 'Authorized procurement relationship reviewer required' USING ERRCODE='PA003';END IF;
  PERFORM 1 FROM public.app_plan a JOIN public.ppmp m ON m.id=a.ppmp_id
      WHERE a.id=v_pr.app_id AND a.status='Approved' AND m.status='Approved'
       AND (v_pr.ppmp_id IS NULL OR v_pr.ppmp_id=m.id) FOR SHARE OF a,m;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Approved planning evidence required for independent relationship' USING ERRCODE='PA006';END IF;
 END IF;

 IF p_confirm IS DISTINCT FROM true OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 10 AND 2000
  OR p_evidence_reference IS NULL OR length(btrim(p_evidence_reference)) NOT BETWEEN 3 AND 500 THEN
  RAISE EXCEPTION 'Documented review confirmation required' USING ERRCODE='PA001';END IF;
 IF EXISTS(SELECT 1 FROM public.nlp n WHERE n.id=p_nlp_id AND
   (n.reviewed_by IS NOT NULL OR n.reviewed_at IS NOT NULL OR n.review_mapping IS NOT NULL
    OR nullif(btrim(n.relationship_reason),'') IS NOT NULL OR nullif(btrim(n.evidence_reference),'') IS NOT NULL)) THEN
  RAISE EXCEPTION 'Existing human review evidence requires preserved history' USING ERRCODE='PA002';END IF;
 v_pr_count:=jsonb_array_length(v_pr.items::jsonb);v_po_count:=jsonb_array_length(v_po.items::jsonb);
 IF v_pr_count<1 OR v_po_count<1 OR v_nlp.details::jsonb ? 'workflow_review_v3'
  OR v_nlp.result IS NULL OR v_nlp.result NOT IN ('Acceptable','Needs Review','Needs Recanvass','Reject')
  OR jsonb_typeof(p_mapping) IS DISTINCT FROM 'array' OR jsonb_array_length(p_mapping)<>v_pr_count
  OR jsonb_typeof(p_checks) IS DISTINCT FROM 'object'
  OR p_checks IS DISTINCT FROM v_nlp.details::jsonb->'technical_comparison'
  OR p_checks->>'version' IS DISTINCT FROM 'PR_PO_REVIEW_V1'
  OR p_checks->'automatic_approval' IS DISTINCT FROM 'false'::jsonb
  OR p_checks->'human_review_required' IS DISTINCT FROM 'true'::jsonb
  OR p_checks->>'technical_status' IS DISTINCT FROM v_nlp.technical_status
  OR v_nlp.technical_status IS NULL OR v_nlp.technical_status NOT IN ('MATCH','NEEDS_REVIEW')
  OR jsonb_typeof(p_checks->'rows') IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_checks->'rows')<>v_pr_count
  OR jsonb_typeof(p_checks->'source_fields'->'PR') IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_checks->'source_fields'->'PO') IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_checks->'source_fields'->'PR')<>v_pr_count
  OR jsonb_array_length(p_checks->'source_fields'->'PO')<>v_po_count
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_checks->'rows') WITH ORDINALITY row_entry(value,position)
     WHERE row_entry.value->>'pr_position' IS DISTINCT FROM row_entry.position::text
      OR row_entry.value->'po_position' IS DISTINCT FROM p_mapping->(row_entry.position::integer-1))
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_mapping) mapping(value)
     WHERE mapping.value<>'null'::jsonb AND (jsonb_typeof(mapping.value)<>'number'
       OR mapping.value::text !~ '^[1-9][0-9]*$' OR mapping.value::text::numeric>v_po_count)) THEN
  RAISE EXCEPTION 'Saved source-bound review evidence changed' USING ERRCODE='PA001';END IF;
 IF EXISTS(SELECT 1 FROM psms_documents.pr_po_reviews proof WHERE proof.po_id=v_po.id) THEN
  RAISE EXCEPTION 'Official relationship already authorized' USING ERRCODE='PA002';END IF;
 SELECT encode(sha256(convert_to(jsonb_build_array(n.pr_id,n.po_id,n.result,n.confidence,
  n.details::jsonb-'workflow_review_v3',n.technical_status,n.model_version,n.pr_items_hash,n.po_items_hash)::text,'UTF8')),'hex') INTO v_nlp_hash FROM public.nlp n WHERE n.id=p_nlp_id;
 UPDATE public.nlp SET status='Reviewed',reviewed_by=v_actor.actor_id,reviewed_at=v_stamp,
  review_mapping=p_mapping,relationship_reason=btrim(p_reason),evidence_reference=btrim(p_evidence_reference),
  details=(details::jsonb||jsonb_build_object('workflow_review_v3',jsonb_build_object(
    'version',1,'actor_id',v_actor.actor_id,'reviewed_at',v_stamp,'mapping',p_mapping,'checks',p_checks,
    'reason',btrim(p_reason),'evidence_reference',btrim(p_evidence_reference),'verification_sha256',v_nlp_hash)))::text
  WHERE id=p_nlp_id AND status='For Review';
 IF NOT FOUND THEN RAISE EXCEPTION 'Review status changed' USING ERRCODE='PA002';END IF;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(v_stamp AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),v_actor.actor_username,
  'Reviewed PR-PO Verification','NLP',v_nlp.no,
  'PR '||v_pr.no||'; PO '||v_po.no||'; technical '||v_nlp.technical_status||'; evidence: '||btrim(p_evidence_reference));
 -- Review creates neither an official relationship proof nor an IAR permission.
 RETURN QUERY SELECT p_nlp_id,v_po.id,'Reviewed'::text;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.number_v1(j jsonb)
 RETURNS double precision
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET standard_conforming_strings TO 'on'
AS $function$
DECLARE t text; n numeric; f double precision;
BEGIN
 IF j IS NULL OR jsonb_typeof(j) NOT IN ('number','string') THEN RETURN NULL; END IF;
 t:=psms_aoq_api.unicode_v1(psms_aoq_api.space_v1(j #>> '{}'),'digits');
 -- Currency syntax matches current review_number; canonical Flask input is already numeric.
 t:=regexp_replace(t,'^(PHP|PH\.?P|PESOS?|P|₱|USD|\$) *','','i');
 t:=regexp_replace(t,' *(PHP|PH\.?P|PESOS?|P|₱|USD|\$)$','','i');
 IF t COLLATE "C" !~ '^[+-]?(([0-9]{1,3}(,[0-9]{3})+|[0-9]+)(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$' THEN RETURN NULL; END IF;
 BEGIN
  n:=replace(t,',','')::numeric; f:=n::double precision;
 EXCEPTION WHEN numeric_value_out_of_range OR invalid_text_representation THEN RETURN NULL;
 END;
 IF f::text IN ('Infinity','-Infinity','NaN') OR (f=0 AND n<>0) THEN RETURN NULL; END IF;
 IF n=0 AND left(t,1)='-' THEN RETURN '-0'::double precision;END IF;
 RETURN f;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.refresh_pr_po_comparison_v4(p_nlp_id bigint, p_checks jsonb, p_confirm boolean)
 RETURNS TABLE(nlp_id bigint, po_id bigint, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
 SET statement_timeout TO '15s'
AS $function$
DECLARE actor record;preview record;aoq record;pr record;po record;n record;
 role_name text;policy text;old_details jsonb;saved jsonb;old_line jsonb;new_line jsonb;
 old_check jsonb;new_check jsonb;mapping jsonb:='[]';history jsonb;archive jsonb;updated jsonb;
 i integer;j integer;side integer;changed integer:=0;position integer;source_item jsonb;
 source_quantity text;source_unit text;quantity numeric;tail text[];product text[];frequency text[];
 clause text;description text;core jsonb;left_core jsonb;stamp timestamptz:=clock_timestamp();
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 IF p_confirm IS DISTINCT FROM true THEN RAISE EXCEPTION 'Explicit recalculation confirmation required' USING ERRCODE='PA001';END IF;
 SELECT * INTO STRICT actor FROM psms_aoq_api.approval_actor_v1();
 SELECT role INTO role_name FROM public.users WHERE id=actor.actor_id;
 PERFORM 1 FROM psms_documents.procurement_policy p WHERE singleton
  AND p.policy->'enabled'='true'::jsonb AND p.policy->>'po_clock'='ASIA_MANILA';
 IF NOT FOUND THEN RAISE EXCEPTION 'Procurement workflow disabled' USING ERRCODE='PA007';END IF;
 SELECT x.po_id,x.pr_id,p.aoq_id INTO preview FROM public.nlp x JOIN public.po p ON p.id=x.po_id WHERE x.id=p_nlp_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Verification unavailable' USING ERRCODE='PA004';END IF;
 SELECT id,pr_id,status INTO aoq FROM public.aoq WHERE id=preview.aoq_id FOR SHARE;
 SELECT id,no,status,items,app_id,ppmp_id,office INTO pr FROM public.pr WHERE id=preview.pr_id FOR UPDATE;
 SELECT id,no,aoq_id,pr_id,status,items INTO po FROM public.po WHERE id=preview.po_id FOR UPDATE;
 SELECT x.id,x.no,x.po_id,x.pr_id,x.workflow_version,x.result,x.confidence,x.details,x.technical_status,x.status,x.model_version,
  x.pr_items_hash,x.po_items_hash,x.reviewed_by,x.reviewed_at,x.review_mapping,x.relationship_reason,x.evidence_reference,x.staff_decision
 INTO n FROM public.nlp x WHERE x.id=p_nlp_id FOR UPDATE;
 IF n.id IS NULL OR n.workflow_version IS DISTINCT FROM 2 OR n.status IS NULL OR n.status NOT IN ('For Review','Reviewed')
  OR n.po_id IS DISTINCT FROM po.id OR n.pr_id IS DISTINCT FROM pr.id OR po.aoq_id IS DISTINCT FROM aoq.id
  OR po.status IS DISTINCT FROM 'Approved' OR pr.status IS DISTINCT FROM 'Approved' OR aoq.status IS DISTINCT FROM 'Approved'
  OR (aoq.pr_id IS NOT NULL AND aoq.pr_id IS DISTINCT FROM pr.id)
  OR (po.pr_id IS NOT NULL AND po.pr_id IS DISTINCT FROM pr.id)
  OR n.pr_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(pr.items,''),'UTF8')),'hex')
  OR n.po_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(po.items,''),'UTF8')),'hex') THEN
  RAISE EXCEPTION 'Sources or verification changed' USING ERRCODE='PA002';END IF;
 IF EXISTS(SELECT 1 FROM psms_documents.pr_po_reviews proof WHERE proof.po_id=po.id OR proof.pr_id=pr.id OR proof.nlp_id=n.id) THEN
  RAISE EXCEPTION 'Official approval or receiving evidence cannot be recalculated' USING ERRCODE='PA002';END IF;
 IF aoq.pr_id IS NULL THEN
  SELECT p.policy->>'link_authority' INTO policy FROM psms_documents.procurement_policy p WHERE singleton;
  IF policy IS NULL OR policy='PENDING' THEN RAISE EXCEPTION 'Relationship authority pending' USING ERRCODE='PA005';END IF;
  IF NOT ((policy='ADMIN_DOCUMENTED' AND role_name='Admin') OR (policy='EXISTING_REVIEWERS_DOCUMENTED'
    AND role_name IN ('Admin','Staff','Inspector'))) THEN RAISE EXCEPTION 'Authorized reviewer required' USING ERRCODE='PA003';END IF;
  PERFORM 1 FROM public.app_plan a JOIN public.ppmp m ON m.id=a.ppmp_id WHERE a.id=pr.app_id
   AND a.status='Approved' AND m.status='Approved' AND (pr.ppmp_id IS NULL OR pr.ppmp_id=m.id) FOR SHARE OF a,m;
  IF NOT FOUND THEN RAISE EXCEPTION 'Approved planning evidence required' USING ERRCODE='PA006';END IF;
 END IF;
 old_details:=n.details::jsonb;saved:=old_details->'technical_comparison';
 IF old_details ? 'verification_lineage' OR EXISTS(SELECT 1 FROM psms_documents.nlp_legacy_replacements l WHERE l.replacement_nlp_id=n.id) THEN
  PERFORM 1 FROM psms_documents.nlp_legacy_replacements l JOIN public.nlp original ON original.id=l.legacy_nlp_id
   WHERE l.replacement_nlp_id=n.id AND l.po_id=po.id AND l.pr_id=pr.id
    AND old_details->'verification_lineage'->>'legacy_nlp_id'=l.legacy_nlp_id::text
    AND old_details->'verification_lineage'->>'legacy_record_sha256'=l.legacy_record_sha256
    AND encode(sha256(convert_to(to_jsonb(original)::text,'UTF8')),'hex')=l.legacy_record_sha256 FOR SHARE OF original;
  IF NOT FOUND THEN RAISE EXCEPTION 'Saved lineage changed' USING ERRCODE='PA002';END IF;
 END IF;
 IF jsonb_typeof(saved) IS DISTINCT FROM 'object' OR jsonb_typeof(p_checks) IS DISTINCT FROM 'object'
  OR saved->>'version' IS DISTINCT FROM 'PR_PO_REVIEW_V1' OR p_checks->>'wording_policy' IS DISTINCT FROM 'CORE_DESCRIPTION_V2'
  OR (p_checks-ARRAY['rows','technical_status','wording_policy']) IS DISTINCT FROM (saved-ARRAY['rows','technical_status','wording_policy'])
  OR jsonb_typeof(saved->'rows') IS DISTINCT FROM 'array' OR jsonb_typeof(p_checks->'rows') IS DISTINCT FROM 'array'
  OR jsonb_array_length(saved->'rows') NOT BETWEEN 1 AND 200
  OR jsonb_array_length(saved->'rows')<>jsonb_array_length(p_checks->'rows')
  OR p_checks->>'technical_status' IS DISTINCT FROM 'MATCH' THEN
  RAISE EXCEPTION 'Only bounded wording comparison refresh is supported' USING ERRCODE='PA001';END IF;
 FOR i IN 0..jsonb_array_length(saved->'rows')-1 LOOP
  old_line:=saved->'rows'->i;new_line:=p_checks->'rows'->i;
  IF (old_line-'checks') IS DISTINCT FROM (new_line-'checks') OR jsonb_typeof(old_line->'checks') IS DISTINCT FROM 'array'
   OR jsonb_typeof(new_line->'checks') IS DISTINCT FROM 'array'
   OR jsonb_array_length(old_line->'checks')<>jsonb_array_length(new_line->'checks') THEN
   RAISE EXCEPTION 'Item correspondence or check coverage changed' USING ERRCODE='PA001';END IF;
  mapping:=mapping||jsonb_build_array(new_line->'po_position');
  FOR j IN 0..jsonb_array_length(old_line->'checks')-1 LOOP
   old_check:=old_line->'checks'->j;new_check:=new_line->'checks'->j;
   IF old_check IS NOT DISTINCT FROM new_check THEN CONTINUE;END IF;
   IF old_check->>'attribute' IS DISTINCT FROM 'source specification wording'
    OR old_check->>'state' IS DISTINCT FROM 'REQUIRES_HUMAN_REVIEW'
    OR new_check->>'state' IS DISTINCT FROM 'MATCH' OR (old_check-'state') IS DISTINCT FROM (new_check-'state')
    OR old_check->'conditional_on_identity' IS DISTINCT FROM 'false'::jsonb THEN
    RAISE EXCEPTION 'Only an equivalent wording check may change' USING ERRCODE='PA001';END IF;
   -- Independent SQL grammar mirrors CORE_DESCRIPTION_V2; unknown requirements
   -- cannot be waived by a forged browser comparison or a similarity score.
   FOR side IN 0..1 LOOP
    description:=CASE WHEN side=0 THEN old_check->>'requested' ELSE old_check->>'offered' END;
    position:=CASE WHEN side=0 THEN (old_line->>'pr_position')::integer ELSE (old_line->>'po_position')::integer END;
    source_item:=(CASE WHEN side=0 THEN pr.items::jsonb ELSE po.items::jsonb END)->(position-1);
    source_quantity:=coalesce(nullif(source_item->>'Quantity',''),nullif(source_item->>'quantity',''),nullif(source_item->>'qty',''),
     nullif(source_item->>'QTY',''),nullif(source_item->>'Requested Quantity',''),nullif(source_item->>'Awarded Quantity',''));
    source_unit:=lower(btrim(coalesce(nullif(source_item->>'Unit',''),nullif(source_item->>'unit',''),
     nullif(source_item->>'Unit of Measure',''),nullif(source_item->>'unit_of_measure',''),nullif(source_item->>'uom',''))));
    IF source_quantity IS NULL OR source_quantity !~ '^[+]?[0-9]+([.][0-9]+)?$' THEN
     RAISE EXCEPTION 'Valid source quantity required for wording refresh' USING ERRCODE='PA001';END IF;
    quantity:=source_quantity::numeric;
    source_unit:=CASE WHEN source_unit IN ('pc','pcs','piece','pieces') THEN 'piece'
                     WHEN source_unit IN ('unit','units') THEN 'unit' ELSE source_unit END;
    core:='{}';
    FOR clause IN SELECT btrim(x) FROM regexp_split_to_table(lower(regexp_replace(description,'\s+',' ','g')),'[,;]') x LOOP
     IF clause='' OR clause IN ('plug-and-play','plug and play','compatible with standard office computers') THEN CONTINUE;END IF;
     tail:=regexp_match(clause,'\s+([0-9]+(?:\.[0-9]+)?)\s+(pcs?|pieces?|units?)$');
     IF tail IS NOT NULL THEN
      IF tail[1]::numeric<>quantity OR (CASE WHEN tail[2] IN ('pc','pcs','piece','pieces') THEN 'piece' ELSE 'unit' END) IS DISTINCT FROM source_unit THEN
       RAISE EXCEPTION 'Embedded quantity or unit differs' USING ERRCODE='PA001';END IF;
      clause:=btrim(regexp_replace(clause,'\s+([0-9]+(?:\.[0-9]+)?)\s+(pcs?|pieces?|units?)$',''));
     END IF;
     product:=regexp_match(clause,'^(?:([0-9]+(?:\.[0-9]+)?)\s+)?wireless optical mouse$');
     IF clause='wireless optical mouse' OR product IS NOT NULL THEN
      IF product[1] IS NOT NULL AND product[1]::numeric<>quantity THEN
       RAISE EXCEPTION 'Embedded quantity differs' USING ERRCODE='PA001';END IF;
      core:=core||'{"product":"wireless optical mouse"}';CONTINUE;
     END IF;
     frequency:=regexp_match(clause,'^([0-9]+(?:\.[0-9]+)?)\s*ghz(?: connection)?$');
     IF frequency IS NOT NULL THEN
      core:=core||jsonb_build_object('frequency',coalesce(core->'frequency','{}')||jsonb_build_object(trim_scale(frequency[1]::numeric)::text,true));CONTINUE;
     END IF;
     IF clause='usb receiver' THEN core:=core||'{"receiver":"usb"}';CONTINUE;END IF;
     RAISE EXCEPTION 'Unknown, mandatory or negative description clause' USING ERRCODE='PA001';
    END LOOP;
    IF core->>'product' IS DISTINCT FROM 'wireless optical mouse' THEN RAISE EXCEPTION 'Explicit mouse product required' USING ERRCODE='PA001';END IF;
    IF side=0 THEN left_core:=core;
    ELSIF core IS DISTINCT FROM left_core THEN RAISE EXCEPTION 'Core product attributes differ' USING ERRCODE='PA001';END IF;
   END LOOP;
   changed:=changed+1;
  END LOOP;
 END LOOP;
 IF changed=0 OR psms_aoq_api.require_ten_percent_review_v4('MATCH',p_checks,mapping,p_checks) IS DISTINCT FROM 0 THEN
  RAISE EXCEPTION 'Refresh requires final zero discrepancy and changed wording' USING ERRCODE='PA001';END IF;
 history:=coalesce(old_details->'comparison_revisions_v4','[]');
 IF jsonb_typeof(history) IS DISTINCT FROM 'array' OR jsonb_array_length(history)>=50 THEN
  RAISE EXCEPTION 'Comparison history needs separate review' USING ERRCODE='PA002';END IF;
 archive:=jsonb_build_object('archived_at',stamp,'archived_by',actor.actor_id,'reason','CORE_DESCRIPTION_V2 confirmed recalculation',
  'technical_comparison',saved,'technical_status',n.technical_status,'status',n.status,'reviewed_by',n.reviewed_by,'reviewed_at',n.reviewed_at,
  'review_mapping',n.review_mapping,'relationship_reason',n.relationship_reason,'evidence_reference',n.evidence_reference,
  'staff_decision',n.staff_decision,'workflow_review_v3',old_details->'workflow_review_v3',
  'threshold_approval_v4',old_details->'threshold_approval_v4','reviewed_technical_checks',old_details->'reviewed_technical_checks');
 updated:=(old_details-ARRAY['workflow_review_v3','threshold_approval_v4','reviewed_technical_checks'])||jsonb_build_object(
  'technical_comparison',p_checks,'comparison_revisions_v4',history||jsonb_build_array(archive));
 IF octet_length(updated::text)>4194304 THEN RAISE EXCEPTION 'Comparison history size limit' USING ERRCODE='PA001';END IF;
 UPDATE public.nlp SET details=updated::text,technical_status='MATCH',status='For Review',reviewed_by=NULL,reviewed_at=NULL,
  review_mapping=NULL,relationship_reason=NULL,evidence_reference=NULL,staff_decision=NULL WHERE id=p_nlp_id;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(stamp AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),actor.actor_username,
  'Recalculated PR-PO Comparison','NLP',n.no,'Prior review archived; unchanged sources; bounded wording comparison recalculated to 0%; fresh review required');
 RETURN QUERY SELECT n.id,po.id,'For Review'::text;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.require_saved_technical_match_v2(p_saved_status text, p_saved jsonb, p_mapping jsonb, p_current jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE n integer;i integer;s jsonb;c jsonb;position_value jsonb;
BEGIN
 -- This deliberately cannot promote an unresolved saved comparison. A future
 -- legitimate re-evaluation needs its own reviewed source-bound persistence path.
 IF p_saved_status IS DISTINCT FROM 'MATCH'
  OR jsonb_typeof(p_saved) IS DISTINCT FROM 'object'
  OR jsonb_typeof(p_current) IS DISTINCT FROM 'object'
  OR jsonb_typeof(p_mapping) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'Stored server technical match required' USING ERRCODE='PA001';END IF;
 IF p_saved->>'technical_status' IS DISTINCT FROM 'MATCH'
  OR p_current->>'technical_status' IS DISTINCT FROM 'MATCH'
  OR p_saved->>'version' IS DISTINCT FROM 'PR_PO_REVIEW_V1'
  OR p_current->>'version' IS DISTINCT FROM 'PR_PO_REVIEW_V1'
  OR p_saved->'extra_or_unallocated_items' IS DISTINCT FROM '[]'::jsonb
  OR p_saved->'missing_or_unresolved_pr_items' IS DISTINCT FROM '[]'::jsonb
  OR p_current->'extra_or_unallocated_items' IS DISTINCT FROM '[]'::jsonb
  OR p_current->'missing_or_unresolved_pr_items' IS DISTINCT FROM '[]'::jsonb
  OR jsonb_typeof(p_saved->'rows') IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_current->'rows') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'Complete stored technical evidence required' USING ERRCODE='PA001';END IF;
 n:=jsonb_array_length(p_saved->'rows');
 IF n<1 OR jsonb_array_length(p_mapping)<>n OR jsonb_array_length(p_current->'rows')<>n
  OR p_saved->'source_fields' IS DISTINCT FROM p_current->'source_fields'
  OR jsonb_typeof(p_saved->'source_fields') IS DISTINCT FROM 'object'
  OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(p_mapping))<>n THEN
  RAISE EXCEPTION 'Stored correspondence required' USING ERRCODE='PA001';END IF;
 FOR i IN 0..n-1 LOOP
  position_value:=p_mapping->i;
  IF jsonb_typeof(position_value) IS DISTINCT FROM 'number'
   OR position_value::text !~ '^[1-9][0-9]*$' THEN
   RAISE EXCEPTION 'Valid correspondence required' USING ERRCODE='PA001';END IF;
  IF position_value::numeric>n THEN
   RAISE EXCEPTION 'Valid correspondence required' USING ERRCODE='PA001';END IF;
  s:=p_saved->'rows'->i;c:=p_current->'rows'->i;
  IF jsonb_typeof(s) IS DISTINCT FROM 'object' OR jsonb_typeof(c) IS DISTINCT FROM 'object'
   OR s->'pr_position' IS DISTINCT FROM to_jsonb(i+1)
   OR c->'pr_position' IS DISTINCT FROM to_jsonb(i+1)
   OR s->'po_position' IS DISTINCT FROM position_value
   OR c->'po_position' IS DISTINCT FROM position_value
   OR s->'pr_reference' IS DISTINCT FROM c->'pr_reference'
   OR s->'po_reference' IS DISTINCT FROM c->'po_reference'
   OR jsonb_typeof(s->'checks') IS DISTINCT FROM 'array'
   OR jsonb_typeof(c->'checks') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'Stored correspondence required' USING ERRCODE='PA001';END IF;
  IF jsonb_array_length(s->'checks')<2 OR s->'checks' IS DISTINCT FROM c->'checks'
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'checks') AS check_row(value)
       WHERE check_row.value->>'state' IS DISTINCT FROM 'MATCH'
        OR check_row.value->'conditional_on_identity' IS DISTINCT FROM 'false'::jsonb
        OR nullif(btrim(check_row.value->>'attribute'),'') IS NULL) THEN
   RAISE EXCEPTION 'Stored attribute compliance required' USING ERRCODE='PA001';END IF;
 END LOOP;
 -- identity/similarity labels may change during confirmation; positions,
 -- attributes, values and compliance findings cannot change through this call.
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.require_ten_percent_review_v4(p_technical_status text, p_saved jsonb, p_mapping jsonb, p_checks jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
AS $function$
DECLARE n integer;pos integer;q integer;line jsonb;c jsonb;side text;source jsonb;field jsonb;
 seen integer[]:='{}';refs text[];check_count integer;quantity_count integer;unit_count integer;
 affected integer:=0;line_affected boolean;a numeric;b numeric;left_unit text;right_unit text;percent numeric;
BEGIN
 IF p_technical_status IS NULL OR p_technical_status NOT IN ('MATCH','NEEDS_REVIEW')
  OR jsonb_typeof(p_saved) IS DISTINCT FROM 'object' OR p_saved IS DISTINCT FROM p_checks
  OR p_saved->>'version' IS DISTINCT FROM 'PR_PO_REVIEW_V1'
  OR p_saved->>'technical_status' IS DISTINCT FROM p_technical_status
  OR p_saved->'extra_or_unallocated_items' IS DISTINCT FROM '[]'::jsonb
  OR p_saved->'missing_or_unresolved_pr_items' IS DISTINCT FROM '[]'::jsonb
  OR jsonb_typeof(p_saved->'rows') IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_saved->'source_fields') IS DISTINCT FROM 'object'
  OR jsonb_typeof(p_mapping) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'Complete unchanged source-bound review required' USING ERRCODE='PA001';END IF;
 n:=jsonb_array_length(p_saved->'rows');
 IF n NOT BETWEEN 1 AND 200 OR jsonb_array_length(p_mapping)<>n THEN
  RAISE EXCEPTION 'Complete one-to-one item coverage required' USING ERRCODE='PA001';END IF;
 FOREACH side IN ARRAY ARRAY['PR','PO'] LOOP
  IF jsonb_typeof(p_saved->'source_fields'->side) IS DISTINCT FROM 'array'
   OR jsonb_array_length(p_saved->'source_fields'->side)<>n THEN
   RAISE EXCEPTION 'Complete source fields required' USING ERRCODE='PA001';END IF;
  refs:='{}';
  FOR source IN SELECT value FROM jsonb_array_elements(p_saved->'source_fields'->side) LOOP
   IF jsonb_typeof(source) IS DISTINCT FROM 'object'
    OR jsonb_typeof(source->'reference') IS DISTINCT FROM 'string'
    OR length(btrim(source->>'reference'))=0 OR source->>'reference'=ANY(refs)
    OR jsonb_typeof(source->'fields') IS DISTINCT FROM 'array' OR jsonb_array_length(source->'fields')=0 THEN
    RAISE EXCEPTION 'Unique bound source references required' USING ERRCODE='PA001';END IF;
   refs:=array_append(refs,source->>'reference');
   FOR field IN SELECT value FROM jsonb_array_elements(source->'fields') LOOP
    IF jsonb_typeof(field) IS DISTINCT FROM 'string' OR length(btrim(field#>>'{}'))=0 THEN
     RAISE EXCEPTION 'Nonempty source fields required' USING ERRCODE='PA001';END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 FOR line,pos IN SELECT value,ordinality::integer FROM jsonb_array_elements(p_saved->'rows') WITH ORDINALITY LOOP
  IF jsonb_typeof(line) IS DISTINCT FROM 'object' OR line->>'identity' IS DISTINCT FROM 'EXACT_NAME'
   OR jsonb_typeof(line->'pr_position') IS DISTINCT FROM 'number' OR line->>'pr_position' IS DISTINCT FROM pos::text
   OR jsonb_typeof(line->'po_position') IS DISTINCT FROM 'number'
   OR line->>'po_position' !~ '^[1-9][0-9]*$'
   OR jsonb_typeof(p_mapping->(pos-1)) IS DISTINCT FROM 'number'
   OR p_mapping->(pos-1) IS DISTINCT FROM line->'po_position'
   OR jsonb_typeof(line->'checks') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'Exact one-to-one item identity required' USING ERRCODE='PA001';END IF;
  IF (line->>'po_position')::numeric NOT BETWEEN 1 AND n THEN
   RAISE EXCEPTION 'Item position outside source coverage' USING ERRCODE='PA001';END IF;
  q:=(line->>'po_position')::integer;
  IF q=ANY(seen) OR line->>'pr_reference' IS DISTINCT FROM p_saved#>>ARRAY['source_fields','PR',(pos-1)::text,'reference']
   OR line->>'po_reference' IS DISTINCT FROM p_saved#>>ARRAY['source_fields','PO',(q-1)::text,'reference'] THEN
   RAISE EXCEPTION 'Source item references changed or duplicated' USING ERRCODE='PA001';END IF;
  seen:=array_append(seen,q);check_count:=0;quantity_count:=0;unit_count:=0;line_affected:=false;
  FOR c IN SELECT value FROM jsonb_array_elements(line->'checks') LOOP
   check_count:=check_count+1;
   IF jsonb_typeof(c) IS DISTINCT FROM 'object' OR jsonb_typeof(c->'attribute') IS DISTINCT FROM 'string'
    OR length(btrim(c->>'attribute'))=0 OR c->>'state' IS NULL OR c->>'state' NOT IN ('MATCH','MISMATCH')
    OR c->'conditional_on_identity' IS DISTINCT FROM 'false'::jsonb
    OR c->'requested' IS NULL OR c->'offered' IS NULL
    OR c->'requested'=ANY(ARRAY['null','false','true','""','[]','{}']::jsonb[])
    OR c->'offered'=ANY(ARRAY['null','false','true','""','[]','{}']::jsonb[])
    OR (jsonb_typeof(c->'requested')='string' AND length(btrim(c->>'requested'))=0)
    OR (jsonb_typeof(c->'offered')='string' AND length(btrim(c->>'offered'))=0) THEN
    RAISE EXCEPTION 'Every saved check must have a final explicit finding' USING ERRCODE='PA001';END IF;
   IF c->>'state'='MISMATCH' THEN line_affected:=true;END IF;
   IF c->>'attribute'='quantity' THEN
    quantity_count:=quantity_count+1;
    BEGIN a:=(c->>'requested')::numeric;b:=(c->>'offered')::numeric;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
     RAISE EXCEPTION 'Finite positive quantities required' USING ERRCODE='PA001';END;
    IF a::text IN ('NaN','Infinity','-Infinity') OR b::text IN ('NaN','Infinity','-Infinity') OR a<=0 OR b<=0
     OR c->>'state' IS DISTINCT FROM (CASE WHEN a=b THEN 'MATCH' ELSE 'MISMATCH' END) THEN
     RAISE EXCEPTION 'Quantity finding differs from source numbers' USING ERRCODE='PA001';END IF;
   ELSIF c->>'attribute'='unit' THEN
    unit_count:=unit_count+1;
    IF jsonb_typeof(c->'requested') IS DISTINCT FROM 'string' OR jsonb_typeof(c->'offered') IS DISTINCT FROM 'string'
     OR c->>'state' IS DISTINCT FROM 'MATCH' THEN
     RAISE EXCEPTION 'Compatible confirmed source units required' USING ERRCODE='PA001';END IF;
    left_unit:=lower(regexp_replace(btrim(c->>'requested'),'\s+',' ','g'));
    right_unit:=lower(regexp_replace(btrim(c->>'offered'),'\s+',' ','g'));
    left_unit:=CASE left_unit WHEN 'pc' THEN 'piece' WHEN 'pcs' THEN 'piece' WHEN 'pieces' THEN 'piece'
     WHEN 'units' THEN 'unit' WHEN 'reams' THEN 'ream' WHEN 'bottles' THEN 'bottle' WHEN 'sets' THEN 'set' ELSE left_unit END;
    right_unit:=CASE right_unit WHEN 'pc' THEN 'piece' WHEN 'pcs' THEN 'piece' WHEN 'pieces' THEN 'piece'
     WHEN 'units' THEN 'unit' WHEN 'reams' THEN 'ream' WHEN 'bottles' THEN 'bottle' WHEN 'sets' THEN 'set' ELSE right_unit END;
    IF left_unit<>right_unit THEN RAISE EXCEPTION 'Source units do not match' USING ERRCODE='PA001';END IF;
   END IF;
  END LOOP;
  IF check_count<2 OR quantity_count<>1 OR unit_count<>1 THEN
   RAISE EXCEPTION 'Exactly one quantity and unit finding required per item' USING ERRCODE='PA001';END IF;
  IF line_affected THEN affected:=affected+1;END IF;
 END LOOP;
 IF (affected=0) IS DISTINCT FROM (p_technical_status='MATCH') THEN
  RAISE EXCEPTION 'Technical status differs from saved findings' USING ERRCODE='PA001';END IF;
 percent:=100::numeric*affected/n;
 IF percent>10 THEN RAISE EXCEPTION 'Final discrepancy exceeds 10 percent' USING ERRCODE='PA001';END IF;
 RETURN percent;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.review_approved_pr_po_verification_v2(p_nlp_id bigint, p_mapping jsonb, p_checks jsonb, p_reason text, p_evidence_reference text, p_confirm boolean)
 RETURNS TABLE(nlp_id bigint, po_id bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_role text;v_preview record;v_aoq record;v_pr record;v_po record;v_nlp record;
 v_policy text;v_nlp_hash text;v_stamp timestamptz:=clock_timestamp();v_pr_count integer;v_po_count integer;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 SELECT role INTO v_role FROM public.users WHERE id=v_actor.actor_id;
 SELECT n.po_id,n.pr_id,p.aoq_id INTO v_preview FROM public.nlp n JOIN public.po p ON p.id=n.po_id WHERE n.id=p_nlp_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Verification unavailable' USING ERRCODE='PA004';END IF;
 SELECT id,pr_id,status INTO v_aoq FROM public.aoq WHERE id=v_preview.aoq_id FOR SHARE;
 SELECT id,no,status,items,app_id,ppmp_id,office INTO v_pr FROM public.pr WHERE id=v_preview.pr_id FOR UPDATE;
 SELECT id,no,aoq_id,pr_id,status,items INTO v_po FROM public.po WHERE id=v_preview.po_id FOR UPDATE;
 SELECT verification.id,verification.no,verification.po_id,verification.pr_id,verification.workflow_version,verification.status,
  verification.result,verification.confidence,verification.details,verification.technical_status,verification.model_version,
  verification.pr_items_hash,verification.po_items_hash INTO v_nlp FROM public.nlp AS verification WHERE verification.id=p_nlp_id FOR UPDATE;
 IF v_nlp.workflow_version IS DISTINCT FROM 2 OR v_nlp.status IS DISTINCT FROM 'For Review'
  OR v_nlp.po_id IS DISTINCT FROM v_po.id OR v_nlp.pr_id IS DISTINCT FROM v_pr.id
  OR v_po.aoq_id IS DISTINCT FROM v_aoq.id OR v_po.status IS DISTINCT FROM 'Approved'
  OR v_pr.status IS DISTINCT FROM 'Approved' OR v_aoq.status IS DISTINCT FROM 'Approved'
  OR (v_aoq.pr_id IS NOT NULL AND v_aoq.pr_id IS DISTINCT FROM v_pr.id)
  OR (v_po.pr_id IS NOT NULL AND v_po.pr_id IS DISTINCT FROM v_pr.id) THEN
  RAISE EXCEPTION 'Sources or verification changed' USING ERRCODE='PA002';END IF;
 IF v_nlp.pr_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_pr.items,''),'UTF8')),'hex')
  OR v_nlp.po_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_po.items,''),'UTF8')),'hex') THEN
  RAISE EXCEPTION 'Sources or verification changed' USING ERRCODE='PA002';END IF;

 -- A replacement may be reviewed only while its immutable lineage still matches.
 IF v_nlp.details::jsonb ? 'verification_lineage' OR EXISTS(
  SELECT 1 FROM psms_documents.nlp_legacy_replacements l WHERE l.replacement_nlp_id=v_nlp.id) THEN
  PERFORM 1 FROM psms_documents.nlp_legacy_replacements l JOIN public.nlp old ON old.id=l.legacy_nlp_id
   WHERE l.replacement_nlp_id=v_nlp.id AND l.po_id=v_po.id AND l.pr_id=v_pr.id
    AND v_nlp.details::jsonb->'verification_lineage'->>'legacy_nlp_id'=l.legacy_nlp_id::text
    AND v_nlp.details::jsonb->'verification_lineage'->>'legacy_record_sha256'=l.legacy_record_sha256
    AND encode(sha256(convert_to(to_jsonb(old)::text,'UTF8')),'hex')=l.legacy_record_sha256
   FOR SHARE OF old;
  IF NOT FOUND THEN RAISE EXCEPTION 'Saved legacy lineage changed' USING ERRCODE='PA002';END IF;
 END IF;

 IF v_aoq.pr_id IS NULL THEN
  SELECT policy->>'link_authority' INTO v_policy FROM psms_documents.procurement_policy WHERE singleton;
  IF v_policy IS NULL OR v_policy='PENDING' THEN RAISE EXCEPTION 'Independent PR-PO authorization policy pending' USING ERRCODE='PA005';END IF;
  IF NOT ((v_policy='ADMIN_DOCUMENTED' AND v_role='Admin') OR
          (v_policy='EXISTING_REVIEWERS_DOCUMENTED' AND v_role IN ('Admin','Staff','Inspector'))) THEN
   RAISE EXCEPTION 'Authorized procurement relationship reviewer required' USING ERRCODE='PA003';END IF;
  PERFORM 1 FROM public.app_plan a JOIN public.ppmp m ON m.id=a.ppmp_id
      WHERE a.id=v_pr.app_id AND a.status='Approved' AND m.status='Approved'
       AND (v_pr.ppmp_id IS NULL OR v_pr.ppmp_id=m.id) FOR SHARE OF a,m;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Approved planning evidence required for independent relationship' USING ERRCODE='PA006';END IF;
 END IF;
 IF p_confirm IS DISTINCT FROM true OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 10 AND 2000
  OR p_evidence_reference IS NULL OR length(btrim(p_evidence_reference)) NOT BETWEEN 3 AND 500 THEN
  RAISE EXCEPTION 'Documented relationship confirmation required' USING ERRCODE='PA001';END IF;
 v_pr_count:=jsonb_array_length(v_pr.items::jsonb);v_po_count:=jsonb_array_length(v_po.items::jsonb);
 IF jsonb_typeof(p_mapping) IS DISTINCT FROM 'array' OR jsonb_typeof(p_checks) IS DISTINCT FROM 'object'
  OR jsonb_array_length(p_mapping)<>v_pr_count OR v_pr_count<>v_po_count
  OR p_checks->>'technical_status' IS DISTINCT FROM 'MATCH'
  OR jsonb_typeof(p_checks->'rows') IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_checks->'rows')<>v_pr_count
  OR p_checks->>'version' IS DISTINCT FROM 'PR_PO_REVIEW_V1'
  OR p_checks->'extra_or_unallocated_items' IS DISTINCT FROM '[]'::jsonb
  OR p_checks->'missing_or_unresolved_pr_items' IS DISTINCT FROM '[]'::jsonb
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_checks->'rows') WITH ORDINALITY AS review_row(value,position)
     WHERE review_row.value->>'identity' IS NULL OR review_row.value->>'identity' NOT IN ('EXACT_NAME','HUMAN_CONFIRMED')
      OR review_row.value->>'pr_position' IS DISTINCT FROM review_row.position::text
      OR review_row.value->'po_position' IS DISTINCT FROM p_mapping->(review_row.position::integer-1)
      OR jsonb_typeof(review_row.value->'checks') IS DISTINCT FROM 'array'
      OR jsonb_array_length(review_row.value->'checks')<2
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(review_row.value->'checks') AS item_check(value)
          WHERE item_check.value->>'state' IS DISTINCT FROM 'MATCH'))
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_mapping) AS mapping_entry(value)
     WHERE jsonb_typeof(mapping_entry.value)<>'number' OR mapping_entry.value::text !~ '^[1-9][0-9]*$'
      OR (mapping_entry.value::text)::numeric>v_po_count)
  OR (SELECT count(DISTINCT mapping_entry.value) FROM jsonb_array_elements(p_mapping) AS mapping_entry(value))<>v_po_count
  OR v_nlp.result IS NULL OR v_nlp.result NOT IN ('Acceptable','Needs Review') THEN
  RAISE EXCEPTION 'Complete reviewed correspondence and technical compliance required' USING ERRCODE='PA001';END IF;
 PERFORM psms_aoq_api.require_saved_technical_match_v2(v_nlp.technical_status,
  v_nlp.details::jsonb->'technical_comparison',p_mapping,p_checks);
 IF EXISTS(SELECT 1 FROM psms_documents.pr_po_reviews AS proof WHERE proof.po_id=v_po.id) THEN
  RAISE EXCEPTION 'Official relationship already reviewed' USING ERRCODE='PA002';END IF;
 IF EXISTS(SELECT 1 FROM psms_documents.pr_po_reviews WHERE pr_id=v_pr.id)
  OR EXISTS(SELECT 1 FROM public.po other_po JOIN public.aoq other_aoq ON other_aoq.id=other_po.aoq_id
     WHERE other_po.id<>v_po.id AND coalesce(other_po.pr_id,other_aoq.pr_id)=v_pr.id
       AND other_po.status IN ('For Review','Approved')) THEN
  RAISE EXCEPTION 'PR already has an active purchase order' USING ERRCODE='PA002';END IF;
 UPDATE public.nlp SET status='Approved',staff_decision=result,reviewed_by=v_actor.actor_id,reviewed_at=v_stamp,
  technical_status='MATCH',review_mapping=p_mapping,relationship_reason=btrim(p_reason),evidence_reference=btrim(p_evidence_reference),
  details=(details::jsonb||jsonb_build_object('reviewed_technical_checks',p_checks,'reviewed_procurement_context',
    jsonb_build_object('pr_app_id',v_pr.app_id,'pr_ppmp_id',v_pr.ppmp_id,'pr_office',v_pr.office)))::text WHERE id=p_nlp_id;
 UPDATE public.po SET pr_id=v_pr.id WHERE id=v_po.id;
 SELECT encode(sha256(convert_to(jsonb_build_array(n.pr_id,n.po_id,n.result,n.confidence,n.details,n.technical_status,n.model_version,n.pr_items_hash,n.po_items_hash)::text,'UTF8')),'hex')
  INTO v_nlp_hash FROM public.nlp n WHERE n.id=p_nlp_id;
 INSERT INTO psms_documents.pr_po_reviews(po_id,pr_id,nlp_id,pr_items_hash,po_items_hash,nlp_hash,
  reviewer_id,reviewed_at,item_mapping,justification,evidence_reference)
 VALUES(v_po.id,v_pr.id,p_nlp_id,v_nlp.pr_items_hash,v_nlp.po_items_hash,v_nlp_hash,v_actor.actor_id,v_stamp,
  p_mapping,btrim(p_reason),btrim(p_evidence_reference));
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(v_stamp AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),v_actor.actor_username,
  'Authorized PR-PO Relationship','NLP',v_nlp.no,'PR '||v_pr.no||'; PO '||v_po.no||'; evidence: '||btrim(p_evidence_reference));
 RETURN QUERY SELECT p_nlp_id,v_po.id;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.review_pr_po_verification_v1(p_nlp_id bigint, p_mapping jsonb, p_checks jsonb, p_reason text, p_evidence_reference text, p_confirm boolean)
 RETURNS TABLE(nlp_id bigint, po_id bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_role text;v_preview record;v_aoq record;v_pr record;v_po record;v_nlp record;
 v_policy text;v_nlp_hash text;v_stamp timestamptz:=clock_timestamp();v_pr_count integer;v_po_count integer;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 SELECT role INTO v_role FROM public.users WHERE id=v_actor.actor_id;
 SELECT n.po_id,n.pr_id,p.aoq_id INTO v_preview FROM public.nlp n JOIN public.po p ON p.id=n.po_id WHERE n.id=p_nlp_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Verification unavailable' USING ERRCODE='PA004';END IF;
 SELECT id,pr_id,status INTO v_aoq FROM public.aoq WHERE id=v_preview.aoq_id FOR SHARE;
 SELECT id,no,status,items,app_id,ppmp_id,office INTO v_pr FROM public.pr WHERE id=v_preview.pr_id FOR UPDATE;
 SELECT id,no,aoq_id,pr_id,status,items INTO v_po FROM public.po WHERE id=v_preview.po_id FOR UPDATE;
 SELECT verification.id,verification.no,verification.po_id,verification.pr_id,verification.workflow_version,verification.status,
  verification.result,verification.confidence,verification.details,verification.technical_status,verification.model_version,
  verification.pr_items_hash,verification.po_items_hash INTO v_nlp FROM public.nlp AS verification WHERE verification.id=p_nlp_id FOR UPDATE;
 IF v_nlp.workflow_version IS DISTINCT FROM 1 OR v_nlp.status IS DISTINCT FROM 'For Review'
  OR v_nlp.po_id IS DISTINCT FROM v_po.id OR v_nlp.pr_id IS DISTINCT FROM v_pr.id
  OR v_po.aoq_id IS DISTINCT FROM v_aoq.id OR v_po.status IS DISTINCT FROM 'For Review'
  OR v_pr.status IS DISTINCT FROM 'Approved' OR v_aoq.status IS DISTINCT FROM 'Approved'
  OR (v_aoq.pr_id IS NOT NULL AND v_aoq.pr_id IS DISTINCT FROM v_pr.id)
  OR (v_po.pr_id IS NOT NULL AND v_po.pr_id IS DISTINCT FROM v_pr.id) THEN
  RAISE EXCEPTION 'Sources or verification changed' USING ERRCODE='PA002';END IF;
 IF v_nlp.pr_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_pr.items,''),'UTF8')),'hex')
  OR v_nlp.po_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_po.items,''),'UTF8')),'hex') THEN
  RAISE EXCEPTION 'Sources or verification changed' USING ERRCODE='PA002';END IF;
 IF v_aoq.pr_id IS NULL THEN
  SELECT policy->>'link_authority' INTO v_policy FROM psms_documents.procurement_policy WHERE singleton;
  IF v_policy IS NULL OR v_policy='PENDING' THEN RAISE EXCEPTION 'Independent PR-PO authorization policy pending' USING ERRCODE='PA005';END IF;
  IF NOT ((v_policy='ADMIN_DOCUMENTED' AND v_role='Admin') OR
          (v_policy='EXISTING_REVIEWERS_DOCUMENTED' AND v_role IN ('Admin','Staff','Inspector'))) THEN
   RAISE EXCEPTION 'Authorized procurement relationship reviewer required' USING ERRCODE='PA003';END IF;
  PERFORM 1 FROM public.app_plan a JOIN public.ppmp m ON m.id=a.ppmp_id
      WHERE a.id=v_pr.app_id AND a.status='Approved' AND m.status='Approved'
       AND (v_pr.ppmp_id IS NULL OR v_pr.ppmp_id=m.id) FOR SHARE OF a,m;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Approved planning evidence required for independent relationship' USING ERRCODE='PA006';END IF;
 END IF;
 IF p_confirm IS DISTINCT FROM true OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 10 AND 2000
  OR p_evidence_reference IS NULL OR length(btrim(p_evidence_reference)) NOT BETWEEN 3 AND 500 THEN
  RAISE EXCEPTION 'Documented relationship confirmation required' USING ERRCODE='PA001';END IF;
 v_pr_count:=jsonb_array_length(v_pr.items::jsonb);v_po_count:=jsonb_array_length(v_po.items::jsonb);
 IF jsonb_typeof(p_mapping) IS DISTINCT FROM 'array' OR jsonb_typeof(p_checks) IS DISTINCT FROM 'object'
  OR jsonb_array_length(p_mapping)<>v_pr_count OR v_pr_count<>v_po_count
  OR p_checks->>'technical_status' IS DISTINCT FROM 'MATCH'
  OR jsonb_typeof(p_checks->'rows') IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_checks->'rows')<>v_pr_count
  OR p_checks->>'version' IS DISTINCT FROM 'PR_PO_REVIEW_V1'
  OR p_checks->'extra_or_unallocated_items' IS DISTINCT FROM '[]'::jsonb
  OR p_checks->'missing_or_unresolved_pr_items' IS DISTINCT FROM '[]'::jsonb
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_checks->'rows') WITH ORDINALITY AS review_row(value,position)
     WHERE review_row.value->>'identity' IS NULL OR review_row.value->>'identity' NOT IN ('EXACT_NAME','HUMAN_CONFIRMED')
      OR review_row.value->>'pr_position' IS DISTINCT FROM review_row.position::text
      OR review_row.value->'po_position' IS DISTINCT FROM p_mapping->(review_row.position::integer-1)
      OR jsonb_typeof(review_row.value->'checks') IS DISTINCT FROM 'array'
      OR jsonb_array_length(review_row.value->'checks')<2
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(review_row.value->'checks') AS item_check(value)
          WHERE item_check.value->>'state' IS DISTINCT FROM 'MATCH'))
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_mapping) AS mapping_entry(value)
     WHERE jsonb_typeof(mapping_entry.value)<>'number' OR mapping_entry.value::text !~ '^[1-9][0-9]*$'
      OR (mapping_entry.value::text)::numeric>v_po_count)
  OR (SELECT count(DISTINCT mapping_entry.value) FROM jsonb_array_elements(p_mapping) AS mapping_entry(value))<>v_po_count
  OR v_nlp.result IS NULL OR v_nlp.result NOT IN ('Acceptable','Needs Review') THEN
  RAISE EXCEPTION 'Complete reviewed correspondence and technical compliance required' USING ERRCODE='PA001';END IF;
 PERFORM psms_aoq_api.require_saved_technical_match_v2(v_nlp.technical_status,
  v_nlp.details::jsonb->'technical_comparison',p_mapping,p_checks);
 IF EXISTS(SELECT 1 FROM psms_documents.pr_po_reviews AS proof WHERE proof.po_id=v_po.id) THEN
  RAISE EXCEPTION 'Official relationship already reviewed' USING ERRCODE='PA002';END IF;
 IF EXISTS(SELECT 1 FROM psms_documents.pr_po_reviews WHERE pr_id=v_pr.id)
  OR EXISTS(SELECT 1 FROM public.po other_po JOIN public.aoq other_aoq ON other_aoq.id=other_po.aoq_id
     WHERE other_po.id<>v_po.id AND coalesce(other_po.pr_id,other_aoq.pr_id)=v_pr.id
       AND other_po.status IN ('For Review','Approved')) THEN
  RAISE EXCEPTION 'PR already has an active purchase order' USING ERRCODE='PA002';END IF;
 UPDATE public.nlp SET status='Approved',staff_decision=result,reviewed_by=v_actor.actor_id,reviewed_at=v_stamp,
  technical_status='MATCH',review_mapping=p_mapping,relationship_reason=btrim(p_reason),evidence_reference=btrim(p_evidence_reference),
  details=(details::jsonb||jsonb_build_object('reviewed_technical_checks',p_checks,'reviewed_procurement_context',
    jsonb_build_object('pr_app_id',v_pr.app_id,'pr_ppmp_id',v_pr.ppmp_id,'pr_office',v_pr.office)))::text WHERE id=p_nlp_id;
 UPDATE public.po SET pr_id=v_pr.id WHERE id=v_po.id;
 SELECT encode(sha256(convert_to(jsonb_build_array(n.pr_id,n.po_id,n.result,n.confidence,n.details,n.technical_status,n.model_version,n.pr_items_hash,n.po_items_hash)::text,'UTF8')),'hex')
  INTO v_nlp_hash FROM public.nlp n WHERE n.id=p_nlp_id;
 INSERT INTO psms_documents.pr_po_reviews(po_id,pr_id,nlp_id,pr_items_hash,po_items_hash,nlp_hash,
  reviewer_id,reviewed_at,item_mapping,justification,evidence_reference)
 VALUES(v_po.id,v_pr.id,p_nlp_id,v_nlp.pr_items_hash,v_nlp.po_items_hash,v_nlp_hash,v_actor.actor_id,v_stamp,
  p_mapping,btrim(p_reason),btrim(p_evidence_reference));
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(v_stamp AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),v_actor.actor_username,
  'Authorized PR-PO Relationship','NLP',v_nlp.no,'PR '||v_pr.no||'; PO '||v_po.no||'; evidence: '||btrim(p_evidence_reference));
 RETURN QUERY SELECT p_nlp_id,v_po.id;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.round2_v1(f double precision)
 RETURNS double precision
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET standard_conforming_strings TO 'on'
AS $function$
DECLARE b bytea; exponent integer; mantissa numeric; shift integer;
 numerator numeric; denominator numeric:=1; quotient numeric; remainder numeric; i integer;
BEGIN
 IF f::text IN ('Infinity','-Infinity','NaN') THEN RAISE EXCEPTION 'Invalid reviewed number' USING ERRCODE='PA001'; END IF;
 -- Decode binary64 exactly. Do not use float8::numeric (which rounds significant digits).
 b:=float8send(f);exponent:=((get_byte(b,0)&127)*16)+(get_byte(b,1)>>4);
 mantissa:=get_byte(b,1)&15;
 FOR i IN 2..7 LOOP mantissa:=mantissa*256+get_byte(b,i); END LOOP;
 IF exponent=0 THEN shift:=-1074;
 ELSE mantissa:=mantissa+4503599627370496;shift:=exponent-1075;END IF;
 numerator:=mantissa*100;
 IF shift>=0 THEN
  FOR i IN 1..shift LOOP numerator:=numerator*2;END LOOP;
 ELSE
  FOR i IN 1..(-shift) LOOP denominator:=denominator*2;END LOOP;
 END IF;
 quotient:=div(numerator,denominator);remainder:=mod(numerator,denominator);
 IF remainder*2>denominator OR (remainder*2=denominator AND mod(quotient,2)=1) THEN quotient:=quotient+1;END IF;
 IF get_byte(b,0)>=128 THEN quotient:=-quotient;END IF;
 IF quotient=0 AND get_byte(b,0)>=128 THEN RETURN '-0'::double precision;END IF;
 RETURN (quotient/100)::double precision;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.save_approved_pr_po_verification_v2(p_po_id bigint, p_pr_id bigint, p_pr_hash text, p_po_hash text, p_result text, p_confidence double precision, p_details jsonb, p_model_version text, p_technical_status text)
 RETURNS TABLE(nlp_id bigint, nlp_no text, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_aid bigint;v_aoq record;v_pr record;v_po record;v_existing record;
 v_count bigint;v_number bigint;v_no text;v_id bigint;v_stamp timestamp;v_key text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 PERFORM 1 FROM psms_documents.procurement_policy p WHERE p.singleton AND p.policy->'enabled'='true'::jsonb
  AND p.policy->>'po_clock'='ASIA_MANILA';
 IF NOT FOUND THEN RAISE EXCEPTION 'Procurement workflow disabled' USING ERRCODE='PA007';END IF;

 SELECT aoq_id INTO v_aid FROM public.po WHERE id=p_po_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PO unavailable' USING ERRCODE='PA004';END IF;
 SELECT id,pr_id,status INTO v_aoq FROM public.aoq WHERE id=v_aid FOR SHARE;
 SELECT id,status,items INTO v_pr FROM public.pr WHERE id=p_pr_id FOR SHARE;
 IF NOT FOUND OR v_pr.status IS DISTINCT FROM 'Approved' OR v_aoq.status IS DISTINCT FROM 'Approved'
  OR (v_aoq.pr_id IS NOT NULL AND v_aoq.pr_id IS DISTINCT FROM p_pr_id) THEN
  RAISE EXCEPTION 'Approved source relationship required' USING ERRCODE='PA002';END IF;
 SELECT id,no,aoq_id,pr_id,status,items INTO v_po FROM public.po WHERE id=p_po_id FOR UPDATE;
 IF NOT FOUND OR v_po.aoq_id IS DISTINCT FROM v_aid OR v_po.status IS DISTINCT FROM 'Approved'
  OR (v_po.pr_id IS NOT NULL AND v_po.pr_id IS DISTINCT FROM p_pr_id) THEN
  RAISE EXCEPTION 'PO is not available for verification' USING ERRCODE='PA002';END IF;
 IF p_pr_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_pr.items,''),'UTF8')),'hex')
  OR p_po_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_po.items,''),'UTF8')),'hex') THEN
  RAISE EXCEPTION 'Sources changed during inference' USING ERRCODE='PA002';END IF;
 IF p_details->>'workflow_version' IS DISTINCT FROM '2'
  OR p_details->>'source_pr_id' IS DISTINCT FROM p_pr_id::text OR p_details->>'source_po_id' IS DISTINCT FROM p_po_id::text
  OR jsonb_typeof(p_details->'technical_comparison') IS DISTINCT FROM 'object'
  OR p_details->'technical_comparison'->>'technical_status' IS DISTINCT FROM p_technical_status THEN
  RAISE EXCEPTION 'Source-bound versioned technical evidence required' USING ERRCODE='PA001';END IF;
 IF p_result IS NULL OR p_result NOT IN ('Acceptable','Needs Review','Needs Recanvass','Reject')
  OR p_confidence IS NULL OR p_confidence::text IN ('NaN','Infinity','-Infinity') OR p_confidence NOT BETWEEN 0 AND 100
  OR jsonb_typeof(p_details) IS DISTINCT FROM 'object' OR p_details->'trained_model_used' IS DISTINCT FROM 'true'::jsonb
  OR p_details->'automatic_approval' IS DISTINCT FROM 'false'::jsonb OR octet_length(p_details::text)>4194304
  OR p_model_version IS NULL OR length(p_model_version) NOT BETWEEN 1 AND 200
  OR p_technical_status IS NULL OR p_technical_status NOT IN ('MATCH','NEEDS_REVIEW') THEN
  RAISE EXCEPTION 'Verified model and technical evidence required' USING ERRCODE='PA001';END IF;
 SELECT count(*) INTO v_count FROM public.nlp WHERE po_id=p_po_id;
 IF v_count>1 THEN RAISE EXCEPTION 'Existing verification records require human review' USING ERRCODE='PA002';END IF;
 IF v_count=1 THEN
  SELECT id,no,workflow_version,pr_id,pr_items_hash,po_items_hash INTO STRICT v_existing FROM public.nlp WHERE po_id=p_po_id;
  IF v_existing.workflow_version IS DISTINCT FROM 2 OR v_existing.pr_id IS DISTINCT FROM p_pr_id
   OR v_existing.pr_items_hash IS DISTINCT FROM p_pr_hash OR v_existing.po_items_hash IS DISTINCT FROM p_po_hash THEN
   RAISE EXCEPTION 'An existing verification must be reviewed first' USING ERRCODE='PA002';END IF;
  RETURN QUERY SELECT v_existing.id,v_existing.no,false;RETURN;
 END IF;
 v_stamp:=clock_timestamp() AT TIME ZONE 'Asia/Manila';v_key:='NLP:'||extract(year FROM v_stamp)::integer;
 INSERT INTO public.identifier_sequence AS counter(sequence_key,last_number) VALUES(v_key,1)
  ON CONFLICT(sequence_key) DO UPDATE SET last_number=counter.last_number+1 RETURNING last_number INTO v_number;
 LOOP
  v_no:='NLP-'||extract(year FROM v_stamp)::integer||'-'||lpad(v_number::text,greatest(4,length(v_number::text)),'0');
  EXIT WHEN NOT EXISTS(SELECT 1 FROM public.nlp WHERE no=v_no);
  UPDATE public.identifier_sequence SET last_number=last_number+1 WHERE sequence_key=v_key RETURNING last_number INTO v_number;
 END LOOP;
 INSERT INTO public.nlp(no,po_id,pr_id,result,confidence,staff_decision,remarks,created_at,details,status,
  workflow_version,pr_items_hash,po_items_hash,model_version,technical_status)
 VALUES(v_no,p_po_id,p_pr_id,p_result,p_confidence,NULL,'Human procurement review required',
  to_char(v_stamp,'Mon DD, YYYY HH12:MI AM'),p_details::text,'For Review',2,p_pr_hash,p_po_hash,p_model_version,p_technical_status)
 RETURNING id INTO v_id;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(v_stamp,'Mon DD, YYYY HH12:MI AM'),v_actor.actor_username,'Recorded PR-PO Verification','NLP',v_no,
  'Independent source PR '||p_pr_id||' and PO '||p_po_id||'; human review required');
 RETURN QUERY SELECT v_id,v_no,true;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.save_approved_pr_po_verification_v3(p_po_id bigint, p_pr_id bigint, p_pr_hash text, p_po_hash text, p_result text, p_confidence double precision, p_details jsonb, p_model_version text, p_technical_status text, p_legacy_nlp_id bigint)
 RETURNS TABLE(nlp_id bigint, nlp_no text, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_aid bigint;v_aoq record;v_pr record;v_po record;v_existing record;
 v_count bigint;v_number bigint;v_no text;v_id bigint;v_stamp timestamp;v_key text;
 v_legacy public.nlp%ROWTYPE;v_replacement record;v_legacy_hash text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 PERFORM 1 FROM psms_documents.procurement_policy p WHERE p.singleton AND p.policy->'enabled'='true'::jsonb
  AND p.policy->>'po_clock'='ASIA_MANILA';
 IF NOT FOUND THEN RAISE EXCEPTION 'Procurement workflow disabled' USING ERRCODE='PA007';END IF;

 SELECT aoq_id INTO v_aid FROM public.po WHERE id=p_po_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PO unavailable' USING ERRCODE='PA004';END IF;
 SELECT id,pr_id,status INTO v_aoq FROM public.aoq WHERE id=v_aid FOR SHARE;
 SELECT id,status,items INTO v_pr FROM public.pr WHERE id=p_pr_id FOR SHARE;
 IF NOT FOUND OR v_pr.status IS DISTINCT FROM 'Approved' OR v_aoq.status IS DISTINCT FROM 'Approved'
  OR (v_aoq.pr_id IS NOT NULL AND v_aoq.pr_id IS DISTINCT FROM p_pr_id) THEN
  RAISE EXCEPTION 'Approved source relationship required' USING ERRCODE='PA002';END IF;
 SELECT id,no,aoq_id,pr_id,status,items INTO v_po FROM public.po WHERE id=p_po_id FOR UPDATE;
 IF NOT FOUND OR v_po.aoq_id IS DISTINCT FROM v_aid OR v_po.status IS DISTINCT FROM 'Approved'
  OR (v_po.pr_id IS NOT NULL AND v_po.pr_id IS DISTINCT FROM p_pr_id) THEN
  RAISE EXCEPTION 'PO is not available for verification' USING ERRCODE='PA002';END IF;
 IF p_pr_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_pr.items,''),'UTF8')),'hex')
  OR p_po_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_po.items,''),'UTF8')),'hex') THEN
  RAISE EXCEPTION 'Sources changed during inference' USING ERRCODE='PA002';END IF;
 IF p_details->>'workflow_version' IS DISTINCT FROM '2'
  OR p_details->>'source_pr_id' IS DISTINCT FROM p_pr_id::text OR p_details->>'source_po_id' IS DISTINCT FROM p_po_id::text
  OR jsonb_typeof(p_details->'technical_comparison') IS DISTINCT FROM 'object'
  OR p_details->'technical_comparison'->>'technical_status' IS DISTINCT FROM p_technical_status THEN
  RAISE EXCEPTION 'Source-bound versioned technical evidence required' USING ERRCODE='PA001';END IF;
 IF p_result IS NULL OR p_result NOT IN ('Acceptable','Needs Review','Needs Recanvass','Reject')
  OR p_confidence IS NULL OR p_confidence::text IN ('NaN','Infinity','-Infinity') OR p_confidence NOT BETWEEN 0 AND 100
  OR jsonb_typeof(p_details) IS DISTINCT FROM 'object' OR p_details->'trained_model_used' IS DISTINCT FROM 'true'::jsonb
  OR p_details->'automatic_approval' IS DISTINCT FROM 'false'::jsonb OR octet_length(p_details::text)>4194304
  OR p_model_version IS NULL OR length(p_model_version) NOT BETWEEN 1 AND 200
  OR p_technical_status IS NULL OR p_technical_status NOT IN ('MATCH','NEEDS_REVIEW') THEN
  RAISE EXCEPTION 'Verified model and technical evidence required' USING ERRCODE='PA001';END IF;
 IF p_legacy_nlp_id IS NULL OR p_legacy_nlp_id<=0 OR p_details ? 'verification_lineage' THEN
  RAISE EXCEPTION 'Server-validated legacy predecessor required' USING ERRCODE='PA001';END IF;
 SELECT n.* INTO v_legacy FROM public.nlp n WHERE n.id=p_legacy_nlp_id FOR SHARE;
 IF NOT FOUND OR v_legacy.po_id IS DISTINCT FROM p_po_id OR v_legacy.pr_id IS DISTINCT FROM p_pr_id
  OR v_legacy.workflow_version IS DISTINCT FROM 1 OR v_legacy.status IS DISTINCT FROM 'For Review'
  OR v_legacy.reviewed_by IS NOT NULL OR v_legacy.reviewed_at IS NOT NULL
  OR v_legacy.review_mapping IS NOT NULL OR v_legacy.staff_decision IS NOT NULL
  OR nullif(btrim(v_legacy.relationship_reason),'') IS NOT NULL
  OR nullif(btrim(v_legacy.evidence_reference),'') IS NOT NULL THEN
  RAISE EXCEPTION 'Legacy evidence is not eligible for replacement' USING ERRCODE='PA002';END IF;
 v_legacy_hash:=encode(sha256(convert_to(to_jsonb(v_legacy)::text,'UTF8')),'hex');
 SELECT l.* INTO v_replacement FROM psms_documents.nlp_legacy_replacements l WHERE l.po_id=p_po_id;
 IF FOUND THEN
  IF v_replacement.legacy_nlp_id IS DISTINCT FROM p_legacy_nlp_id OR v_replacement.pr_id IS DISTINCT FROM p_pr_id
   OR v_replacement.legacy_record_sha256 IS DISTINCT FROM v_legacy_hash THEN
   RAISE EXCEPTION 'Legacy replacement lineage changed' USING ERRCODE='PA002';END IF;
  SELECT id,no,workflow_version,pr_id,po_id,pr_items_hash,po_items_hash,status,details INTO STRICT v_existing
   FROM public.nlp WHERE id=v_replacement.replacement_nlp_id;
  IF v_existing.workflow_version IS DISTINCT FROM 2 OR v_existing.pr_id IS DISTINCT FROM p_pr_id
   OR v_existing.po_id IS DISTINCT FROM p_po_id OR v_existing.status NOT IN ('For Review','Approved')
   OR v_existing.pr_items_hash IS DISTINCT FROM p_pr_hash OR v_existing.po_items_hash IS DISTINCT FROM p_po_hash
   OR v_existing.details::jsonb->'verification_lineage'->>'legacy_nlp_id' IS DISTINCT FROM p_legacy_nlp_id::text
   OR v_existing.details::jsonb->'verification_lineage'->>'legacy_record_sha256' IS DISTINCT FROM v_legacy_hash
   OR EXISTS(SELECT 1 FROM public.nlp n WHERE n.po_id=p_po_id
      AND n.id NOT IN(p_legacy_nlp_id,v_replacement.replacement_nlp_id)) THEN
   RAISE EXCEPTION 'Saved replacement requires human review' USING ERRCODE='PA002';END IF;
  RETURN QUERY SELECT v_existing.id,v_existing.no,false;RETURN;
 END IF;
 IF EXISTS(SELECT 1 FROM public.nlp n WHERE n.po_id=p_po_id AND n.id<>p_legacy_nlp_id)
  OR EXISTS(SELECT 1 FROM psms_documents.pr_po_reviews proof
     WHERE proof.po_id=p_po_id OR proof.pr_id=p_pr_id OR proof.nlp_id=p_legacy_nlp_id) THEN
  RAISE EXCEPTION 'Existing verification or official relationship requires human review' USING ERRCODE='PA002';END IF;
 p_details:=p_details||jsonb_build_object('verification_lineage',jsonb_build_object(
  'version',1,'legacy_nlp_id',v_legacy.id,'legacy_nlp_no',v_legacy.no,'legacy_record_sha256',v_legacy_hash));
 v_stamp:=clock_timestamp() AT TIME ZONE 'Asia/Manila';v_key:='NLP:'||extract(year FROM v_stamp)::integer;
 INSERT INTO public.identifier_sequence AS counter(sequence_key,last_number) VALUES(v_key,1)
  ON CONFLICT(sequence_key) DO UPDATE SET last_number=counter.last_number+1 RETURNING last_number INTO v_number;
 LOOP
  v_no:='NLP-'||extract(year FROM v_stamp)::integer||'-'||lpad(v_number::text,greatest(4,length(v_number::text)),'0');
  EXIT WHEN NOT EXISTS(SELECT 1 FROM public.nlp WHERE no=v_no);
  UPDATE public.identifier_sequence SET last_number=last_number+1 WHERE sequence_key=v_key RETURNING last_number INTO v_number;
 END LOOP;
 INSERT INTO public.nlp(no,po_id,pr_id,result,confidence,staff_decision,remarks,created_at,details,status,
  workflow_version,pr_items_hash,po_items_hash,model_version,technical_status)
 VALUES(v_no,p_po_id,p_pr_id,p_result,p_confidence,NULL,'Human procurement review required',
  to_char(v_stamp,'Mon DD, YYYY HH12:MI AM'),p_details::text,'For Review',2,p_pr_hash,p_po_hash,p_model_version,p_technical_status)
 RETURNING id INTO v_id;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(v_stamp,'Mon DD, YYYY HH12:MI AM'),v_actor.actor_username,'Recorded PR-PO Verification','NLP',v_no,
  'Independent source PR '||p_pr_id||' and PO '||p_po_id||'; human review required');
 INSERT INTO psms_documents.nlp_legacy_replacements(po_id,pr_id,legacy_nlp_id,replacement_nlp_id,legacy_record_sha256,created_by)
 VALUES(p_po_id,p_pr_id,p_legacy_nlp_id,v_id,v_legacy_hash,v_actor.actor_id);
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(v_stamp,'Mon DD, YYYY HH12:MI AM'),v_actor.actor_username,'Recorded Legacy Verification Replacement','NLP',v_no,
  'Preserved legacy NLP '||p_legacy_nlp_id||'; new NLP '||v_id||'; both records retained; no approval granted');
 RETURN QUERY SELECT v_id,v_no,true;
END $function$;

