CREATE OR REPLACE FUNCTION psms_aoq_api.save_reviewed_aoq_independent_v1(p_draft_id uuid, p_expected_revision bigint, p_offer_review_token text, p_winner_index integer, p_supplier_corrections jsonb, p_reviewed_items jsonb, p_manual_winner text, p_remarks text, p_confirm_reviewed boolean)
 RETURNS TABLE(aoq_id bigint, aoq_no text, created boolean, draft_revision bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET extra_float_digits TO '1'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET standard_conforming_strings TO 'on'
AS $function$
DECLARE
 actor jsonb; actor_id bigint; actor_name text; parent_id bigint; pr_status text;
 draft record; source_owner bigint; source_kind text; original jsonb; suppliers jsonb:='[]';
 correction jsonb; supplier jsonb; item jsonb; items jsonb:='[]'; canonical_items jsonb:='[]'; source_items jsonb;
 selected_name text; winner text; normalized_winner text; manual text; notes text;
 target text; has_quotes boolean:=false; matched boolean:=false; expected_signature jsonb;
 reviewed_signature jsonb; quantity double precision; price double precision; amount double precision;
 product double precision; total_decimal numeric:=0; total double precision; other_amount double precision;
 index_number integer; n integer; k text; key text; number bigint; document_no text; official_id bigint;
 save_instant timestamptz; stamp timestamp; display_date text; profile jsonb; encoded_suppliers text; encoded_items text;
BEGIN
 -- READ COMMITTED is part of the call contract: waiting saves see preceding committed children.
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'Unsupported save transaction' USING ERRCODE='PA002';END IF;
 BEGIN
  actor:=nullif(current_setting('psms.workbook_actor',true),'')::jsonb;
  IF jsonb_typeof(actor) IS DISTINCT FROM 'object'
   OR coalesce(actor->>'uid','') !~ '^[1-9][0-9]{0,18}$'
   OR coalesce(actor->>'sid','') !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';END IF;
  actor_id:=(actor->>'uid')::bigint;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';
 END;
 SELECT u.username INTO actor_name FROM public.users u WHERE u.id=actor_id
  AND u.status='Active' AND u.role IN ('Admin','Staff','Inspector') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';END IF;
 PERFORM 1 FROM public.auth_sessions s WHERE s.user_id=actor_id AND s.token_hash=actor->>'sid'
  AND s.revoked_at IS NULL AND s.expires_at>clock_timestamp() FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';END IF;
 IF p_draft_id IS NULL THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='PA004';END IF;
 SELECT d.pr_id INTO parent_id FROM psms_documents.aoq_drafts d
  WHERE d.id=p_draft_id AND d.owner_id=actor_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='PA004';END IF;
 -- Independent-only contract. Linked drafts continue through unchanged v1.
 IF parent_id IS NOT NULL THEN RAISE EXCEPTION 'Independent draft required' USING ERRCODE='PA002';END IF;
 SELECT d.id,d.owner_id,d.source_id,d.pr_id,d.payload,d.revision,d.status,d.official_aoq_id
  INTO draft FROM psms_documents.aoq_drafts d WHERE d.id=p_draft_id AND d.owner_id=actor_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='PA004';END IF;
 IF draft.pr_id IS DISTINCT FROM parent_id OR jsonb_typeof(draft.payload) IS DISTINCT FROM 'object'
  OR (draft.payload ? 'pr_id' AND draft.payload->>'pr_id' IS DISTINCT FROM parent_id::text) THEN
  RAISE EXCEPTION 'Draft parent changed' USING ERRCODE='PA002';END IF;
 SELECT s.owner_id,s.kind INTO source_owner,source_kind FROM psms_documents.sources s WHERE s.id=draft.source_id;
 IF NOT FOUND OR source_owner IS DISTINCT FROM actor_id OR source_kind IS DISTINCT FROM 'aoq' THEN
  RAISE EXCEPTION 'Source unavailable' USING ERRCODE='PA004';END IF;
 IF draft.status='CONFIRMED' THEN
  SELECT a.id,a.no INTO official_id,document_no FROM public.aoq a
   WHERE a.id=draft.official_aoq_id AND a.pr_id IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Confirmed link unavailable' USING ERRCODE='PA002';END IF;
  RETURN QUERY SELECT official_id,document_no,false,draft.revision;RETURN;
 END IF;
 IF draft.status<>'REVIEW' OR p_expected_revision IS NULL OR p_expected_revision<=0
  OR draft.revision<>p_expected_revision THEN RAISE EXCEPTION 'Draft changed' USING ERRCODE='PA002';END IF;
 IF p_confirm_reviewed IS DISTINCT FROM true THEN RAISE EXCEPTION 'Explicit review required' USING ERRCODE='PA001';END IF;

 IF jsonb_typeof(p_supplier_corrections) IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_reviewed_items) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'Invalid review shape' USING ERRCODE='PA001';END IF;
 IF octet_length(p_supplier_corrections::text)>4194304 OR octet_length(p_reviewed_items::text)>4194304
  OR jsonb_array_length(p_supplier_corrections)>100 OR jsonb_array_length(p_reviewed_items) NOT BETWEEN 1 AND 200 THEN
  RAISE EXCEPTION 'Review limit exceeded' USING ERRCODE='PA001';END IF;
 original:=coalesce(draft.payload->'suppliers','[]'::jsonb);
 IF jsonb_typeof(original)<>'array' OR jsonb_array_length(original)>100 THEN
  RAISE EXCEPTION 'Source review unavailable' USING ERRCODE='PA002';END IF;
 FOR supplier IN SELECT value FROM jsonb_array_elements(original) LOOP
  IF jsonb_typeof(supplier)<>'object' THEN RAISE EXCEPTION 'Source review unavailable' USING ERRCODE='PA002';END IF;
  IF supplier ? 'items' AND supplier->'items'<>'null'::jsonb AND jsonb_typeof(supplier->'items')<>'array' THEN
   RAISE EXCEPTION 'Source review unavailable' USING ERRCODE='PA002';END IF;
  has_quotes:=has_quotes OR jsonb_array_length(coalesce(nullif(supplier->'items','null'::jsonb),'[]'))>0;
 END LOOP;
 IF has_quotes AND jsonb_array_length(original)<>jsonb_array_length(p_supplier_corrections) THEN
  RAISE EXCEPTION 'Supplier review changed' USING ERRCODE='PA002';END IF;
 manual:=left(psms_aoq_api.strip_v1(coalesce(p_manual_winner,'')),500);
 notes:=left(psms_aoq_api.strip_v1(coalesce(p_remarks,'')),5000);
 n:=jsonb_array_length(p_supplier_corrections);
 index_number:=coalesce(p_winner_index,-1);
 FOR correction IN SELECT value FROM jsonb_array_elements(p_supplier_corrections) LOOP
  IF jsonb_typeof(correction) IS DISTINCT FROM 'object'
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(correction) AS keys(value) WHERE value NOT IN ('supplier','amount','remarks'))
   OR jsonb_typeof(correction->'supplier') IS DISTINCT FROM 'string'
   OR jsonb_typeof(correction->'remarks') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'Invalid supplier review' USING ERRCODE='PA001';END IF;
  other_amount:=psms_aoq_api.number_v1(correction->'amount');
  IF correction->'amount'<>'""'::jsonb AND (other_amount IS NULL OR other_amount<0) THEN
   RAISE EXCEPTION 'Invalid supplier amount' USING ERRCODE='PA001';END IF;
  k:=jsonb_array_length(suppliers)::text;
  source_items:=coalesce(nullif(original->(k::integer)->'items','null'::jsonb),'[]');
  supplier:=jsonb_build_object('supplier',correction->>'supplier','remarks',correction->>'remarks',
   'amount',CASE WHEN other_amount IS NULL THEN '""'::jsonb ELSE to_jsonb(psms_aoq_api.round2_v1(other_amount)) END,
   'is_winner',false,'items',source_items);
  suppliers:=suppliers||jsonb_build_array(supplier);
 END LOOP;
 IF index_number>=0 AND index_number<n THEN selected_name:=suppliers->index_number->>'supplier';winner:=selected_name;
 ELSIF manual<>'' THEN winner:=manual;
 ELSE RAISE EXCEPTION 'Choose a winner' USING ERRCODE='PA001';END IF;
 normalized_winner:=psms_aoq_api.supplier_key_v1(winner);
 IF coalesce(winner,'')='' OR (SELECT count(*) FROM jsonb_array_elements(suppliers) s
  WHERE psms_aoq_api.supplier_key_v1(s->>'supplier')=normalized_winner)>1 THEN
  RAISE EXCEPTION 'Choose an unambiguous winner' USING ERRCODE='PA001';END IF;
 target:=CASE WHEN index_number>=0 AND index_number<jsonb_array_length(original) THEN index_number::text ELSE 'custom' END;
 IF has_quotes AND (draft.payload->>'offer_supplier_index' IS DISTINCT FROM target
  OR coalesce(draft.payload->>'offer_review_token','')=''
  OR p_offer_review_token IS DISTINCT FROM draft.payload->>'offer_review_token') THEN
  RAISE EXCEPTION 'Supplier review changed' USING ERRCODE='PA002';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_reviewed_items) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(item) AS keys(value)
   WHERE value NOT IN ('item','description','qty','unit','unit_cost','amount','remarks','category')) THEN
   RAISE EXCEPTION 'Invalid reviewed item' USING ERRCODE='PA001';END IF;
  FOREACH k IN ARRAY ARRAY['item','description','unit'] LOOP
   IF jsonb_typeof(item->k) IS DISTINCT FROM 'string' OR psms_aoq_api.space_v1(item->>k)='' THEN
    RAISE EXCEPTION 'Incomplete reviewed item' USING ERRCODE='PA001';END IF;
  END LOOP;
  IF item ? 'category' AND (jsonb_typeof(item->'category')<>'string' OR item->>'category' NOT IN ('','DBM','NON-DBM','LIB')) THEN
   RAISE EXCEPTION 'Invalid reviewed category' USING ERRCODE='PA001';END IF;
  IF item ? 'remarks' AND jsonb_typeof(item->'remarks')<>'string' THEN
   RAISE EXCEPTION 'Invalid reviewed remarks' USING ERRCODE='PA001';END IF;
  quantity:=psms_aoq_api.number_v1(item->'qty');price:=psms_aoq_api.number_v1(item->'unit_cost');amount:=psms_aoq_api.number_v1(item->'amount');
  IF quantity IS NULL OR price IS NULL OR amount IS NULL OR quantity<0 OR price<0 OR amount<0 THEN
   RAISE EXCEPTION 'Invalid reviewed number' USING ERRCODE='PA001';END IF;
  IF price<>psms_aoq_api.round2_v1(price) OR amount<>psms_aoq_api.round2_v1(amount) THEN
   RAISE EXCEPTION 'Canonical reviewed values required' USING ERRCODE='PA001';END IF;
  BEGIN product:=quantity*price;
  EXCEPTION WHEN numeric_value_out_of_range THEN
   -- Python permits multiplication underflow to zero; PostgreSQL float8 raises.
   IF quantity<1 AND price<1 THEN product:=0;
   ELSE RAISE EXCEPTION 'Invalid reviewed product' USING ERRCODE='PA001';END IF;
  END;
  IF psms_aoq_api.round2_v1(product)<>psms_aoq_api.round2_v1(amount) THEN
   RAISE EXCEPTION 'Reviewed line amount mismatch' USING ERRCODE='PA001';END IF;
  total_decimal:=total_decimal+psms_aoq_api.shortest_decimal_v1(amount);
  canonical_items:=canonical_items||jsonb_build_array(item||jsonb_build_object('qty',quantity,'unit_cost',price,'amount',amount));
 END LOOP;
 BEGIN total:=psms_aoq_api.round2_v1(total_decimal::double precision);
 EXCEPTION WHEN numeric_value_out_of_range THEN RAISE EXCEPTION 'Invalid reviewed total' USING ERRCODE='PA001';END;
 IF total<=0 THEN RAISE EXCEPTION 'Reviewed total must be positive' USING ERRCODE='PA001';END IF;
 IF has_quotes THEN
  reviewed_signature:=psms_aoq_api.signature_v1(p_reviewed_items);
  expected_signature:=psms_aoq_api.signature_v1(coalesce(original->(index_number)->'items','[]'));
  IF target='custom' THEN expected_signature:='[]';END IF;
  IF reviewed_signature IS DISTINCT FROM expected_signature THEN
   FOR supplier,index_number IN SELECT value,(ordinality-1)::integer FROM jsonb_array_elements(original) WITH ORDINALITY LOOP
    IF index_number::text<>target AND jsonb_array_length(coalesce(nullif(supplier->'items','null'::jsonb),'[]'))>0
     AND reviewed_signature=psms_aoq_api.signature_v1(supplier->'items') THEN
     RAISE EXCEPTION 'Offer belongs to another supplier' USING ERRCODE='PA001';END IF;
   END LOOP;
  END IF;
 END IF;
 index_number:=coalesce(p_winner_index,-1);
 -- Owner-approved Philippine official date/year policy; one captured instant feeds both.
 save_instant:=clock_timestamp();
 stamp:=save_instant AT TIME ZONE 'Asia/Manila';
 display_date:=to_char(stamp,'Mon DD, YYYY HH12:MI AM');
 key:='AOQ:'||extract(year FROM stamp)::integer::text;
 INSERT INTO public.identifier_sequence AS counter(sequence_key,last_number) VALUES(key,1)
  ON CONFLICT(sequence_key) DO UPDATE SET last_number=counter.last_number+1 RETURNING last_number INTO number;
 LOOP
  document_no:='AOQ-'||extract(year FROM stamp)::integer::text||'-'||lpad(number::text,greatest(4,length(number::text)),'0');
  EXIT WHEN NOT EXISTS(SELECT 1 FROM public.aoq a WHERE a.no=document_no);
  UPDATE public.identifier_sequence SET last_number=last_number+1 WHERE sequence_key=key RETURNING last_number INTO number;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(canonical_items) LOOP
  item:=item||jsonb_build_object('_AOQ Item ID',document_no||'-ITEM-'||lpad((jsonb_array_length(items)+1)::text,2,'0'));
  -- Python width is a minimum, not a truncation limit (items 100 through 200).
  IF jsonb_array_length(items)>=99 THEN item:=item||jsonb_build_object('_AOQ Item ID',document_no||'-ITEM-'||(jsonb_array_length(items)+1)::text);END IF;
  items:=items||jsonb_build_array(item);
 END LOOP;
 original:=suppliers;suppliers:='[]';
 FOR supplier,n IN SELECT value,(ordinality-1)::integer FROM jsonb_array_elements(original) WITH ORDINALITY LOOP
  IF n=index_number OR psms_aoq_api.supplier_key_v1(supplier->>'supplier')=normalized_winner THEN
   supplier:=supplier||jsonb_build_object('is_winner',true,'items',items,'amount',total);matched:=true;END IF;
  suppliers:=suppliers||jsonb_build_array(supplier);
 END LOOP;
 IF NOT matched THEN suppliers:=suppliers||jsonb_build_array(jsonb_build_object('supplier',winner,'amount',total,'remarks',notes,'is_winner',true,'items',items));END IF;
 encoded_suppliers:=suppliers::text;encoded_items:=items::text;
 IF octet_length(encoded_suppliers)>4194304 OR octet_length(encoded_items)>4194304 THEN
  RAISE EXCEPTION 'Review limit exceeded' USING ERRCODE='PA001';END IF;
 profile:=jsonb_build_object('document_type',draft.payload->'document_type','extraction_method',draft.payload->'extraction_method',
  'confidence',draft.payload->'confidence','table_count',draft.payload->'table_count',
  'parsed_table_sources',draft.payload->'parsed_table_sources','detected_tables',draft.payload->'detected_tables');
 INSERT INTO public.aoq(no,pr_id,status,created_at,suppliers,winner,winning_amount,winning_offer,ocr_filename,ocr_text,
  stored_filename,source_type,extraction_method,extraction_profile,extraction_warnings)
 VALUES(document_no,parent_id,'For Review',display_date,encoded_suppliers,winner,total,encoded_items,
  coalesce(draft.payload->>'ocr_filename',''),coalesce(draft.payload->>'raw_text',''),'',
  coalesce(draft.payload->>'document_type',''),coalesce(draft.payload->>'extraction_method',''),profile::text,
  coalesce(nullif(draft.payload->'warnings','null'::jsonb),'[]')::text) RETURNING id INTO official_id;
 UPDATE psms_documents.aoq_drafts SET status='CONFIRMED',official_aoq_id=official_id,
  revision=revision+1,updated_at=save_instant WHERE id=p_draft_id AND owner_id=actor_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='PA002';END IF;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(display_date,actor_name,'Created AOQ from Confirmed OCR','AOQ',document_no,'Private document review operation');
 RETURN QUERY SELECT official_id,document_no,true,draft.revision+1;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.save_reviewed_aoq_v1(p_draft_id uuid, p_expected_revision bigint, p_offer_review_token text, p_winner_index integer, p_supplier_corrections jsonb, p_reviewed_items jsonb, p_manual_winner text, p_remarks text, p_confirm_reviewed boolean)
 RETURNS TABLE(aoq_id bigint, aoq_no text, created boolean, draft_revision bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET extra_float_digits TO '1'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET standard_conforming_strings TO 'on'
AS $function$
DECLARE
 actor jsonb; actor_id bigint; actor_name text; parent_id bigint; pr_status text;
 draft record; source_owner bigint; source_kind text; original jsonb; suppliers jsonb:='[]';
 correction jsonb; supplier jsonb; item jsonb; items jsonb:='[]'; canonical_items jsonb:='[]'; source_items jsonb;
 selected_name text; winner text; normalized_winner text; manual text; notes text;
 target text; has_quotes boolean:=false; matched boolean:=false; expected_signature jsonb;
 reviewed_signature jsonb; quantity double precision; price double precision; amount double precision;
 product double precision; total_decimal numeric:=0; total double precision; other_amount double precision;
 index_number integer; n integer; k text; key text; number bigint; document_no text; official_id bigint;
 save_instant timestamptz; stamp timestamp; display_date text; profile jsonb; encoded_suppliers text; encoded_items text;
BEGIN
 -- READ COMMITTED is part of the call contract: waiting saves see preceding committed children.
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'Unsupported save transaction' USING ERRCODE='PA002';END IF;
 BEGIN
  actor:=nullif(current_setting('psms.workbook_actor',true),'')::jsonb;
  IF jsonb_typeof(actor) IS DISTINCT FROM 'object'
   OR coalesce(actor->>'uid','') !~ '^[1-9][0-9]{0,18}$'
   OR coalesce(actor->>'sid','') !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';END IF;
  actor_id:=(actor->>'uid')::bigint;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';
 END;
 SELECT u.username INTO actor_name FROM public.users u WHERE u.id=actor_id
  AND u.status='Active' AND u.role IN ('Admin','Staff','Inspector') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';END IF;
 PERFORM 1 FROM public.auth_sessions s WHERE s.user_id=actor_id AND s.token_hash=actor->>'sid'
  AND s.revoked_at IS NULL AND s.expires_at>clock_timestamp() FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';END IF;
 IF p_draft_id IS NULL THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='PA004';END IF;
 SELECT d.pr_id INTO parent_id FROM psms_documents.aoq_drafts d
  WHERE d.id=p_draft_id AND d.owner_id=actor_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='PA004';END IF;
 -- Lock order matches existing creation: actor, session, typed PR, draft, counter.
 SELECT p.status INTO pr_status FROM public.pr p WHERE p.id=parent_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Parent unavailable' USING ERRCODE='PA002';END IF;
 SELECT d.id,d.owner_id,d.source_id,d.pr_id,d.payload,d.revision,d.status,d.official_aoq_id
  INTO draft FROM psms_documents.aoq_drafts d WHERE d.id=p_draft_id AND d.owner_id=actor_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='PA004';END IF;
 IF draft.pr_id IS DISTINCT FROM parent_id OR jsonb_typeof(draft.payload) IS DISTINCT FROM 'object'
  OR (draft.payload ? 'pr_id' AND draft.payload->>'pr_id' IS DISTINCT FROM parent_id::text) THEN
  RAISE EXCEPTION 'Draft parent changed' USING ERRCODE='PA002';END IF;
 SELECT s.owner_id,s.kind INTO source_owner,source_kind FROM psms_documents.sources s WHERE s.id=draft.source_id;
 IF NOT FOUND OR source_owner IS DISTINCT FROM actor_id OR source_kind IS DISTINCT FROM 'aoq' THEN
  RAISE EXCEPTION 'Source unavailable' USING ERRCODE='PA004';END IF;
 IF draft.status='CONFIRMED' THEN
  SELECT a.id,a.no INTO official_id,document_no FROM public.aoq a
   WHERE a.id=draft.official_aoq_id AND a.pr_id=parent_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Confirmed link unavailable' USING ERRCODE='PA002';END IF;
  RETURN QUERY SELECT official_id,document_no,false,draft.revision;RETURN;
 END IF;
 IF draft.status<>'REVIEW' OR p_expected_revision IS NULL OR p_expected_revision<=0
  OR draft.revision<>p_expected_revision THEN RAISE EXCEPTION 'Draft changed' USING ERRCODE='PA002';END IF;
 IF p_confirm_reviewed IS DISTINCT FROM true THEN RAISE EXCEPTION 'Explicit review required' USING ERRCODE='PA001';END IF;
 IF pr_status IS DISTINCT FROM 'Approved' OR EXISTS(SELECT 1 FROM public.aoq a WHERE a.pr_id=parent_id) THEN
  RAISE EXCEPTION 'Parent unavailable' USING ERRCODE='PA002';END IF;
 IF jsonb_typeof(p_supplier_corrections) IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_reviewed_items) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'Invalid review shape' USING ERRCODE='PA001';END IF;
 IF octet_length(p_supplier_corrections::text)>4194304 OR octet_length(p_reviewed_items::text)>4194304
  OR jsonb_array_length(p_supplier_corrections)>100 OR jsonb_array_length(p_reviewed_items) NOT BETWEEN 1 AND 200 THEN
  RAISE EXCEPTION 'Review limit exceeded' USING ERRCODE='PA001';END IF;
 original:=coalesce(draft.payload->'suppliers','[]'::jsonb);
 IF jsonb_typeof(original)<>'array' OR jsonb_array_length(original)>100 THEN
  RAISE EXCEPTION 'Source review unavailable' USING ERRCODE='PA002';END IF;
 FOR supplier IN SELECT value FROM jsonb_array_elements(original) LOOP
  IF jsonb_typeof(supplier)<>'object' THEN RAISE EXCEPTION 'Source review unavailable' USING ERRCODE='PA002';END IF;
  IF supplier ? 'items' AND supplier->'items'<>'null'::jsonb AND jsonb_typeof(supplier->'items')<>'array' THEN
   RAISE EXCEPTION 'Source review unavailable' USING ERRCODE='PA002';END IF;
  has_quotes:=has_quotes OR jsonb_array_length(coalesce(nullif(supplier->'items','null'::jsonb),'[]'))>0;
 END LOOP;
 IF has_quotes AND jsonb_array_length(original)<>jsonb_array_length(p_supplier_corrections) THEN
  RAISE EXCEPTION 'Supplier review changed' USING ERRCODE='PA002';END IF;
 manual:=left(psms_aoq_api.strip_v1(coalesce(p_manual_winner,'')),500);
 notes:=left(psms_aoq_api.strip_v1(coalesce(p_remarks,'')),5000);
 n:=jsonb_array_length(p_supplier_corrections);
 index_number:=coalesce(p_winner_index,-1);
 FOR correction IN SELECT value FROM jsonb_array_elements(p_supplier_corrections) LOOP
  IF jsonb_typeof(correction) IS DISTINCT FROM 'object'
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(correction) AS keys(value) WHERE value NOT IN ('supplier','amount','remarks'))
   OR jsonb_typeof(correction->'supplier') IS DISTINCT FROM 'string'
   OR jsonb_typeof(correction->'remarks') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'Invalid supplier review' USING ERRCODE='PA001';END IF;
  other_amount:=psms_aoq_api.number_v1(correction->'amount');
  IF correction->'amount'<>'""'::jsonb AND (other_amount IS NULL OR other_amount<0) THEN
   RAISE EXCEPTION 'Invalid supplier amount' USING ERRCODE='PA001';END IF;
  k:=jsonb_array_length(suppliers)::text;
  source_items:=coalesce(nullif(original->(k::integer)->'items','null'::jsonb),'[]');
  supplier:=jsonb_build_object('supplier',correction->>'supplier','remarks',correction->>'remarks',
   'amount',CASE WHEN other_amount IS NULL THEN '""'::jsonb ELSE to_jsonb(psms_aoq_api.round2_v1(other_amount)) END,
   'is_winner',false,'items',source_items);
  suppliers:=suppliers||jsonb_build_array(supplier);
 END LOOP;
 IF index_number>=0 AND index_number<n THEN selected_name:=suppliers->index_number->>'supplier';winner:=selected_name;
 ELSIF manual<>'' THEN winner:=manual;
 ELSE RAISE EXCEPTION 'Choose a winner' USING ERRCODE='PA001';END IF;
 normalized_winner:=psms_aoq_api.supplier_key_v1(winner);
 IF coalesce(winner,'')='' OR (SELECT count(*) FROM jsonb_array_elements(suppliers) s
  WHERE psms_aoq_api.supplier_key_v1(s->>'supplier')=normalized_winner)>1 THEN
  RAISE EXCEPTION 'Choose an unambiguous winner' USING ERRCODE='PA001';END IF;
 target:=CASE WHEN index_number>=0 AND index_number<jsonb_array_length(original) THEN index_number::text ELSE 'custom' END;
 IF has_quotes AND (draft.payload->>'offer_supplier_index' IS DISTINCT FROM target
  OR coalesce(draft.payload->>'offer_review_token','')=''
  OR p_offer_review_token IS DISTINCT FROM draft.payload->>'offer_review_token') THEN
  RAISE EXCEPTION 'Supplier review changed' USING ERRCODE='PA002';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_reviewed_items) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(item) AS keys(value)
   WHERE value NOT IN ('item','description','qty','unit','unit_cost','amount','remarks','category')) THEN
   RAISE EXCEPTION 'Invalid reviewed item' USING ERRCODE='PA001';END IF;
  FOREACH k IN ARRAY ARRAY['item','description','unit'] LOOP
   IF jsonb_typeof(item->k) IS DISTINCT FROM 'string' OR psms_aoq_api.space_v1(item->>k)='' THEN
    RAISE EXCEPTION 'Incomplete reviewed item' USING ERRCODE='PA001';END IF;
  END LOOP;
  IF item ? 'category' AND (jsonb_typeof(item->'category')<>'string' OR item->>'category' NOT IN ('','DBM','NON-DBM','LIB')) THEN
   RAISE EXCEPTION 'Invalid reviewed category' USING ERRCODE='PA001';END IF;
  IF item ? 'remarks' AND jsonb_typeof(item->'remarks')<>'string' THEN
   RAISE EXCEPTION 'Invalid reviewed remarks' USING ERRCODE='PA001';END IF;
  quantity:=psms_aoq_api.number_v1(item->'qty');price:=psms_aoq_api.number_v1(item->'unit_cost');amount:=psms_aoq_api.number_v1(item->'amount');
  IF quantity IS NULL OR price IS NULL OR amount IS NULL OR quantity<0 OR price<0 OR amount<0 THEN
   RAISE EXCEPTION 'Invalid reviewed number' USING ERRCODE='PA001';END IF;
  IF price<>psms_aoq_api.round2_v1(price) OR amount<>psms_aoq_api.round2_v1(amount) THEN
   RAISE EXCEPTION 'Canonical reviewed values required' USING ERRCODE='PA001';END IF;
  BEGIN product:=quantity*price;
  EXCEPTION WHEN numeric_value_out_of_range THEN
   -- Python permits multiplication underflow to zero; PostgreSQL float8 raises.
   IF quantity<1 AND price<1 THEN product:=0;
   ELSE RAISE EXCEPTION 'Invalid reviewed product' USING ERRCODE='PA001';END IF;
  END;
  IF psms_aoq_api.round2_v1(product)<>psms_aoq_api.round2_v1(amount) THEN
   RAISE EXCEPTION 'Reviewed line amount mismatch' USING ERRCODE='PA001';END IF;
  total_decimal:=total_decimal+psms_aoq_api.shortest_decimal_v1(amount);
  canonical_items:=canonical_items||jsonb_build_array(item||jsonb_build_object('qty',quantity,'unit_cost',price,'amount',amount));
 END LOOP;
 BEGIN total:=psms_aoq_api.round2_v1(total_decimal::double precision);
 EXCEPTION WHEN numeric_value_out_of_range THEN RAISE EXCEPTION 'Invalid reviewed total' USING ERRCODE='PA001';END;
 IF total<=0 THEN RAISE EXCEPTION 'Reviewed total must be positive' USING ERRCODE='PA001';END IF;
 IF has_quotes THEN
  reviewed_signature:=psms_aoq_api.signature_v1(p_reviewed_items);
  expected_signature:=psms_aoq_api.signature_v1(coalesce(original->(index_number)->'items','[]'));
  IF target='custom' THEN expected_signature:='[]';END IF;
  IF reviewed_signature IS DISTINCT FROM expected_signature THEN
   FOR supplier,index_number IN SELECT value,(ordinality-1)::integer FROM jsonb_array_elements(original) WITH ORDINALITY LOOP
    IF index_number::text<>target AND jsonb_array_length(coalesce(nullif(supplier->'items','null'::jsonb),'[]'))>0
     AND reviewed_signature=psms_aoq_api.signature_v1(supplier->'items') THEN
     RAISE EXCEPTION 'Offer belongs to another supplier' USING ERRCODE='PA001';END IF;
   END LOOP;
  END IF;
 END IF;
 index_number:=coalesce(p_winner_index,-1);
 -- Owner-approved Philippine official date/year policy; one captured instant feeds both.
 save_instant:=clock_timestamp();
 stamp:=save_instant AT TIME ZONE 'Asia/Manila';
 display_date:=to_char(stamp,'Mon DD, YYYY HH12:MI AM');
 key:='AOQ:'||extract(year FROM stamp)::integer::text;
 INSERT INTO public.identifier_sequence AS counter(sequence_key,last_number) VALUES(key,1)
  ON CONFLICT(sequence_key) DO UPDATE SET last_number=counter.last_number+1 RETURNING last_number INTO number;
 LOOP
  document_no:='AOQ-'||extract(year FROM stamp)::integer::text||'-'||lpad(number::text,greatest(4,length(number::text)),'0');
  EXIT WHEN NOT EXISTS(SELECT 1 FROM public.aoq a WHERE a.no=document_no);
  UPDATE public.identifier_sequence SET last_number=last_number+1 WHERE sequence_key=key RETURNING last_number INTO number;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(canonical_items) LOOP
  item:=item||jsonb_build_object('_AOQ Item ID',document_no||'-ITEM-'||lpad((jsonb_array_length(items)+1)::text,2,'0'));
  -- Python width is a minimum, not a truncation limit (items 100 through 200).
  IF jsonb_array_length(items)>=99 THEN item:=item||jsonb_build_object('_AOQ Item ID',document_no||'-ITEM-'||(jsonb_array_length(items)+1)::text);END IF;
  items:=items||jsonb_build_array(item);
 END LOOP;
 original:=suppliers;suppliers:='[]';
 FOR supplier,n IN SELECT value,(ordinality-1)::integer FROM jsonb_array_elements(original) WITH ORDINALITY LOOP
  IF n=index_number OR psms_aoq_api.supplier_key_v1(supplier->>'supplier')=normalized_winner THEN
   supplier:=supplier||jsonb_build_object('is_winner',true,'items',items,'amount',total);matched:=true;END IF;
  suppliers:=suppliers||jsonb_build_array(supplier);
 END LOOP;
 IF NOT matched THEN suppliers:=suppliers||jsonb_build_array(jsonb_build_object('supplier',winner,'amount',total,'remarks',notes,'is_winner',true,'items',items));END IF;
 encoded_suppliers:=suppliers::text;encoded_items:=items::text;
 IF octet_length(encoded_suppliers)>4194304 OR octet_length(encoded_items)>4194304 THEN
  RAISE EXCEPTION 'Review limit exceeded' USING ERRCODE='PA001';END IF;
 profile:=jsonb_build_object('document_type',draft.payload->'document_type','extraction_method',draft.payload->'extraction_method',
  'confidence',draft.payload->'confidence','table_count',draft.payload->'table_count',
  'parsed_table_sources',draft.payload->'parsed_table_sources','detected_tables',draft.payload->'detected_tables');
 INSERT INTO public.aoq(no,pr_id,status,created_at,suppliers,winner,winning_amount,winning_offer,ocr_filename,ocr_text,
  stored_filename,source_type,extraction_method,extraction_profile,extraction_warnings)
 VALUES(document_no,parent_id,'For Review',display_date,encoded_suppliers,winner,total,encoded_items,
  coalesce(draft.payload->>'ocr_filename',''),coalesce(draft.payload->>'raw_text',''),'',
  coalesce(draft.payload->>'document_type',''),coalesce(draft.payload->>'extraction_method',''),profile::text,
  coalesce(nullif(draft.payload->'warnings','null'::jsonb),'[]')::text) RETURNING id INTO official_id;
 UPDATE psms_documents.aoq_drafts SET status='CONFIRMED',official_aoq_id=official_id,
  revision=revision+1,updated_at=save_instant WHERE id=p_draft_id AND owner_id=actor_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='PA002';END IF;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(display_date,actor_name,'Created AOQ from Confirmed OCR','AOQ',document_no,'Private document review operation');
 RETURN QUERY SELECT official_id,document_no,true,draft.revision+1;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.save_selected_aoq_independent_v2(p_draft_id uuid, p_expected_revision bigint, p_offer_review_token text, p_winner_index integer, p_supplier_corrections jsonb, p_reviewed_items jsonb, p_manual_winner text, p_remarks text, p_confirm_reviewed boolean, p_selected_indices jsonb)
 RETURNS TABLE(aoq_id bigint, aoq_no text, created boolean, draft_revision bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET extra_float_digits TO '1'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET standard_conforming_strings TO 'on'
AS $function$
DECLARE
 actor jsonb; actor_id bigint; actor_name text; parent_id bigint; pr_status text;
 draft record; source_owner bigint; source_kind text; original jsonb; suppliers jsonb:='[]';
 correction jsonb; supplier jsonb; item jsonb; items jsonb:='[]'; canonical_items jsonb:='[]'; source_items jsonb;
 selected_name text; winner text; normalized_winner text; manual text; notes text;
 target text; has_quotes boolean:=false; matched boolean:=false; expected_signature jsonb;
 reviewed_signature jsonb; quantity double precision; price double precision; amount double precision;
 product double precision; total_decimal numeric:=0; total double precision; other_amount double precision;
 index_number integer; n integer; k text; key text; number bigint; document_no text; official_id bigint;
 save_instant timestamptz; stamp timestamp; display_date text; profile jsonb; encoded_suppliers text; encoded_items text;
BEGIN
 -- READ COMMITTED is part of the call contract: waiting saves see preceding committed children.
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'Unsupported save transaction' USING ERRCODE='PA002';END IF;
 BEGIN
  actor:=nullif(current_setting('psms.workbook_actor',true),'')::jsonb;
  IF jsonb_typeof(actor) IS DISTINCT FROM 'object'
   OR coalesce(actor->>'uid','') !~ '^[1-9][0-9]{0,18}$'
   OR coalesce(actor->>'sid','') !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';END IF;
  actor_id:=(actor->>'uid')::bigint;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';
 END;
 SELECT u.username INTO actor_name FROM public.users u WHERE u.id=actor_id
  AND u.status='Active' AND u.role IN ('Admin','Staff','Inspector') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';END IF;
 PERFORM 1 FROM public.auth_sessions s WHERE s.user_id=actor_id AND s.token_hash=actor->>'sid'
  AND s.revoked_at IS NULL AND s.expires_at>clock_timestamp() FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active actor required' USING ERRCODE='PA003';END IF;
 IF p_draft_id IS NULL THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='PA004';END IF;
 SELECT d.pr_id INTO parent_id FROM psms_documents.aoq_drafts d
  WHERE d.id=p_draft_id AND d.owner_id=actor_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='PA004';END IF;
 -- Independent-only contract. Linked drafts continue through unchanged v1.
 IF parent_id IS NOT NULL THEN RAISE EXCEPTION 'Independent draft required' USING ERRCODE='PA002';END IF;
 SELECT d.id,d.owner_id,d.source_id,d.pr_id,d.payload,d.revision,d.status,d.official_aoq_id
  INTO draft FROM psms_documents.aoq_drafts d WHERE d.id=p_draft_id AND d.owner_id=actor_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='PA004';END IF;
 IF draft.pr_id IS DISTINCT FROM parent_id OR jsonb_typeof(draft.payload) IS DISTINCT FROM 'object'
  OR (draft.payload ? 'pr_id' AND draft.payload->>'pr_id' IS DISTINCT FROM parent_id::text) THEN
  RAISE EXCEPTION 'Draft parent changed' USING ERRCODE='PA002';END IF;
 SELECT s.owner_id,s.kind INTO source_owner,source_kind FROM psms_documents.sources s WHERE s.id=draft.source_id;
 IF NOT FOUND OR source_owner IS DISTINCT FROM actor_id OR source_kind IS DISTINCT FROM 'aoq' THEN
  RAISE EXCEPTION 'Source unavailable' USING ERRCODE='PA004';END IF;
 IF draft.status='CONFIRMED' THEN
  SELECT a.id,a.no INTO official_id,document_no FROM public.aoq a
   WHERE a.id=draft.official_aoq_id AND a.pr_id IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Confirmed link unavailable' USING ERRCODE='PA002';END IF;
  RETURN QUERY SELECT official_id,document_no,false,draft.revision;RETURN;
 END IF;
 IF draft.status<>'REVIEW' OR p_expected_revision IS NULL OR p_expected_revision<=0
  OR draft.revision<>p_expected_revision THEN RAISE EXCEPTION 'Draft changed' USING ERRCODE='PA002';END IF;
 IF p_confirm_reviewed IS DISTINCT FROM true THEN RAISE EXCEPTION 'Explicit review required' USING ERRCODE='PA001';END IF;

 IF jsonb_typeof(p_supplier_corrections) IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_reviewed_items) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'Invalid review shape' USING ERRCODE='PA001';END IF;
 IF octet_length(p_supplier_corrections::text)>4194304 OR octet_length(p_reviewed_items::text)>4194304
  OR jsonb_array_length(p_supplier_corrections)>100 OR jsonb_array_length(p_reviewed_items) NOT BETWEEN 1 AND 200 THEN
  RAISE EXCEPTION 'Review limit exceeded' USING ERRCODE='PA001';END IF;
 original:=coalesce(draft.payload->'suppliers','[]'::jsonb);
 IF jsonb_typeof(original)<>'array' OR jsonb_array_length(original)>100 THEN
  RAISE EXCEPTION 'Source review unavailable' USING ERRCODE='PA002';END IF;
 FOR supplier IN SELECT value FROM jsonb_array_elements(original) LOOP
  IF jsonb_typeof(supplier)<>'object' THEN RAISE EXCEPTION 'Source review unavailable' USING ERRCODE='PA002';END IF;
  IF supplier ? 'items' AND supplier->'items'<>'null'::jsonb AND jsonb_typeof(supplier->'items')<>'array' THEN
   RAISE EXCEPTION 'Source review unavailable' USING ERRCODE='PA002';END IF;
  has_quotes:=has_quotes OR jsonb_array_length(coalesce(nullif(supplier->'items','null'::jsonb),'[]'))>0;
 END LOOP;
 IF has_quotes AND jsonb_array_length(original)<>jsonb_array_length(p_supplier_corrections) THEN
  RAISE EXCEPTION 'Supplier review changed' USING ERRCODE='PA002';END IF;
 manual:=left(psms_aoq_api.strip_v1(coalesce(p_manual_winner,'')),500);
 notes:=left(psms_aoq_api.strip_v1(coalesce(p_remarks,'')),5000);
 n:=jsonb_array_length(p_supplier_corrections);
 index_number:=coalesce(p_winner_index,-1);
 FOR correction IN SELECT value FROM jsonb_array_elements(p_supplier_corrections) LOOP
  IF jsonb_typeof(correction) IS DISTINCT FROM 'object'
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(correction) AS keys(value) WHERE value NOT IN ('supplier','amount','remarks'))
   OR jsonb_typeof(correction->'supplier') IS DISTINCT FROM 'string'
   OR jsonb_typeof(correction->'remarks') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'Invalid supplier review' USING ERRCODE='PA001';END IF;
  other_amount:=psms_aoq_api.number_v1(correction->'amount');
  IF correction->'amount'<>'""'::jsonb AND (other_amount IS NULL OR other_amount<0) THEN
   RAISE EXCEPTION 'Invalid supplier amount' USING ERRCODE='PA001';END IF;
  k:=jsonb_array_length(suppliers)::text;
  source_items:=coalesce(nullif(original->(k::integer)->'items','null'::jsonb),'[]');
  supplier:=jsonb_build_object('supplier',correction->>'supplier','remarks',correction->>'remarks',
   'amount',CASE WHEN other_amount IS NULL THEN '""'::jsonb ELSE to_jsonb(psms_aoq_api.round2_v1(other_amount)) END,
   'is_winner',false,'items',source_items);
  suppliers:=suppliers||jsonb_build_array(supplier);
 END LOOP;
 IF index_number>=0 AND index_number<n THEN selected_name:=suppliers->index_number->>'supplier';winner:=selected_name;
 ELSIF manual<>'' THEN winner:=manual;
 ELSE RAISE EXCEPTION 'Choose a winner' USING ERRCODE='PA001';END IF;
 normalized_winner:=psms_aoq_api.supplier_key_v1(winner);
 IF coalesce(winner,'')='' OR (SELECT count(*) FROM jsonb_array_elements(suppliers) s
  WHERE psms_aoq_api.supplier_key_v1(s->>'supplier')=normalized_winner)>1 THEN
  RAISE EXCEPTION 'Choose an unambiguous winner' USING ERRCODE='PA001';END IF;
 target:=CASE WHEN index_number>=0 AND index_number<jsonb_array_length(original) THEN index_number::text ELSE 'custom' END;
 IF has_quotes AND (draft.payload->>'offer_supplier_index' IS DISTINCT FROM target
  OR coalesce(draft.payload->>'offer_review_token','')=''
  OR p_offer_review_token IS DISTINCT FROM draft.payload->>'offer_review_token') THEN
  RAISE EXCEPTION 'Supplier review changed' USING ERRCODE='PA002';END IF;

 -- All supplied rows remain bound to original source ordinals. Apply the
 -- unchanged item-validation loop to selected rows; originals remain untouched.
 IF NOT has_quotes OR target='custom' OR index_number<0 OR index_number>=jsonb_array_length(original)
  OR jsonb_typeof(p_selected_indices) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'Source-backed item selection required' USING ERRCODE='PA001';END IF;
 IF jsonb_array_length(p_reviewed_items)<>jsonb_array_length(original->index_number->'items')
  OR jsonb_array_length(p_selected_indices) NOT BETWEEN 1 AND jsonb_array_length(p_reviewed_items)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_selected_indices) s(value)
    WHERE CASE WHEN jsonb_typeof(s.value)<>'number' OR s.value::text !~ '^(0|[1-9][0-9]*)$'
      THEN true ELSE (s.value::text)::numeric>=jsonb_array_length(p_reviewed_items) END)
  OR (SELECT count(DISTINCT s.value) FROM jsonb_array_elements(p_selected_indices) s(value))<>jsonb_array_length(p_selected_indices) THEN
  RAISE EXCEPTION 'Unique original source item indices required' USING ERRCODE='PA001';END IF;
 SELECT jsonb_agg(s.value ORDER BY (s.value::text)::numeric) INTO p_selected_indices
 FROM jsonb_array_elements(p_selected_indices) s(value);
 FOR item IN SELECT entry.value FROM jsonb_array_elements(p_reviewed_items) WITH ORDINALITY entry(value,position)
  WHERE p_selected_indices @> jsonb_build_array(entry.position-1) ORDER BY entry.position LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(item) AS keys(value)
   WHERE value NOT IN ('item','description','qty','unit','unit_cost','amount','remarks','category')) THEN
   RAISE EXCEPTION 'Invalid reviewed item' USING ERRCODE='PA001';END IF;
  FOREACH k IN ARRAY ARRAY['item','description','unit'] LOOP
   IF jsonb_typeof(item->k) IS DISTINCT FROM 'string' OR psms_aoq_api.space_v1(item->>k)='' THEN
    RAISE EXCEPTION 'Incomplete reviewed item' USING ERRCODE='PA001';END IF;
  END LOOP;
  IF item ? 'category' AND (jsonb_typeof(item->'category')<>'string' OR item->>'category' NOT IN ('','DBM','NON-DBM','LIB')) THEN
   RAISE EXCEPTION 'Invalid reviewed category' USING ERRCODE='PA001';END IF;
  IF item ? 'remarks' AND jsonb_typeof(item->'remarks')<>'string' THEN
   RAISE EXCEPTION 'Invalid reviewed remarks' USING ERRCODE='PA001';END IF;
  quantity:=psms_aoq_api.number_v1(item->'qty');price:=psms_aoq_api.number_v1(item->'unit_cost');amount:=psms_aoq_api.number_v1(item->'amount');
  IF quantity IS NULL OR price IS NULL OR amount IS NULL OR quantity<0 OR price<0 OR amount<0 THEN
   RAISE EXCEPTION 'Invalid reviewed number' USING ERRCODE='PA001';END IF;
  IF price<>psms_aoq_api.round2_v1(price) OR amount<>psms_aoq_api.round2_v1(amount) THEN
   RAISE EXCEPTION 'Canonical reviewed values required' USING ERRCODE='PA001';END IF;
  BEGIN product:=quantity*price;
  EXCEPTION WHEN numeric_value_out_of_range THEN
   -- Python permits multiplication underflow to zero; PostgreSQL float8 raises.
   IF quantity<1 AND price<1 THEN product:=0;
   ELSE RAISE EXCEPTION 'Invalid reviewed product' USING ERRCODE='PA001';END IF;
  END;
  IF psms_aoq_api.round2_v1(product)<>psms_aoq_api.round2_v1(amount) THEN
   RAISE EXCEPTION 'Reviewed line amount mismatch' USING ERRCODE='PA001';END IF;
  total_decimal:=total_decimal+psms_aoq_api.shortest_decimal_v1(amount);
  canonical_items:=canonical_items||jsonb_build_array(item||jsonb_build_object('qty',quantity,'unit_cost',price,'amount',amount));
 END LOOP;
 BEGIN total:=psms_aoq_api.round2_v1(total_decimal::double precision);
 EXCEPTION WHEN numeric_value_out_of_range THEN RAISE EXCEPTION 'Invalid reviewed total' USING ERRCODE='PA001';END;
 IF total<=0 THEN RAISE EXCEPTION 'Reviewed total must be positive' USING ERRCODE='PA001';END IF;
 IF has_quotes THEN
  reviewed_signature:=psms_aoq_api.signature_v1(p_reviewed_items);
  expected_signature:=psms_aoq_api.signature_v1(coalesce(original->(index_number)->'items','[]'));
  IF target='custom' THEN expected_signature:='[]';END IF;
  IF reviewed_signature IS DISTINCT FROM expected_signature THEN
   FOR supplier,index_number IN SELECT value,(ordinality-1)::integer FROM jsonb_array_elements(original) WITH ORDINALITY LOOP
    IF index_number::text<>target AND jsonb_array_length(coalesce(nullif(supplier->'items','null'::jsonb),'[]'))>0
     AND reviewed_signature=psms_aoq_api.signature_v1(supplier->'items') THEN
     RAISE EXCEPTION 'Offer belongs to another supplier' USING ERRCODE='PA001';END IF;
   END LOOP;
  END IF;
 END IF;
 index_number:=coalesce(p_winner_index,-1);
 -- Owner-approved Philippine official date/year policy; one captured instant feeds both.
 save_instant:=clock_timestamp();
 stamp:=save_instant AT TIME ZONE 'Asia/Manila';
 display_date:=to_char(stamp,'Mon DD, YYYY HH12:MI AM');
 key:='AOQ:'||extract(year FROM stamp)::integer::text;
 INSERT INTO public.identifier_sequence AS counter(sequence_key,last_number) VALUES(key,1)
  ON CONFLICT(sequence_key) DO UPDATE SET last_number=counter.last_number+1 RETURNING last_number INTO number;
 LOOP
  document_no:='AOQ-'||extract(year FROM stamp)::integer::text||'-'||lpad(number::text,greatest(4,length(number::text)),'0');
  EXIT WHEN NOT EXISTS(SELECT 1 FROM public.aoq a WHERE a.no=document_no);
  UPDATE public.identifier_sequence SET last_number=last_number+1 WHERE sequence_key=key RETURNING last_number INTO number;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(canonical_items) LOOP
  item:=item||jsonb_build_object('_AOQ Item ID',document_no||'-ITEM-'||lpad((jsonb_array_length(items)+1)::text,2,'0'));
  -- Python width is a minimum, not a truncation limit (items 100 through 200).
  IF jsonb_array_length(items)>=99 THEN item:=item||jsonb_build_object('_AOQ Item ID',document_no||'-ITEM-'||(jsonb_array_length(items)+1)::text);END IF;
  items:=items||jsonb_build_array(item);
 END LOOP;
 original:=suppliers;suppliers:='[]';
 FOR supplier,n IN SELECT value,(ordinality-1)::integer FROM jsonb_array_elements(original) WITH ORDINALITY LOOP
  IF n=index_number OR psms_aoq_api.supplier_key_v1(supplier->>'supplier')=normalized_winner THEN
   supplier:=supplier||jsonb_build_object('is_winner',true,'items',items,'amount',total);matched:=true;END IF;
  suppliers:=suppliers||jsonb_build_array(supplier);
 END LOOP;
 IF NOT matched THEN suppliers:=suppliers||jsonb_build_array(jsonb_build_object('supplier',winner,'amount',total,'remarks',notes,'is_winner',true,'items',items));END IF;
 encoded_suppliers:=suppliers::text;encoded_items:=items::text;
 IF octet_length(encoded_suppliers)>4194304 OR octet_length(encoded_items)>4194304 THEN
  RAISE EXCEPTION 'Review limit exceeded' USING ERRCODE='PA001';END IF;
 profile:=jsonb_build_object('document_type',draft.payload->'document_type','extraction_method',draft.payload->'extraction_method',
  'selected_source_indices',p_selected_indices,'selection_version',2,
  'confidence',draft.payload->'confidence','table_count',draft.payload->'table_count',
  'parsed_table_sources',draft.payload->'parsed_table_sources','detected_tables',draft.payload->'detected_tables');
 INSERT INTO public.aoq(no,pr_id,status,created_at,suppliers,winner,winning_amount,winning_offer,ocr_filename,ocr_text,
  stored_filename,source_type,extraction_method,extraction_profile,extraction_warnings)
 VALUES(document_no,parent_id,'For Review',display_date,encoded_suppliers,winner,total,encoded_items,
  coalesce(draft.payload->>'ocr_filename',''),coalesce(draft.payload->>'raw_text',''),'',
  coalesce(draft.payload->>'document_type',''),coalesce(draft.payload->>'extraction_method',''),profile::text,
  coalesce(nullif(draft.payload->'warnings','null'::jsonb),'[]')::text) RETURNING id INTO official_id;
 UPDATE psms_documents.aoq_drafts SET status='CONFIRMED',official_aoq_id=official_id,
  revision=revision+1,updated_at=save_instant WHERE id=p_draft_id AND owner_id=actor_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='PA002';END IF;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(display_date,actor_name,'Created AOQ from Confirmed OCR','AOQ',document_no,'Private document review operation');
 RETURN QUERY SELECT official_id,document_no,true,draft.revision+1;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.shortest_decimal_v1(f double precision)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET standard_conforming_strings TO 'on'
AS $function$
DECLARE b bytea; exponent integer; mantissa numeric; shift integer; numerator numeric; denominator numeric:=1;
 decimal_exponent integer; scale_places integer; factor numeric; scaled_n numeric; scaled_d numeric;
 quotient numeric; remainder numeric; candidate numeric; candidate_float double precision; digits text; i integer; precision_digits integer;
BEGIN
 IF f::text IN ('Infinity','-Infinity','NaN') THEN RAISE EXCEPTION 'Invalid reviewed number' USING ERRCODE='PA001';END IF;
 IF f=0 THEN RETURN 0;END IF;
 -- PostgreSQL shortest output excludes decimal midpoint strings; Python repr does not.
 -- Find the shortest significant-digit decimal that round-trips, choosing nearest/even.
 -- All comparisons and integer remainders use the exact binary64 rational.
 b:=float8send(f);exponent:=((get_byte(b,0)&127)*16)+(get_byte(b,1)>>4);mantissa:=get_byte(b,1)&15;
 FOR i IN 2..7 LOOP mantissa:=mantissa*256+get_byte(b,i);END LOOP;
 IF exponent=0 THEN shift:=-1074;ELSE mantissa:=mantissa+4503599627370496;shift:=exponent-1075;END IF;
 numerator:=mantissa;
 IF shift>=0 THEN FOR i IN 1..shift LOOP numerator:=numerator*2;END LOOP;
 ELSE FOR i IN 1..(-shift) LOOP denominator:=denominator*2;END LOOP;END IF;
 decimal_exponent:=length(numerator::text)-length(denominator::text);
 factor:=('1'||repeat('0',abs(decimal_exponent)))::numeric;
 IF (decimal_exponent>=0 AND numerator<denominator*factor)
  OR (decimal_exponent<0 AND numerator*factor<denominator) THEN decimal_exponent:=decimal_exponent-1;END IF;
 FOR precision_digits IN 1..17 LOOP
  scale_places:=precision_digits-1-decimal_exponent;
  factor:=('1'||repeat('0',abs(scale_places)))::numeric;
  IF scale_places>=0 THEN scaled_n:=numerator*factor;scaled_d:=denominator;
  ELSE scaled_n:=numerator;scaled_d:=denominator*factor;END IF;
  quotient:=div(scaled_n,scaled_d);remainder:=mod(scaled_n,scaled_d);
  IF remainder*2>scaled_d OR (remainder*2=scaled_d AND mod(quotient,2)=1) THEN quotient:=quotient+1;END IF;
  IF scale_places<=0 THEN candidate:=quotient*factor;
  ELSE
   digits:=quotient::text;
   IF length(digits)<=scale_places THEN candidate:=('0.'||repeat('0',scale_places-length(digits))||digits)::numeric;
   ELSE candidate:=(left(digits,length(digits)-scale_places)||'.'||right(digits,scale_places))::numeric;END IF;
  END IF;
  BEGIN candidate_float:=candidate::double precision;
  EXCEPTION WHEN numeric_value_out_of_range THEN CONTINUE;END;
  IF candidate_float=abs(f) THEN RETURN CASE WHEN f<0 THEN -candidate ELSE candidate END;END IF;
 END LOOP;
 RAISE EXCEPTION 'Numeric compatibility unavailable' USING ERRCODE='PA001';
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.signature_v1(rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET standard_conforming_strings TO 'on'
 SET extra_float_digits TO '1'
AS $function$
DECLARE row jsonb; answer jsonb:='[]'; fields jsonb; k text; f double precision; t text;
BEGIN
 IF jsonb_typeof(rows) IS DISTINCT FROM 'array' THEN RETURN NULL;END IF;
 FOR row IN SELECT value FROM jsonb_array_elements(rows) LOOP
  IF jsonb_typeof(row)<>'object' THEN RETURN NULL;END IF;
  fields:='[]';
  FOREACH k IN ARRAY ARRAY['item','description','qty','unit','unit_cost','amount'] LOOP
   IF k IN ('qty','unit_cost','amount') THEN
    f:=psms_aoq_api.number_v1(row->k);
    -- Numeric JSON equality gives the same equivalence as Python str(float) for finite values.
    -- Signed zero is significant to Python str; retain it in the signature.
    fields:=fields||jsonb_build_array(CASE WHEN f IS NULL THEN '"INVALID"'::jsonb
        WHEN f=0 AND get_byte(float8send(f),0)>=128 THEN '"NEGATIVE_ZERO"'::jsonb ELSE to_jsonb(f) END);
   ELSE
    t:=coalesce(row->>k,'');
    IF row->k IN ('false'::jsonb,'0'::jsonb,'[]'::jsonb,'{}'::jsonb) THEN t:='';END IF;
    fields:=fields||jsonb_build_array(psms_aoq_api.unicode_v1(psms_aoq_api.space_v1(t),'fold'));
   END IF;
  END LOOP;
  answer:=answer||jsonb_build_array(fields);
 END LOOP;
 -- Equality only: sorting JSON arrays in both operands preserves row multiplicity/order independence.
 RETURN (SELECT coalesce(jsonb_agg(value ORDER BY value),'[]') FROM jsonb_array_elements(answer));
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.space_v1(t text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET standard_conforming_strings TO 'on'
AS $function$
DECLARE spaces text:='"\t\n\u000b\f\r\u001c\u001d\u001e\u001f \u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000"'::jsonb #>> '{}'; answer text:=''; ch text; pending boolean:=false; i integer;
BEGIN
 FOR i IN 1..length(t) LOOP
  ch:=substr(t,i,1);
  IF position(ch IN spaces)>0 THEN pending:=answer<>'';
  ELSE answer:=answer||CASE WHEN pending THEN ' ' ELSE '' END||ch;pending:=false;
  END IF;
 END LOOP;
 RETURN answer;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.strip_v1(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET standard_conforming_strings TO 'on'
AS $function$
 SELECT btrim(t,'"\t\n\u000b\f\r\u001c\u001d\u001e\u001f \u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000"'::jsonb #>> '{}')
$function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.supplier_key_v1(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET standard_conforming_strings TO 'on'
AS $function$
 SELECT btrim(regexp_replace(psms_aoq_api.unicode_v1(t,'lower') COLLATE "C",'[^a-z0-9]+',' ','g'))
$function$;

