", "\ud807\udc51": "1", "\ud807\udc52": "2", "\ud807\udc53": "3", "\ud807\udc54": "4", "\ud807\udc55": "5", "\ud807\udc56": "6", "\ud807\udc57": "7", "\ud807\udc58": "8", "\ud807\udc59": "9", "\ud807\udd50": "0", "\ud807\udd51": "1", "\ud807\udd52": "2", "\ud807\udd53": "3", "\ud807\udd54": "4", "\ud807\udd55": "5", "\ud807\udd56": "6", "\ud807\udd57": "7", "\ud807\udd58": "8", "\ud807\udd59": "9", "\ud807\udda0": "0", "\ud807\udda1": "1", "\ud807\udda2": "2", "\ud807\udda3": "3", "\ud807\udda4": "4", "\ud807\udda5": "5", "\ud807\udda6": "6", "\ud807\udda7": "7", "\ud807\udda8": "8", "\ud807\udda9": "9", "\ud81a\ude60": "0", "\ud81a\ude61": "1", "\ud81a\ude62": "2", "\ud81a\ude63": "3", "\ud81a\ude64": "4", "\ud81a\ude65": "5", "\ud81a\ude66": "6", "\ud81a\ude67": "7", "\ud81a\ude68": "8", "\ud81a\ude69": "9", "\ud81a\udec0": "0", "\ud81a\udec1": "1", "\ud81a\udec2": "2", "\ud81a\udec3": "3", "\ud81a\udec4": "4", "\ud81a\udec5": "5", "\ud81a\udec6": "6", "\ud81a\udec7": "7", "\ud81a\udec8": "8", "\ud81a\udec9": "9", "\ud81a\udf50": "0", "\ud81a\udf51": "1", "\ud81a\udf52": "2", "\ud81a\udf53": "3", "\ud81a\udf54": "4", "\ud81a\udf55": "5", "\ud81a\udf56": "6", "\ud81a\udf57": "7", "\ud81a\udf58": "8", "\ud81a\udf59": "9", "\ud835\udfce": "0", "\ud835\udfcf": "1", "\ud835\udfd0": "2", "\ud835\udfd1": "3", "\ud835\udfd2": "4", "\ud835\udfd3": "5", "\ud835\udfd4": "6", "\ud835\udfd5": "7", "\ud835\udfd6": "8", "\ud835\udfd7": "9", "\ud835\udfd8": "0", "\ud835\udfd9": "1", "\ud835\udfda": "2", "\ud835\udfdb": "3", "\ud835\udfdc": "4", "\ud835\udfdd": "5", "\ud835\udfde": "6", "\ud835\udfdf": "7", "\ud835\udfe0": "8", "\ud835\udfe1": "9", "\ud835\udfe2": "0", "\ud835\udfe3": "1", "\ud835\udfe4": "2", "\ud835\udfe5": "3", "\ud835\udfe6": "4", "\ud835\udfe7": "5", "\ud835\udfe8": "6", "\ud835\udfe9": "7", "\ud835\udfea": "8", "\ud835\udfeb": "9", "\ud835\udfec": "0", "\ud835\udfed": "1", "\ud835\udfee": "2", "\ud835\udfef": "3", "\ud835\udff0": "4", "\ud835\udff1": "5", "\