 FOR i IN 1..length(t) LOOP
  ch:=substr(t,i,1); answer:=answer||coalesce(mapping->>ch,ch);
 END LOOP;
 RETURN answer;
END $function$;

CREATE OR REPLACE FUNCTION psms_aoq_api.workflow_offer_v1(p_offer text, p_winner text, p_winning_amount double precision)
 RETURNS TABLE(items_text text, total double precision)
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET standard_conforming_strings TO 'on'
 SET extra_float_digits TO '1'
AS $function$
DECLARE
 rows json; item json; field_name text; raw_value json; field_value json; pair record;
 quantity double precision; price double precision; amount double precision; product double precision;
 f double precision; sum_decimal numeric:=0; sum_float double precision; expected double precision;
 fields text; output_text text:=''; numeric_text text; item_count integer:=0;
BEGIN
 BEGIN rows:=p_offer::json;
 EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'Invalid reviewed offer' USING ERRCODE='PA001';END;
 IF json_typeof(rows) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'Invalid reviewed offer' USING ERRCODE='PA001';END IF;
 IF json_array_length(rows)=0 THEN
  RAISE EXCEPTION 'Invalid reviewed offer' USING ERRCODE='PA001';END IF;
 IF p_winner IS NULL OR psms_aoq_api.strip_v1(p_winner)='' THEN
  RAISE EXCEPTION 'Winning supplier required' USING ERRCODE='PA001';END IF;
 FOR item IN SELECT value FROM json_array_elements(rows) LOOP
  IF json_typeof(item) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'Invalid reviewed offer' USING ERRCODE='PA001';END IF;
  FOREACH field_name IN ARRAY ARRAY['item','description','unit'] LOOP
   IF json_typeof(item->field_name) IS DISTINCT FROM 'string' OR psms_aoq_api.strip_v1(item->>field_name)='' THEN
    RAISE EXCEPTION 'Incomplete reviewed offer' USING ERRCODE='PA001';END IF;
  END LOOP;
  FOREACH field_name IN ARRAY ARRAY['qty','unit_cost','amount'] LOOP
   raw_value:=item->field_name;
   -- json retains numeric -0.0 spelling, unlike jsonb. Parse numeric tokens as text.
   f:=psms_aoq_api.number_v1(CASE WHEN json_typeof(raw_value)='number' THEN to_jsonb(raw_value::text) ELSE raw_value::jsonb END);
   IF f IS NULL OR f<0 THEN RAISE EXCEPTION 'Invalid reviewed numbers' USING ERRCODE='PA001';END IF;
   IF field_name='qty' THEN quantity:=f;ELSIF field_name='unit_cost' THEN price:=f;ELSE amount:=f;END IF;
  END LOOP;
  BEGIN product:=quantity*price;
  EXCEPTION WHEN numeric_value_out_of_range THEN
   IF quantity<1 AND price<1 THEN product:=0;
   ELSE RAISE EXCEPTION 'Invalid reviewed numbers' USING ERRCODE='PA001';END IF;
  END;
  IF product::text IN ('Infinity','-Infinity','NaN')
   OR psms_aoq_api.round2_v1(product)<>psms_aoq_api.round2_v1(amount) THEN
   RAISE EXCEPTION 'Inconsistent reviewed amounts' USING ERRCODE='PA001';END IF;
  sum_decimal:=sum_decimal+psms_aoq_api.shortest_decimal_v1(amount);
  fields:='';
  FOR pair IN SELECT key,value FROM json_each(item) LOOP
   IF fields<>'' THEN fields:=fields||',';END IF;
   fields:=fields||to_json(pair.key)::text||':';
   IF pair.key IN ('qty','unit_cost','amount') THEN
    f:=CASE pair.key WHEN 'qty' THEN quantity WHEN 'unit_cost' THEN price ELSE amount END;
    IF f=0 AND get_byte(float8send(f),0)>=128 THEN numeric_text:='-0.0';
    ELSE
     numeric_text:=psms_aoq_api.shortest_decimal_v1(f)::text;
     -- Preserve Python JSON float types, important to unchanged NLP text construction.
     IF position('.' IN numeric_text)=0 AND position('e' IN lower(numeric_text))=0 THEN numeric_text:=numeric_text||'.0';END IF;
    END IF;
    fields:=fields||numeric_text;
   ELSE fields:=fields||pair.value::text;END IF;
  END LOOP;
  IF item_count>0 THEN output_text:=output_text||',';END IF;
  output_text:=output_text||'{'||fields||'}';item_count:=item_count+1;
 END LOOP;
 BEGIN sum_float:=sum_decimal::double precision;
 EXCEPTION WHEN numeric_value_out_of_range THEN RAISE EXCEPTION 'Invalid reviewed total' USING ERRCODE='PA001';END;
 expected:=psms_aoq_api.number_v1(to_jsonb(p_winning_amount));
 IF expected IS NULL OR expected<0 OR sum_float::text IN ('Infinity','-Infinity','NaN')
  OR psms_aoq_api.round2_v1(expected)<>psms_aoq_api.round2_v1(sum_float) THEN
  RAISE EXCEPTION 'Inconsistent reviewed total' USING ERRCODE='PA001';END IF;
 RETURN QUERY SELECT '['||output_text||']',sum_float;
END $function$;

-- psms_documents routines
CREATE OR REPLACE FUNCTION psms_documents.configure_backend(role_name text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare target record; relation text;
begin
 select * into target from pg_catalog.pg_roles where rolname=role_name;
 if not found or not target.rolcanlogin or target.rolsuper or target.rolbypassrls or target.rolcreatedb
  or target.rolcreaterole or target.rolinherit or lower(role_name) in ('anon','authenticated','service_role','postgres')
  or role_name like 'pg_%' or exists(select 1 from pg_auth_members where roleid=target.oid or member=target.oid)
  or exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace
   where n.nspname in ('public','psms_signatories','psms_documents') and c.relowner=target.oid) then
  raise exception 'Reviewed nonprivileged backend required'; end if;
 execute format('grant usage on schema psms_documents to %I',role_name);
 execute format('grant select,insert on psms_documents.sources to %I',role_name);
 execute format('grant select,insert,update on psms_documents.aoq_drafts to %I',role_name);
 foreach relation in array array['sources','aoq_drafts'] loop
  execute format('create policy %I on psms_documents.%I for all to %I using(true) with check(true)','backend_'||role_name,relation,role_name);
 end loop;
 execute format('grant select on psms_signatories.legacy_evidence to %I',role_name);
 execute format('create policy %I on psms_signatories.legacy_evidence for select to %I using(true)','backend_'||role_name,role_name);
 execute format('grant execute on function psms_signatories.record_verified_archive(text,bigint,text,jsonb,bytea,text,jsonb,text,uuid) to %I',role_name);
end;
$function$;

-- psms_revised_release routines
CREATE OR REPLACE FUNCTION psms_revised_release.approve_po_after_verification_v1(p_po_id bigint, p_review_confirm boolean, p_final_confirm boolean)
 RETURNS TABLE(po_id bigint, new_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'on'
 SET "TimeZone" TO 'UTC'
 SET lc_time TO 'C'
 SET lock_timeout TO '5s'
AS $function$
DECLARE v_actor record;v_preview record;v_aoq record;v_pr record;v_po record;v_review record;v_nlp record;v_hash text;
BEGIN
 PERFORM psms_revised_release.require_release_v1();
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Read committed required' USING ERRCODE='PA002';END IF;
 SELECT * INTO STRICT v_actor FROM psms_aoq_api.approval_actor_v1();
 SELECT aoq_id,pr_id INTO v_preview FROM public.po WHERE id=p_po_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'PO unavailable' USING ERRCODE='PA004';END IF;
 SELECT id,pr_id,status INTO v_aoq FROM public.aoq WHERE id=v_preview.aoq_id FOR SHARE;
 SELECT id,no,status,items,app_id,ppmp_id,office INTO v_pr FROM public.pr WHERE id=v_preview.pr_id FOR SHARE;
 SELECT id,no,aoq_id,pr_id,status,items INTO v_po FROM public.po WHERE id=p_po_id FOR UPDATE;
 SELECT proof.* INTO v_review FROM psms_documents.pr_po_reviews AS proof WHERE proof.po_id=p_po_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Authorized PR-PO relationship required before final PO approval' USING ERRCODE='PA002';END IF;
 SELECT verification.id,verification.no,verification.po_id,verification.pr_id,verification.workflow_version,verification.status,
  verification.result,verification.confidence,verification.details,verification.technical_status,verification.model_version,
  verification.pr_items_hash,verification.po_items_hash INTO v_nlp FROM public.nlp AS verification WHERE verification.id=v_review.nlp_id FOR SHARE;
 IF p_review_confirm IS DISTINCT FROM true OR p_final_confirm IS DISTINCT FROM true
  OR v_po.status IS DISTINCT FROM 'For Review' OR v_pr.status IS DISTINCT FROM 'Approved'
  OR v_aoq.status IS DISTINCT FROM 'Approved' OR v_po.aoq_id IS DISTINCT FROM v_preview.aoq_id
  OR v_po.pr_id IS DISTINCT FROM v_review.pr_id OR v_pr.id IS DISTINCT FROM v_review.pr_id
  OR (v_aoq.pr_id IS NOT NULL AND v_aoq.pr_id IS DISTINCT FROM v_review.pr_id)
  OR v_nlp.status IS DISTINCT FROM 'Approved' OR v_nlp.result IS NULL OR v_nlp.result NOT IN ('Acceptable','Needs Review')
  OR v_nlp.technical_status IS DISTINCT FROM 'MATCH' OR v_nlp.po_id IS DISTINCT FROM v_po.id
  OR v_nlp.pr_id IS DISTINCT FROM v_pr.id THEN
  RAISE EXCEPTION 'Confirmed reviewed procurement relationship required' USING ERRCODE='PA002';END IF;
 IF v_nlp.details::jsonb->'reviewed_procurement_context' IS DISTINCT FROM
   jsonb_build_object('pr_app_id',v_pr.app_id,'pr_ppmp_id',v_pr.ppmp_id,'pr_office',v_pr.office) THEN
  RAISE EXCEPTION 'Reviewed procurement scope changed' USING ERRCODE='PA002';END IF;
 IF v_aoq.pr_id IS NULL THEN
  PERFORM 1 FROM public.app_plan a JOIN public.ppmp m ON m.id=a.ppmp_id
   WHERE a.id=v_pr.app_id AND a.status='Approved' AND m.status='Approved'
    AND (v_pr.ppmp_id IS NULL OR v_pr.ppmp_id=m.id) FOR SHARE OF a,m;
  IF NOT FOUND THEN RAISE EXCEPTION 'Approved planning evidence changed' USING ERRCODE='PA006';END IF;
 END IF;
 IF v_review.pr_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_pr.items,''),'UTF8')),'hex')
  OR v_review.po_items_hash IS DISTINCT FROM encode(sha256(convert_to(coalesce(v_po.items,''),'UTF8')),'hex') THEN
  RAISE EXCEPTION 'Reviewed documents changed' USING ERRCODE='PA002';END IF;
 v_hash:=encode(sha256(convert_to(jsonb_build_array(v_nlp.pr_id,v_nlp.po_id,v_nlp.result,v_nlp.confidence,v_nlp.details,
  v_nlp.technical_status,v_nlp.model_version,v_nlp.pr_items_hash,v_nlp.po_items_hash)::text,'UTF8')),'hex');
 IF v_hash IS DISTINCT FROM v_review.nlp_hash THEN RAISE EXCEPTION 'Reviewed verification changed' USING ERRCODE='PA002';END IF;
 PERFORM psms_revised_release.require_saved_technical_match_v2(v_nlp.technical_status,
  v_nlp.details::jsonb->'technical_comparison',v_review.item_mapping,
  v_nlp.details::jsonb->'reviewed_technical_checks');
 -- The existing Python signatory adapter binds context only for direct UPDATE
 -- statements. This secure SELECT/RPC path must bind the same validated actor
 -- before the existing approval trigger runs; never bypass that trigger.
 PERFORM set_config('psms.signatory_actor',jsonb_build_object('user_id',v_actor.actor_id,
  'sid',(nullif(current_setting('psms.workbook_actor',true),'')::jsonb)->>'sid')::text,true);
 UPDATE public.po SET status='Approved' WHERE id=p_po_id;
 INSERT INTO public.audit_trail(dt,"user",action,module,ref,details)
 VALUES(to_char(clock_timestamp() AT TIME ZONE 'Asia/Manila','Mon DD, YYYY HH12:MI AM'),v_actor.actor_username,
  'Approved PO','PO',v_po.no,'Final approval after authorized PR-PO relationship and human NLP review');
 RETURN QUERY SELECT p_po_id,'Approved'::text;
END $function$;

