-- psms_signatories routines
CREATE OR REPLACE FUNCTION psms_signatories.capture_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare actor jsonb; actor_user record; slots text[]; kind text; identities jsonb; revision bigint;
begin
  if new.status is distinct from 'Approved' then return new; end if;
  if TG_OP='UPDATE' and old.status='Approved' then return new; end if;
  -- Bound to this transaction only by the candidate connection adapter. Validate
  -- against the real active registry; neither cookie role nor posted IDs suffice.
  actor:=nullif(current_setting('psms.signatory_actor',true),'')::jsonb;
  if actor is null or coalesce(actor->>'sid','') !~ '^[0-9a-f]{64}$'
      or coalesce(actor->>'user_id','') !~ '^[1-9][0-9]{0,18}$' then
    raise exception 'Authenticated approval context is required' using errcode='42501';
  end if;
  select u.id,u.username into actor_user from public.users u
    join public.auth_sessions s on s.user_id=u.id
    where u.id=(actor->>'user_id')::bigint and s.token_hash=actor->>'sid'
      and u.status='Active' and u.role in ('Admin','Staff','Inspector')
      and s.revoked_at is null and s.expires_at>clock_timestamp();
  if not found then
    raise exception 'Authenticated approval context is unavailable' using errcode='42501';
  end if;
  case TG_TABLE_NAME
    when 'ppmp' then kind:='ppmp'; slots:=array['ppmp_prepared','ppmp_approved'];
    when 'app_plan' then kind:='app'; slots:=array['app_prepared','app_approved'];
    when 'pr' then kind:='pr'; slots:=array['pr_requested','pr_approved'];
    when 'po' then kind:='po'; slots:=array['po_authorized'];
    when 'iar' then kind:='iar'; slots:=array['iar_inspection','iar_acceptance'];
    when 'ris_ics' then
      if new.type not in ('RIS','ICS') then raise exception 'Invalid document type'; end if;
      kind:=lower(new.type); slots:=array['ris_issued','ris_received'];
    else raise exception 'Unsupported document type';
  end case;
  -- Every Admin mutation locks this row FOR UPDATE. Approval holds FOR SHARE
  -- until its own status/inventory/audit transaction commits or rolls back.
  select c.revision into strict revision from psms_signatories.config_state c where id=1 for share;
  select jsonb_object_agg(field,jsonb_build_object(
      'person_id',p.id,'name',coalesce(p.full_name,''),'position',coalesce(p.position,''),
      'office',coalesce(p.office,''),'person_revision',p.revision,
      'signature_version',null,'signature_authorized',false)) into identities
    from unnest(slots) field left join psms_signatories.assignments a on a.slot=field
    left join psms_signatories.people p on p.id=a.person_id and p.active
      and p.effective_from<=current_date and (p.effective_to is null or p.effective_to>=current_date);
  insert into psms_signatories.document_snapshots
    (document_kind,document_id,document_no,actor_id,config_revision,identities)
    values(kind,new.id,coalesce(new.no,''),actor_user.id,revision,identities);
  -- Do not silently replace an existing snapshot on retries/reapproval. Evidence
  -- and this generic audit entry commit/roll back with the existing approval.
  insert into public.audit_trail(dt,"user",action,module,ref,details)
    values(clock_timestamp()::text,actor_user.username,'Captured Signatory Snapshot',
           'Authorized Signatories',kind||':'||new.id::text,
           'Identity snapshot captured; no signature image applied');
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION psms_signatories.configure_backend(role_name text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare target record; relation text;
begin
  select * into target from pg_catalog.pg_roles where rolname=role_name;
  if not found or not target.rolcanlogin or target.rolsuper or target.rolbypassrls
    or target.rolcreatedb or target.rolcreaterole or target.rolinherit
    or lower(role_name) in ('anon','authenticated','service_role','postgres')
    or role_name like 'pg_%'
    or exists(select 1 from pg_catalog.pg_auth_members m where m.roleid=target.oid or m.member=target.oid)
    or exists(select 1 from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
      where n.nspname in ('public','psms_signatories') and c.relowner=target.oid) then
    raise exception 'A reviewed distinct nonprivileged backend role is required';
  end if;
  execute format('grant usage on schema psms_signatories to %I',role_name);
  foreach relation in array array['config_state','people','signature_versions','assignments','change_history','document_snapshots'] loop
    execute format('grant select on psms_signatories.%I to %I',relation,role_name);
    execute format('create policy %I on psms_signatories.%I for all to %I using(true) with check(true)',
      'backend_'||role_name,relation,role_name);
  end loop;
  execute format('grant update on psms_signatories.config_state to %I',role_name);
  execute format('grant insert,update on psms_signatories.people to %I',role_name);
  execute format('grant insert on psms_signatories.signature_versions,psms_signatories.change_history to %I',role_name);
  execute format('grant insert,update,delete on psms_signatories.assignments to %I',role_name);
end;
$function$;

CREATE OR REPLACE FUNCTION psms_signatories.immutable_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
begin
  raise exception 'Signatory evidence is immutable' using errcode='42501';
end;
$function$;

CREATE OR REPLACE FUNCTION psms_signatories.record_verified_archive(kind text, doc_id bigint, doc_no text, identities jsonb, original_pdf bytea, digest text, quotes jsonb, note text, evidence_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare actor jsonb; actor_user record; table_name text; target record;
begin
 actor:=nullif(current_setting('psms.signatory_actor',true),'')::jsonb;
 if actor is null or coalesce(actor->>'user_id','') !~ '^[1-9][0-9]{0,18}$'
  or coalesce(actor->>'sid','') !~ '^[0-9a-f]{64}$' then
  raise exception 'Active Administrator context required' using errcode='42501'; end if;
 select id,username into actor_user from public.users
  where id=(actor->>'user_id')::bigint and role='Admin' and status='Active' for share;
 if not found then raise exception 'Active Administrator required' using errcode='42501'; end if;
 perform 1 from public.auth_sessions where user_id=actor_user.id and token_hash=actor->>'sid'
  and revoked_at is null and expires_at>clock_timestamp() for share;
 if not found then raise exception 'Active session required' using errcode='42501'; end if;
 table_name:=case kind when 'ppmp' then 'ppmp' when 'app' then 'app_plan' when 'pr' then 'pr'
  when 'po' then 'po' when 'iar' then 'iar' when 'ris' then 'ris_ics' when 'ics' then 'ris_ics' end;
 if table_name is null then raise exception 'Invalid document kind'; end if;
 execute format('select id,no,status from public.%I where id=$1 for share',table_name) into target using doc_id;
 if target.id is null or target.no is distinct from doc_no or target.status is distinct from 'Approved' then
  raise exception 'Approved historical document identity does not match'; end if;
 if kind in ('ris','ics') then
  perform 1 from public.ris_ics where id=doc_id and lower(type)=kind;
  if not found then raise exception 'Document kind does not match'; end if;
 end if;
 if exists(select 1 from psms_signatories.document_snapshots s where s.document_kind=kind and s.document_id=doc_id) then
  raise exception 'Historical evidence already exists' using errcode='23505'; end if;
 if jsonb_typeof(identities)<>'object' or jsonb_typeof(quotes)<>'array' or length(btrim(note)) not between 1 and 1000 then
  raise exception 'Verified source evidence is required'; end if;
 insert into psms_signatories.legacy_evidence(id,document_kind,document_id,original_pdf,sha256,source_quotes,verification_note,verified_by)
  values(evidence_id,kind,doc_id,original_pdf,digest,quotes,note,actor_user.id);
 insert into psms_signatories.document_snapshots(document_kind,document_id,document_no,actor_id,config_revision,identities,origin,legacy_evidence_id)
  values(kind,doc_id,doc_no,actor_user.id,-1,identities,'verified_archive',evidence_id);
 insert into psms_signatories.change_history(id,actor_id,action,reference,detail)
  values(evidence_id,actor_user.id,'Recorded Verified Historical Evidence',kind||':'||doc_id,
   jsonb_build_object('archive_sha256',digest,'approval_timestamp_reconstructed',false,'signature_placement_authorized',false));
 insert into public.audit_trail(dt,"user",action,module,ref,details)
  values(clock_timestamp()::text,actor_user.username,'Recorded Verified Historical Evidence','Authorized Signatories',kind||':'||doc_id,
   'Historical identity reconstruction with retained archive; original approval unchanged; no image applied');
end;
$function$;

-- psms_sync routines
CREATE OR REPLACE FUNCTION psms_sync.read_versions(requested text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE uid bigint; actor_role text; topic text; key text; state jsonb; result jsonb:='{}';
BEGIN
 uid:=psms_workbooks.active_actor_id();
 SELECT role INTO actor_role FROM public.users WHERE id=uid AND status='Active';
 IF uid IS NULL OR actor_role IS NULL OR actor_role NOT IN ('Admin','Staff','Inspector') THEN
   RAISE EXCEPTION 'Active authenticated actor required' USING ERRCODE='42501';
 END IF;
 IF requested IS NULL OR cardinality(requested)>14 THEN RAISE EXCEPTION 'Invalid topics'; END IF;
 SELECT values_json INTO state FROM psms_sync.revisions WHERE singleton;
 FOREACH topic IN ARRAY requested LOOP
   IF topic IS NULL OR topic NOT IN ('ppmp','app','pr','aoq','po','nlp','iar','inventory','ris','dataset','documents','account','users','audit')
      OR (topic='users' AND actor_role<>'Admin') THEN
     RAISE EXCEPTION 'Unauthorized topic' USING ERRCODE='42501';
   END IF;
   key:=topic||':'||CASE WHEN topic IN ('documents','account') THEN uid::text ELSE '0' END;
   result:=result||jsonb_build_object(topic,coalesce(state->>key,'0'));
 END LOOP;
 RETURN result;
END;$function$;

CREATE OR REPLACE FUNCTION psms_sync.record_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE data jsonb; owner_id bigint:=0; topic text; key text; keys text[];
        touched text:=coalesce(current_setting('psms.sync_touched',true),'');
BEGIN
 IF TG_OP='DELETE' THEN data:=to_jsonb(OLD); ELSE data:=to_jsonb(NEW); END IF;
 topic:=TG_ARGV[0];
 IF TG_ARGV[1]<>'' THEN owner_id:=coalesce((data->>TG_ARGV[1])::bigint,0); END IF;
 keys:=ARRAY[topic||':'||owner_id::text];
 IF TG_TABLE_SCHEMA='public' AND TG_TABLE_NAME='users' THEN
   keys:=keys||ARRAY['account:'||(data->>'id')];
 END IF;
 FOREACH key IN ARRAY keys LOOP
   IF strpos(touched,'|'||key||'|')=0 THEN
     UPDATE psms_sync.revisions SET values_json=jsonb_set(values_json,ARRAY[key],
       to_jsonb(coalesce((values_json->>key)::bigint,0)+1),true) WHERE singleton;
     touched:=touched||'|'||key||'|';
   END IF;
 END LOOP;
 PERFORM set_config('psms.sync_touched',touched,true);
 RETURN NULL;
END;$function$;

-- psms_workbooks routines
CREATE OR REPLACE FUNCTION psms_workbooks.active_actor_id()
 RETURNS bigint
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT u.id FROM public.users u
  JOIN public.auth_sessions s ON s.user_id=u.id
  WHERE u.id=(nullif(current_setting('psms.workbook_actor',true),'')::jsonb->>'uid')::bigint
    AND s.token_hash=(nullif(current_setting('psms.workbook_actor',true),'')::jsonb->>'sid')
    AND u.status='Active' AND u.role IN ('Admin','Staff','Inspector')
    AND s.revoked_at IS NULL AND s.expires_at>statement_timestamp()
$function$;

