CREATE INDEX idx_inventory_status ON public.inventory USING btree (status);
CREATE INDEX idx_audit_id_desc ON public.audit_trail USING btree (id DESC);
CREATE INDEX idx_ppmp_ocr_drafts_category_status ON public.ppmp_ocr_drafts USING btree (ppmp_category, status);
