CREATE INDEX recovery_user_issued ON psms_accounts.recovery_tokens USING btree (user_id, issued_at);
CREATE INDEX recovery_actor_issued ON psms_accounts.recovery_tokens USING btree (issued_by, issued_at);
CREATE INDEX otp_recent_user ON psms_accounts.otp_challenges USING btree (user_id, issued_at);
CREATE UNIQUE INDEX one_confirmed_aoq_per_pr ON psms_documents.aoq_drafts USING btree (pr_id) WHERE (status = 'CONFIRMED'::text);
