CREATE UNIQUE INDEX one_processing_run_per_source ON psms_documents.processing_runs USING btree (source_id) WHERE (status = 'PROCESSING'::text);
CREATE INDEX owner_source_processing_history ON psms_documents.processing_runs USING btree (owner_id, source_id, started_at DESC);
CREATE INDEX owner_kind_source_history ON psms_documents.sources USING btree (owner_id, kind, created_at DESC, id);

